/* 令和4年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r04.committeeSessions.push(...[{"id":"r04-20220822-5","meetingId":"r04-cm08","date":"2022年8月22日","dateIso":"2022-08-22","committee":"総務委員会","time":"午後 １時００分～午後 ２時２１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","topics":[{"id":"topic-01","title":"先ほど申し上げましたとおり、取り上げる順番を変更し、初めに、(2)南大井一丁目区営住宅外壁改修その他工事請負契約","agenda":"先ほど申し上げましたとおり、取り上げる順番を変更し、初めに、(2)南大井一丁目区営住宅外壁改修その他工事請負契約","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"すみません。ちょっと基本的なことを教えていただきたいのです。この区営住宅の築年数を教えていただきたいのと、それから外壁の改修というのは、基準としてどれくらいごとにされるのか、そういう基本的なところなのですけれど、教えてください。","respondent":"小林施設整備課長","answer":"この施設につきましては、塗装による外壁仕上げですので、現地の劣化状況等はありますが、前回の外壁改修からおよそ２０年経過していますので、適正な改修の時期なのかなというふうには認識しています。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、１５年から２０年ごとに外壁改修ということと、築５０年近く経っているのですけども、この建て替え計画というのは、おおよそどれくらいで考えられるのか、その点もちょっと伺いたいと思います。","respondent":"小林施設整備課長","answer":"建て替えのタイミングにつきまして、各所管課のほうでの様々な計画の中で検討されることかと思いますが、通常、建物は６０年とか６５年とか７０年、様々、改修の周期があるかと思いますので、その改修周期の中で検討されることかと認識しています。","id":"exchange-002"}]},{"id":"topic-02","title":"ファミーユ西五反田西館低層棟および大崎第一地域センターほか外壁改修その他工事請負契約","agenda":"ファミーユ西五反田西館低層棟および大崎第一地域センターほか外壁改修その他工事請負契約","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このファミーユ西五反田も築年数がどれくらいなのかを教えていただきたいのと、あと、これは高層棟と低層棟があって、高層棟は工事対象外になって低層棟だけというのが今回の契約みたいなのですけれども、多分同じ時期の建設だと思うのですが、なぜ今回は低層棟だけなのか。それから、今回、これも外壁改修なのですけれど、この外壁改修は前回はいつ頃されているのか、その点についても伺いたいと思います。","respondent":"小林施設整備課長","answer":"来年度以降、高層棟についても改修のための準備を進めているところでございまして、来年度予算以降でまた出てくるかというふうに思います。それと、前回の改修ですが、先ほど申し上げましたように築年数１８年ですので、外壁改修としては今回が初めての改修です。","id":"exchange-003"}]},{"id":"topic-03","title":"天王洲公園野球場ＡＢ面ナイター照明ＬＥＤ化その他工事請負契約","agenda":"天王洲公園野球場ＡＢ面ナイター照明ＬＥＤ化その他工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"ＬＥＤ化して、環境云々に対しては、電気代その他については今後のためにはいいのかもしれないのですが、ここでこれだけの金額をかけて、別に今の照明が特段傷んでいるわけではないのですが、そういう意味で、こういうふうに今回ＬＥＤ化する、これだけ費用をかけてやるということは、何かそれなりのメリットというものはあるのでしょうか。教えてください。","respondent":"東野経理課長","answer":"こちらのＬＥＤ化する前の水銀灯につきましては、耐用年数が過ぎているというような状況で、部品の交換につきましては、製造が現在行われていないということで、それに対応するためにＬＥＤ化を進めているというふうに聞いてあります。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"区有施設もこういうふうにＬＥＤ化を進めるということは、やはりそれなりに意義があると私は思うのですが、場面に応じて、それが適切なのか、費用対効果があるのかというのは、やはり今後もきちんと検討していただきたいと思います。","respondent":"東野経理課長","answer":"すみません。削減効果ですが、約５５％の削減で、年間で約４８０万円の効果があるというふうに聞いているところです。訂正します。","id":"exchange-005"},{"speaker":"吉田委員","kind":"確認","question":"今の確認なのですけれど、削減効果というのは電気代ということでいいのでしょうか。それとも、ＬＥＤ化にするということで、既存のものをまた設置するよりも、ＬＥＤのほうが削減効果があるという意味なのでしょうか。工事金額の妥当性ということのご報告ということなので、その辺を教えてください。","respondent":"東野経理課長","answer":"既存の水銀灯を年間で使った場合と、ＬＥＤに新設した場合の差が、先ほどお話ししました４８０万円ほどであるということになります。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"工事内容で、照明器具交換工事と受変電設備交換工事が２つあると思うのですけれど、それぞれ内訳を教えていただきたいと思います。ということは、この１か所に大体２４個ぐらいの投光器が付いているという感じの照明鉄塔というものになっているということでしょうか。ちょっとそこの状況が分からないので教えていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-04","title":"令和４年度都区財政調整交付金当初算定結果","agenda":"令和４年度都区財政調整交付金当初算定結果","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３ページのところで、市町村民税法人分、法人住民税が、令和４年度は４０.９％の伸びになっていますけれども、この理由がどういうことでこの伸びになっていると考えられているか、ちょっと伺いたいと思います。これは当初算定ということなので、実際はどうだったのか、ちょっとそこら辺も分かったら教えていただきたいと思います。その点を伺いたいと思います。","respondent":"黒田財政課長","answer":"令和３年度ですが、１０月以降は緊急事態宣言が解除されていまして、そういった企業活動の再開というのもかなり大きく影響したと思いますけれども、そちらのほうで再調整においてかなり法人住民税の税収が伸びたということもありまして、今回の当初フレームは。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、令和３年度の最終的な調整額のところで、今回の４０％を超えるような業績が見込まれたというか、そういう実態になったということで、今回４０％の伸びになったというふうなことで捉えていいということですか。それから、配当割交付金と株式等譲渡所得割交付金もそれぞれ２０.９％、２６.７％ということで増えていますけれど、ここの評価についても伺いたいと思います。","respondent":"黒田財政課長","answer":"基準財政収入額のほうの配当割交付金につきましては、これは前年から遡って３か年の平均を基準財政収入額として見るのですが、この３か年の傾向としましては、収益分配等が増加傾向にあるということで、前年と比較すると増えているところでございまして。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この下のほうの基準財政需要額Ｃというところの投資的経費のところも８４.７％増えて、プラスの部分だけでも１,６５２億円余も取れているのですけれど、これも令和２年度、令和３年度のもちょっと見てみたのが、これも令和２年度も令和３年度も減っていたのが、今回一気に増えているということなのです。この理由は何なのか、開発補助金ということになるのか、ちょっとその点も伺いたいと思います。","respondent":"黒田財政課長","answer":"令和４年度の、財調算定に当たりましては、昨年度、いわゆる都区の財調協議の中で、どういった項目を算定していくかというところが特に協議される中で、財源がかなり伸びてきているというようなところ、先ほども申し上げたとおり。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今の説明でも、年末に向けて再調整して改めて各区に配分されるという説明ですけれど、令和３年度の今の時期の説明資料では、令和３年度の当初算定というところでは３７１億８,８００万円余なのですけれども、最終的に品川区に来た財政調整交付金というのは再調整されて幾らになったのか、その額についても教えていただけたらと思います。","respondent":"黒田財政課長","answer":"令和３年度の当初算定につきましては、３７１億８,８００万円余でございましたが、再算定で６９億２,０００万円ほどプラスになりまして、最終的にいわゆる普通交付金の算定額としましては、４４１億円余となっておりますので、令和３年度につきましては。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"昨年の説明で、「対象とする経費の２分の１を算定」ということなのですけれど、今年度も同様になるのでしょうかということなのです。それで対象とする経費というのは具体的にどんなものが考えられるのか、その点についてもお伺いしたいと思います。それ以外に区独自に対策を取った場合なども財調算定されるものがあるのか、どういうふうに算定されるのか、伺いたいと思います。","respondent":"黒田財政課長","answer":"いわゆるそのコロナ対応につきましては、まず大本では、国の新型コロナウイルス感染症対応地方創生臨時交付金がありますので、そちらのほうで対応するというものもありますし、東京都の補助事業の中で対応するというものもございまして。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つ、児童相談所についてなのです。それから、これからどんどん児童相談所は各区が運営するようになっていくと思うのですけれど、それに対して、都区の割合を変更していくというのは、今年度、都と議論をして、もっと特別区のほうで獲得できるようにという方向でやっていくという考えで進められているのか、ちょっとそこら辺の方向性についても伺いたいと思います。","respondent":"黒田財政課長","answer":"児童相談所ですが、いわゆる建設費につきましては、特別交付金で４分の１を措置した上で、開設年度にその増額を普通交付金で算定するということでは都区の合意となってございまして、運営費につきましては、この令和４年度で言いますと。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当に児童相談所は大事なところですし、かなりの額がかかっていくと思いますので、都区の配分を変更できるというところまでぜひ進めていただきたいと思います。最後なのですけれど、事務事業概要の説明のときに、生活保護費の自治体負担分の２５％がどのように財調算定されるのかということでお聞きしたのですが、その後どういう状況なのか、分かったら教えていただきたいのです。","respondent":"黒田財政課長","answer":"いわゆるその財調の中での生活保護費につきましては、経常的経費の中で算定しておりまして、測定単位というのがあるのですが、その単位に費用の単価を掛けて需要額を出すというところなのですが、その測定単位が被保護者数となっておりますので、当然。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"これ、毎年お話を聞いて都区財政調整の算定を見ていますと、固定資産税はますます増えていく、市町村民税法人分も結局、法人の所得が上がっているということもあるから、そういう部分も増えてきて、法人事業税もこういうふうに増えてきて、企業間の格差はもちろん出ていると思うのですが、この社会情勢の変化で、交付金の総額云々は出ていますけれど、やはり財調の算定というのはずっと同じやり方で。","respondent":"黒田財政課長","answer":"その税制改正でありますとか、それから地方自治法などの制度が大きく改正された際に見直されるというものでございまして、通常その景気の動向等では、その割合は見直さないという形で合意していますので。","id":"exchange-015"},{"speaker":"須貝委員","kind":"質問","question":"ちょっと思うのですけれど、これだけ固定資産税が増えているということならば、どんどん２３区、特に都心に対しては増えている。そういう考え方というのですか、捉え方がないと、いや、固定資産税はどんどん増えています、でも今までの算定はこういうふうになっています、配分もこの割合です、変わりません。その辺についてちょっとお考えをお聞かせください。","respondent":"黒田財政課長","answer":"その財源が伸びているときの算定の方法ですが、先ほど、令和３年度は再調整がかなり品川区としても、最後に財調の交付金が増えたというご説明をいたしましたが、令和３年度の再調整の項目の中に、首都直下地震等に対する防災・減災対策ということで。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり２３区、とりわけ品川区などが率先して、きちんともっと、今までの算定は算定として、別にプラスアルファで、やはりこういう財源が、固定資産税などが伸びているなら、それはそれで、皆さんの区民のために負担してくださいよというような、やはりまちづくりを含めて、もっと主張すべきではないかなと私は思いますので、それはそういうふうに都のほうに伝えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-05","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"今の調査事項で、静岡市のほうなのですが、人材育成の取組方針がこの３ページにありますが、これももちろん、人材を育成するというのは今までも何度かやっているのですが、その人材を選ぶ、要は新人を選ぶときのポイントですか、それを教えていただければありがたいなと。これだけ、事務事業というのですか、これを出すだけでも大変なご苦労だと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"鈴木（真）委員長","kind":"確認","question":"品川区も前は、すごい冊子でしたよね。厚い冊子になっていました。品川区は毎年やっていた。多分、名古屋市も毎年やっているような感じがするのですけれど。その辺は私も、自民党の中でも話したのですが、職員負担の問題もありますので、その辺は確認してもらったほうがいいと思います。事前に事務局からも打合せしますので、今のご質問等も調整をしたいと思います。何か確認しておきたいことがありましたら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それと、４ページに「今後の組織の中核を担う女性職員の育成」と書かれているのですけれど、そういうジェンダーというところで捉えたときに、女性の管理職をどう確保して、方針を決定する場に女性の割合をどう確保していくかということを目的を持ってされているのかどうなのか、ちょっとそこら辺のところも伺えたらなというふうに思ったところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問・要望","question":"その辺が、人材育成型キャリアパス、複線型人事制度で、専門の、職務深耕というのですか、深く、職務深耕ステージに応募できるとか何かそういう制度で、やはり、ある意味、あちこち異動するよりも、そこで専門性をもっと高めるという人事のあり方なのかしらと思って勝手にそう読んでしまったのですけれど、その辺も含めてぜひ教えていただきたいなというふうに思います。取りあえず、それだけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"静岡市のほうなのですけれども、新人ではなく幹部職員の人材育成というのはどうしているのかなと。けれど、多分そうではないのだろうなという思いがあるので、その辺の変わり方、育成の変化というのがあったら教えてほしいなという思いがあります。それから、名古屋市のほうなのですけれど、行政評価をして、次年度にどう役に立っているのかなという。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"湯澤委員","kind":"質問","question":"行政評価が公会計制度とどのように関連をしていくのかというところについても質問をしていきたいと考えています。先ほども出ましたけれども、名古屋市などでは１１０件の施策シートなどを作成して点検・評価しているということなので、職員の負担というのがどういったものになっているのかということについても質問していきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"すみません。静岡の職員の体制なのですけれど、多分基本的なところは、正規の職員と非常勤の職員がどの程度の割合かとかいうものは教えていただけるのかな。そこら辺のところと、専門職の配置と生かし方をどう考えられているのかをお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問","question":"人材育成のほうで、先ほどどなたかがおっしゃったのが関係するかもしれないのですけれど、今、どこの職場でもメンタルについてのフォローというのですか、そういうものが必要とされていると思うのですけれど、その辺について見当たらなかったので、もしそういうことで何か工夫されていることがあればぜひ伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問","question":"多摩市も最初は失敗したというのを聞いたのです。これでは全然面白くないみたいな。それで改善されて評価するようになったという事例報告を、新公会計制度ができた後の何かの学習会で事例を聞いた記憶があるのですけれど、ごめんなさい、ちょっともう今、曖昧になってしまって。もし、名古屋市でそういうことが伺えるのであれば、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"大倉委員","kind":"質問","question":"行政の窓口とかこういうところに来るのは、仕方なくというか目的があって来ると思うので、そういったときに、職員などの対応とか、来庁者の方の満足度とかというお話がちょっと出ていたのですけれど、どういうふうにそういう満足度を上げていくというやり方をされて、コンシェルジュみたいなお話もありましたけれど、その辺の満足度についてどう評価していこうと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"つる副委員長","kind":"質問","question":"今の点は名古屋市のほうの視点でいいですか。静岡市も両方またぐのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"つる副委員長","kind":"質問","question":"これ、多分正副委員長に一任いただくことかもしれないですけれど、今こう言っていただいて、事前に事務局を通じて先方に送って、恐らく口頭ベースでそれを含んだ説明だと、それぞれ１時間しか視察時間がないので、多分現場での質問の機会というのはなく、聞いて終わってしまうということを考えると、この委員会として向かう私たちの姿勢としても、今、事前にこうやって、先方にお届けして、それを一定程度。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982063?Template=document&Id=2242#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":23446,"voices":75}},{"id":"r04-20220823-14","meetingId":"r04-cm08","date":"2022年8月23日","dateIso":"2022-08-23","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時４０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"やはり、これは、何とか独自の決済システムみたいなものを持って、そのような手数料をなくしていく、あるいは軽減していくといったことは、考えていってほしいと思っています。この手数料に関しての考え方、また、国あるいは東京都等で、このようなことが話題になったり、検討されたりということが、今後、起こるようなことがないのかということで、まず、現状をお伺いしたいと思います。","respondent":"宮澤情報推進課長","answer":"決済システム自体を独自に調達、構築するということは、なかなか難しい分野であると感じているところですが、その他、窓口での様々なシステム等の共同調達という動きはありますので、そこら辺は、情報収集等を踏まえながら研究していく部分であると感じているところです。","id":"exchange-001"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。もう１点です。これはできる、これはどうだろうかなどという仕分のようなこともされているのだと思います。これを進める上で、もう一つ、コスト面の視点というのでしょうか、デジタル化をして、業務効率は上がったのだけれども、そのシステム運用などの維持管理に、また、委託料をＩＴベンダーにたくさん支払っていくようになることも、一長一短であると思います。","respondent":"河西情報戦略担当課長","answer":"あまり大きなシステムを入れてしまうと、メンテナンスができないという将来のお荷物になってしまう可能性もありますので、そこはしっかり技術視点で目利きをしながら、導入を進めていきたいと思います。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"すみません、もう一回、デジタル化に関することをやるのですか。今日は、この赤枠で囲まれた2)、3)、4)、5)のところで、例えば、２ページのところのオンライン化などというものは、この次の説明ということになるのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"赤枠のところになるのですね。だから、オンライン化などは、次のところで、取組みのところの行政手続きのオンライン化に３００手続きなどがあります。ここのところは、次のときということで、今日の審議にはならないということですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"分かりました。すみません。そうしましたら、どのような体制でやっているかというところです。３ページのところで、各課のデジタル化推進委員１０９名でされているということですけれども、ということは、１課あたり、二、三人みたいな形になっているのか。そこら辺の体制はどのような形でされているのか、研修などはどのような形で行われているのか、そこら辺を教えていただきたいと思います。","respondent":"河西情報戦略担当課長","answer":"６ページをご覧ください。先ほど駆け足で説明した内容を、少し細かく説明させてください。2)、3)、4)、それぞれ業務を挙げさせていただきまして、効率化方法をご説明しました。ローコードツールとはどのようなものかというところからご説明させてください。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ありがとうございました。議事録作成は、ほとんどＡＩ議事録作成ソフトで、区としては、大体、様々な会議のところで、これが実施されて、このソフトでできるという状況になっているということなのでしょうか。区の状況というのは、進み具合が、どこら辺まで来ているのかということを教えていただけたらと思います。そのことについて、教えていただけたらと思います。","respondent":"河西情報戦略担当課長、宮澤情報推進課長","answer":"１つ目のご質問に対してご回答します。ＡＩ議事録作成支援ソフトですが、延べ１７２件ということで、件数的には多いように見えるかもしれませんが、我々が庁内で実施している会議数を考えますと、氷山の一角です。２点目の委託に関わるセキュリティの部分です。委託の内容は幅広いかと思いますが、例えば、委託している社員の方が、区の窓口等で、業務システム等を扱うものがございましたら、８月を区職員のセキュリティ強化月間としております。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"デジタル化の仕組みをつくるにあたっての業務委託みたいな形で、民間業者に丸ごと委託するみたいなものはないのでしょうか。というのは、以前、委託の業務職員がＵＳＢを持ち出して、その後、飲み会か何かに参加したのでしたか。区として、そのような場面、そのような業務委託、そのようなことに対してのセキュリティの対策は、どのようになっているのかを伺えたらと思います。","respondent":"宮澤情報推進課長","answer":"なので、職員であっても、自由にＵＳＢメモリーを差し込んで、データを移すということが、仕組み的にできないような対策を取っているです。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１０ページの電子決裁も、基本１００％にしていくということでした。その体制も伺えたらと思います。国から、デジタル化を推進するということで、かなり予算も組まれていると思うのですけれども、デジタル化を進めるにあたっては、この計画からすると、令和７年度までに、基本的な仕組みをつくるという考えでいいのでしょうか。全体と今年度みたいなものが分かったら、教えていただけたらと思います。","respondent":"宮澤情報推進課長、河西情報戦略担当課長","answer":"続いて２点目です。デジタル化を進めていく推進基本方針につきましては、令和７年度までを適用期間としています。私からは、先ほどの１つ目のご質問に対して、ご回答します。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"デジタル化で、業務もかなり効率化されて、住民にとっても、様々な便利な部分が出てくると思うのです。そのようなところで、さらに、それが本当に住民にとってプラスになるような形で、ぜひやっていただきたいと思っています。これを導入するまでには、そのような経費がかかっていくけれども、その後は、運営経費が削減されていくという見通しは、どう考えられているのか。最後に、その点を教えてください。","respondent":"河西情報戦略担当課長","answer":"ただし、先ほど、併せてお言葉をいただいたとおり、運営経費は、その後、デジタル化することにより、自動化できる作業等々が出てまいりますので、スマートな運営ができるということで、運営経費に関しては削減できると報告いたします。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"セキュリティのところで伺いたいのですけれども、順不同で、資料の１１ページです。どうしても国の説明が足りないのか、区民からいろいろなお話を伺うと、マイナンバーカードを取得することによって、自分の個人情報が抜き取られてしまうという、私の認識からすれば、誤解が非常に多いというところについて、ここのセキュリティレベルについてのご説明を、もう少し詳しく伺いたいと思います。","respondent":"河西情報戦略担当課長","answer":"「無害化が必要」というところをご説明する前に、まず、３層分離モデルの基本的な考え方をご紹介いたしますと、今までは、物理的に一つのネットワークで、このようなマイナンバー系、ＬＧＷＡＮ系、インターネット系という業務をやっていた時代がございましたが、今は物理的。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ごめんなさい、分かっていないのは、私だけかもしれませんが、何でセキュリティレベルが低いということなのかを、もう一回、繰り返しになってしまうかもしれませんが、もう少し教えていただきたいということが、一つです。もう一つだけ伺います。企業だと、そのようなイメージがあるのですけれども、その辺りも教えていただきたい。その辺りを教えていただきたいと思います。","respondent":"河西情報戦略担当課長、宮澤情報推進課長","answer":"もう一度、少し説明の仕方を変えさせてください。こちらは、インターネット系、ＬＧＷＡＮ系、マイナンバー系のセキュリティレベルのご説明になります。ただ、先ほどの説明のとおり、今現在、直近ですと、４０％近くを電子決裁で進めているというところで、電子決裁自体が、意思決定の迅速化であったり、例えば過去の決定文書を見る際に、今までは、紙であれば。","id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"質問","question":"私も詳しくないのでよく分からないのですが、２－１のところからお伺いします。１００％もあったり、いろいろやっていこうということです。例えば、これも、今、２－１がスタートしていって、横串をして、どこかで共有化すれば、もっとこれはいい方向で、共有化ができるのではないかなどの判断は、情報戦略担当でやるのですか。そのようなイメージでいいのか。","respondent":"河西情報戦略担当課長","answer":"決めなければならないことの種別について、そちらによって、決定される方が変わってくると考えています。大きな目標や品川区のＤＸを進める方針に関わることに関しては、先ほどご紹介させていただいたＤＸ推進戦略会議にかける必要があると考えています。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問","question":"一つだけ伺いたいことは、先ほど、１８名体制で、今、課長も民間から来られて、１名で、あとは、職員の方が一生懸命、頑張ってやっていただいている体制。国も動き出しています。そのような意味でいうと、強化をしたほうがいいのかと思うのだけれども、そこら辺は、どのような感じでお考えでしょうか。","respondent":"河西情報戦略担当課長","answer":"ご質問にご回答します。大きな目標、方針に関しては、しっかり桑村副区長を筆頭に出していただけたと考えています。我々も、望んだものを出していただけたと考えています。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問","question":"もう１点、伺いたいのだけれども、国もやっています。東京都もやっています。東京都だけれども、区があげるといったら、今の紙ベースの感じでは、とてもではないけれども、向こうも、紙ベースでこれほどの書類が出てきて、それをチェックしてなどということはできないと、もうバンザイをしている雰囲気が大分あるわけではないですか。区長会なのか。部長会なのか。課長会なのか。","respondent":"宮澤情報推進課長","answer":"デジタル化を進めていく上での方針の意思決定等になるかと思います。先ほど来の説明のとおり、区のＤＸ推進方針、ビジョンに基づく部分は、ＤＸ推進戦略会議で行っていくです。","id":"exchange-014"},{"speaker":"西村委員","kind":"質問・要望","question":"２点、お伺いさせてください。テレワークについて伺います。２点目が、デジタル化を進めていく中で、障害のある方が在宅でできるお仕事があるのではないかということは、模索していきたいと思っているのですけれども、障害者雇用が多様化されてきていまして、ぜひとも柔軟にお考えいただきたいと考えていますが、何かご検討されていることがあれば教えてください。","respondent":"宮澤情報推進課長","answer":"障害者の在宅雇用の部分につきましては、このＤＸという部分では、現在、検討といいますか、所管の部分で、お答えを申し上げられないところです。","id":"exchange-015"},{"speaker":"西村委員","kind":"質問・要望","question":"すみません、ありがとうあります。区役所の業務はテレワークに不向きなものがすごく多いのではないかと思っておりまして、働き方改革という点においては、やはり、有効な手段であると、個人的にも思いますので、引き続き、取り組めるところから、取り組んでいただきたいと考えています。障害者雇用に関しては、若干、所管が違うところもありまして、失礼いたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"渡部委員","kind":"質問・要望","question":"いわゆる自治体のＤＸというか、デジタル化の部分で、僕はそのようなところなのかと思うのですけれども、その辺の考え方だけを、もう一回、お聞かせいただきたい。ぴったりサービスでしたか。マイナポータルで、お金が絡んだり、マイナンバーカードが絶対必要な申請があるではないですか。最終的に、区民の利便性が高まっていれば、それは、それでいいとは思うのですけれども、その辺の関係性を教えてほしい。","respondent":"宮澤情報推進課長","answer":"ＤＸを進めていく体制、また、そのコストという部分です。情報推進課１８名で行っておりますけれども、やはり、情報推進課だけで、ＤＸを進めていくわけではなく、全庁的にやっていこうという機運で、全ての職員を対象として、ＤＸの研修等も実施しながら、行っております。","id":"exchange-017"},{"speaker":"渡部委員","kind":"質問・要望","question":"前段の部分に関しては、そこでスピードの遅滞などが起こらないように、スムーズに進められるような体制をしっかりつくっていただいて、行政ですから、当然、コストのことは考えていかなければいけないのだろうけれども、それは二の次で、最終的にそれの着地点というときには、もう絶対にコスト削減にはつながっているはずなので、そのような観点で進めていただきたい。それでやったとします。答弁は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"大倉委員","kind":"質問・要望","question":"教えていただきたいのですが、スライドの２ページの重点項目、ＡＩの活用やＲＰＡの活用というところで、令和４年は１５業務というところで、先ほども石田（秀）委員のお話、答弁の中でも、拡大していくほうが、デジタル化が速く進んでいきますというお話です。","respondent":"河西情報戦略担当課長","answer":"こちらは、あくまでも、目標は、累計１５業務となっておりますが、各課のニーズに応じて、そちらは、情報戦略担当で、技術的な目線で、しっかり効果が見込めて、コスト的にも問題がないというところを確認できましたら、１６５業務の中でも。","id":"exchange-019"},{"speaker":"大倉委員","kind":"質問","question":"そうすると、いろいろ精査して、コスト、効率化を考えながら、１５業務以上をやっていくというところで、これは、例えば、令和７年で２７業務というところも、もういきなり目標達成するみたいなこともあるのかどうかということと、そのような業務が、前倒しで速くなることのメリットみたいなことがあれば、教えてください。","respondent":"河西情報戦略担当課長","answer":"ご指摘のとおり、目標に関しては、どんどん前倒しで実行できるものに関しては、実行していこうと考えております。１点、２ページに、令和７年度、２７業務と書いてある目標に関しては、ＡＩ、ＲＰＡの累計業務数になっております。分かりづらい資料で、申し訳ありません。","id":"exchange-020"},{"speaker":"大倉委員","kind":"質問","question":"そうすると、これを足すと、５５業務ということで、２７業務より上回っていると思って、その中で精査しながら、前倒しをしてやっていくということで、分かりました。例えば、これは、もう前倒しをして、どんどんやれるというところであれば、ぜひ、やっていっていただいて、業務効率化をしていっていただければいいと思ったので、質問しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"様々ご説明をいただいて、私もデジタル化はあまり詳しくないので、６ページのところは、訳が分からなかったのですが、手作業でやっていたところが、コンピューターシステムによって、効率化されるということは、イメージできました。私たちも、そのようなまとめたものを見られるようになっているのか伺いたいと思います。","respondent":"宮澤情報推進課長","answer":"区のＤＸ推進基本方針、また工程表は、区のホームページで公開しております。ただ、ＤＸ推進戦略会議の状況は、議事録等は公表していないのですが、この取組み自体につきましては、取組みの進捗状況は、今後、区のホームページ等で、お知らせしていく予定です。","id":"exchange-022"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"私はそうなのですけれども、だからこそ、オープンにしていただいて、分かるように、見えるようにしていただきたいというところでは、どのような議論があったのかということは、知りたいところであると思いますので、検討していただけたらと思います。スライド３のところです。どれぐらい研修をされてきたのかということを伺いたい。そこら辺の感覚を教えていただきたい。","respondent":"宮澤情報推進課長、河西情報戦略担当課長","answer":"ＤＸ推進戦略会議で話す方針・決定する内容は、その後の進め方に反映していきます。それらは、ホームページ等で、言葉が分かりやすくなるような形等を踏まえて、お知らせしていければと考えております。これから、今、デジタル化推進委員向けに実施しておりますが、その方が気づかないところも補完できるように、対象の方等々を検討いたしまして、引き続き、こちらのデジタル人材育成研修を実施することによって、漏れなく。","id":"exchange-023"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"分かりました。最後に、ＤＸ推進戦略会議は、年、何回という回数は決まっているのか、その都度、開かれていくものなのかを伺いたいと思います。","respondent":"宮澤情報推進課長","answer":"ＤＸ推進戦略会議です。年２回程度というところで考えておりまして、会が行われて、方針等の内容、進捗状況を確認しながら、行っていくです。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/893508?Template=document&Id=6136#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":30669,"voices":68}},{"id":"r04-20220824-19","meetingId":"r04-cm08","date":"2022年8月24日","dateIso":"2022-08-24","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ３時１１分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"難しい用語がいっぱい並んでいるので、私も調べながら読ませていただきましたけれども、まだまだ理解が不十分な点がいろいろあるのではないかと少し不安なのですが、２つほど質問したいと思います。そういう意味で、２０１３年度比５０％という目標値はもはや不十分ではないかと思うのですけれども、いかがでしょうか。","respondent":"河内環境課長","answer":"５０％の考え方ですが、現実目標というところと、それから東京都との整合などいろいろ考えつつも、今置かれている品川区の状況などを踏まえまして、５０％を果たしたいですが、もとよりこれは５０％で制限する問題はございませんので。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"そのために、２０３０年までに意欲的な目標を達成していかなくてはいけない。そのことをにらみながら、品川区もここで中間見直しをやるということでは、やはり５０％ではもはや不十分なのだという国際的なＮＧＯの提言も出ているわけですから、それを十分考慮した目標値を、せっかくの見直しのチャンスなのですから、国際的なＮＧＯの提言を踏まえた見直しをやっていただきたいと私は思います。","respondent":"河内環境課長","answer":"その際にも、また社会情勢を反映した適切なことにアジャストできると考えておりますので、今回の見直しにおきましては、５０％の削減目標値は適正なものであると考えているところです。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"そういう意味で、現段階でも５０％では不十分だと、私は思っているという意見表明させていただきたいと思います。再生可能エネルギーによほど余裕ができてというような将来の話なら、その再生可能エネルギーからできている電力を使って水素エネルギーを作り出すという話もあり得るとは思うのですけれども、これは２０３０年までというお話ですから、その期限のことを考えれば非現実的な話になると思います。","respondent":"河内環境課長","answer":"水素だけで全ての問題が解決するわけでございませんが、得意分野をこの提案どおり組み合わせていきませんと、もとより区民や事業者の方がどの方法を選択するかという問題も出てまいりますので、そういった意味からも。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"ただ、それらはこれから開発される技術ですよね。２０３０年までという期限付きのことを考えると、この水素エネルギーの普及拡大ということにはあまり結びつかないのではないかと思えて仕方がないのです。２０３０年までの脱炭素社会の実現に結びつけるものとして持ち出すのは、違うのではないかなと私には思えるのですけれども、いかがでしょうか。","respondent":"河内環境課長","answer":"先ほど私の説明の中にも、ＪＥＲＡの水素発電につきまして２０３０年代を目途にというところで、２０３０年につきましては、まずは一定のゴール地点ではなく、中間スタート地点というようなところです。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"ちょっと数字は忘れましたけれども、今の何倍もあるのだと。ですから、そこに注力することが最も重要であって、まだ開発されてない技術を使わなければいけないようなものを、２０３０年まで要するにあと８年の話ですけれども、そこにあまり目を向け過ぎても、脱炭素社会の実現には結びついていかないようなことになってしまいかねないと思えてしようがないのですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ、この対象が、適正管理を誰が努めるのかなという部分を確認させていただきたいというのと、それが事業者だけではなくて、何度も何度も議会の中で、生活者ネットワークが伝えていたと思うのですけれども、身の回りの生活の中にある化学物質について、事業者だけではなくて、家庭、区民がやはり考えて向き合っていかなくてはいけない問題なので、ぜひ環境省のＰＲＴＲの市民ガイドブックの紹介とかも。","respondent":"河内環境課長","answer":"最終的にトータルなＣＯ２が少ない選択をしていくことが、地球全体のＣＯ２の削減につながると考えていますので、可能性を捨てることなくという点ではあるのですが、基本的には再生可能エネルギーが重要だという認識は間違いございませんので、そういったことで。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"水素エネルギーのところなのですけれども、ＣＯ２削減をしていく、その環境のことを考えてということだと、やはり再生可能エネルギーを使ったグリーン水素の普及というのがやはり根底にあるべきだと思うので、ぜひそういった計画になったらいいなということを求めたいと思います。ごめんなさい、さっき言い忘れてしまったのですけれども、今、エコルとごしでフード・マイレージの展示があるではないですか。","respondent":"河内環境課長","answer":"委員のおっしゃるとおりフード・マイレージ、食料自給率が、カロリーベースで３８％台というところで多くの輸入材料について、生産地からの輸送でＣＯ２が発生しという中で廃棄されているというようなところは、見直すというきっかけになろうかと思うのですが。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"資料裏面の6)建物の脱炭素化で、区内建物へのＺＥＢ等の促進、区有施設への太陽光パネル設置、ＺＥＢ化促進とありますけれども、超高層のタワーマンションやオフィスビルではＺＥＢは難しいという考えは品川区にあるのかどうか、まず伺いたいと思います。ＺＥＢを目指すと言いながら、延床を最大限に増やす再開発では環境対策に逆行すると思います。","respondent":"河内環境課長","answer":"一方で、そういった状況の中でやろうといたしますと、ＺＥＢが適用するような条件もおのずから出てくるです。壁面の太陽光パネルとか、いろいろなこれも今後の新技術におきましては、ＺＥＢの適用条件もいろいろ変わってこようかと考えています。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"しかし、ＺＥＢを目指すと位置づけながら、逆に現状よりもＣＯ２を増やしてしまうことになるのでは、環境対策にならないと思います。太陽光ももちろんその一つではありますけれども、例えば水力、海の潮の満ち引き、下水処理の際のメタンガスの活用など、視野を日本全国、世界にも向けて、都市部での再生エネルギー活用の調査研究もしっかりと位置づけていただきたいと思いますけれども、いかがでしょうか。","respondent":"河内環境課長","answer":"区有施設へのＺＥＢの適用ですが、現在施設整備課におきまして、適用条件、内容などを整理している状況でございまして、私どもで答えることが難しい状況ではありますが、主には省エネと創エネにつきまして、しっかり創エネ、これは認証を取得するものですので。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"ＣＯ２排出の比較ですけれども、従前の建物とこの再生エネルギー設置後や建て替えた際に、区有施設はもちろん民間施設であっても比較できるように、しっかりしていただきたいと要望しておきたいと思います。石炭火力発電所はやめること、原発ゼロを求めること、この国への要望活動も、ぜひ中間見直しのこの計画に記載していただきたいと改めて要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"１点気になるのが、このサステナブルファッションとして、ペットボトルから作られた洋服、というもので、何かサステナブルといったような売り出し方というのがあるのですけれども、結局やはりマイクロプラスチックを生んでしまっている状況もあったりとかで、環境に優しいような、しかし実際はそうでない、海に流してしまっている状況があるということもあるので。","respondent":"河内環境課長","answer":"そういったことをしっかりやっていきたいなというところで、この項目を入れさせていただいた次第です。","id":"exchange-011"},{"speaker":"田中委員","kind":"確認","question":"洋服を買うときとかにも、やはりどういうもので作られているかという製品を確認してというのはとても大事だと思うので、そういった確認、そういうところの啓発がされたらいいなというのと、エコルとごしでもたしかあったと思うのですけれども、洗濯用ネットでもマイクロプラスチックが生まれてしまっていたりとか、やはり製品についてみんながちゃんとどういう成分でできているものなのかということを。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"つる委員","kind":"提案","question":"中間見直しの骨子案ということで、スケジュールを見ると来年の３月が最終版ということで、ここに記載されていることが最終版でしっかりと達成されるということを、強く期待したいと思います。この辺りについて、まだ計画の見直しの骨子案の段階ですが、具体的にこれまでの提案も含め、どういう方向性で考えていただいているか、今のお考えを教えてください。","respondent":"河内環境課長","answer":"その中でそういったものが実現できればということで、今多様な可能性といたしまして、そういった分野の検討も併せ、進めているところですが、具体的にいつやるかというところは今後の検討なのですが、そういったところでしっかり進めてまいりたいと考えております。","id":"exchange-013"},{"speaker":"つる委員","kind":"提案","question":"ありがとうございました。どちらかというと人権に入るかもしれませんが、搾取されてできてきたものとかという、本当に大きい意味での、これはＳＤＧｓとかその辺になってくるかもしれません。これはいろいろな施策でも課題ではあるのですけれども、いわゆる見える化とか見せる化とかいう言葉がずっと言われて久しい中で、今、一応エコルとごしのほうでは発行が３つ目ですか。この辺りをどうやっていくか。","respondent":"河内環境課長","answer":"区内に本社がある会社ですとか、そういったところに呼びかけまして、区がいろいろやっているだけではなくて、品川区の中でやはり環境意識が、周りからもいろいろな意識の高さが出てきていて、そういった意識の醸成が進んでいる区だなというふうに認識されますよう。","id":"exchange-014"},{"speaker":"つる委員","kind":"質問・要望","question":"だけど、それは先ほどの方ではないけれども、永遠なのだということを考えれば、これは減価償却から見てもすごく安くなっていくものだということを見れば、別に高いからいいのだとかそういうことではない視点をしっかりと含んだ展開をしていただくに際して、誤った形にならないよう、みんなが本当に取り組みやすい、世代関係なくやれるような形でぜひ進めていただきたいなと。これは要望で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"須貝委員","kind":"提案","question":"それは提案だけではなくて、そしてある程度小さな予算でもやはり支援をしていくということが大事ではないかと私は考えます。具体的な提案として、手法なのですが、例えば目に見えるガス代、電気代などは、これは建築課も関わると思うのですが、現在ある各建物に関しても、今の１枚のガラスではなくて例えばペアガラスに替えてくれませんかと。もう一つ、世界の取組も私は取り入れていただきたいと思います。","respondent":"河内環境課長","answer":"世界の取組につきまして、コンクリートなどは、いわゆる私どもは消費ＣＯ２を分担しておりますが、製造ＣＯ２の面もありますので、そういったところも踏まえ、啓発の中で触れていければと思っておりまして、次に潮流で何が来るかとか、世界では何をという点も。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"建築課からすれば、本当はペアガラスを使ってくれればどれだけ助かるか。省エネで助かるか分からないし、本当にどんどん進めてほしい。けれども、ソーラーパネルはさすがに屋根の上につけるには相当費用がかかるし、それに蓄電池などを入れたらやはり大変だという現実もあります。何かご意見あったらお願いします。","respondent":"河内環境課長","answer":"砂電池の利用拡大につきましても、今後研さんを進めてまいりまして、検討してまいりたいと考えています。","id":"exchange-017"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。様々議論を聞かせていただく中で、簡単に要望だけさせていただきたいと思います。ゼロカーボンシティ宣言を行う中で、この２０３０年に向けたカウントダウンと言っていいのかあれですが、この８年間の中で、ゼロカーボンシティ宣言からこの２０３０年に向けての一つ一つ、例えば小学校の１年生であれば８年生までですかね。","respondent":"河内環境課長","answer":"そういった次世代を担う子どもたちが読み解けるような工夫といたしまして、そういった表現に落ち着かせるというところで、現在検討を進めているところです。","id":"exchange-018"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。今、コロナの感染が落ち着かない状況でありますので、エコルとごしでの様々なイベントとか、小学生の見学もなかなか進まないという現状もあるかと思いますが、エコルとごしを最大限に活用しながら、小学生の子どもたち、また区民の皆様がそういうところで意識が高まっていけるような、そういう取組もぜひお願いをしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"のだて副委員長","kind":"質問","question":"基本目標１のところで、この目標の文言を「低炭素な暮らし」というところから「脱炭素社会」ということで変更になっていますけれども、変更したことでの違いというのですか、この意味するところを伺いたいと思います。","respondent":"河内環境課長","answer":"詳細につきましては、今後また素案の中で検討を進めてまいりますので、よろしくお願いいたします。","id":"exchange-020"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"それと資料の事業者のアンケートのところに、「ハード面による省エネ等は進めるにあたって工夫が必要」と書かれております。それと、できるだけ全ての区有施設で設置を進めていくということと、それは太陽光パネルだけでなく、いろいろ風力ですとか調整力などあると思うのですけれども、そこでその施設の電力を賄えるところを目標に設置を進めていくべきだと思うのですが、いかがでしょうか。","respondent":"河内環境課長","answer":"ここにつきましては認証制度ですので、そこに受かるか受からないかというところはあるのですが、一方で受かる、受からないにかかわらず、やはり環境に優しい建物としてこういったものに近づけていくというところの方針につきましては。","id":"exchange-021"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"適材適所で進めていくということですけれども、事業者への設備更新の助成ですとか、区有施設への再生可能エネルギーの設置ですね。ぜひ積極的に進めていっていただきたいと思いますし、計画にも位置づけていただけるよう、要望、意見を言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-02","title":"令和４年度東京都・品川区合同総合防災訓練","agenda":"令和４年度東京都・品川区合同総合防災訓練","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"そうしますと、四十何年ぶりというこの東京都と品川区の総合防災訓練ということで、かなり前からこういうことがあるということが町会・自治会には話があって、しかしながら感染が拡大しているということで少し内容が変わってきている、人員も変わってきているということで、まず、町会・自治会への周知というか、どういう方が参加されるのかというところを。","respondent":"五十嵐災害対策担当課長","answer":"特殊車両の展示も、小さい子ども向けですけれども、同じ会場で実施されます。それと、小山台小学校の校庭も一部区民向けの体験訓練の会場となっています。そちらもぜひ体験していただきたいと考えております。","id":"exchange-023"},{"speaker":"新妻委員","kind":"確認","question":"どれだけの方が来られるのか。意識を持って多くの方が訓練に参加をしたいということは非常に大事かと思うのですけれども、一方でそういう警備の問題とか感染拡大防止の視点から見ると、たくさんの方が来られるということになると受入れも大変だということもあるのですけれども、そこら辺はどうお考えになっているのか確認をさせてください。","respondent":"五十嵐災害対策担当課長","answer":"２つのご質問のうち、まず１つ目ですけれども、９月３日の件は、巡回バスを使ってご来場いただきたいと考えております。東京都には当初私どものほうから、どのイベントでも人数制限などは今やっていませんよというふうにお話ししたところです。","id":"exchange-024"},{"speaker":"新妻委員","kind":"質問","question":"分かりました。そうしますと、私が参加をしたいという場合は、この林試の森公園また小山台小学校等に行くということでよろしいわけですね。それともう一つ、併せてこのときに、聴覚障害者の団体の方が訓練をされると伺っておりましたが、この団体の方の訓練というのはどちらで行われるのか教えてください。","respondent":"五十嵐災害対策担当課長","answer":"障害者団体の訓練の参加についてのご質問になります。今、お話がありましたとおり、９月３日の小山台小学校で行われる避難所運営訓練に参加される予定です。この部分、経緯からご説明します。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"今の障害者への避難訓練の呼びかけのところなのですけれども、訓練に参加してもらって、体験してもらった後にヒアリングをして改善をしていくといったご答弁で、とてもいいなと思ったのですけれども、現状、聴覚障害以外の障害の方にも声かけされているのかというところをまず確認させていただきたいのと、今回この防災訓練の場所、小山台小学校が選ばれた理由は何かあるのかというところと。","respondent":"五十嵐災害対策担当課長","answer":"バスのお話なのですけれども、通常の路線バスと変わらないようなバスを予定しています。すみません、私のほうで確認しますけれども、障害者対応できるバスなのか、一般の路線バスと変わらないので、大丈夫かとは思うのですけれども、そこはもう一度確認させていただきたい。","id":"exchange-026"},{"speaker":"田中委員","kind":"確認","question":"巡回バスのところなのですけれども、私は、今大井のほうを走っているあの小さいバスなのかなと思ったので、そうではなくて大きいのと聞いて驚きました。では大きな道路を使っていくということなのですかね。なるほど。林試の森公園での利用ということなのですけれども、今、この林試の森公園でのアナウンスはされているのでしょうか。参加して大丈夫というところを確認したいです。","respondent":"五十嵐災害対策担当課長","answer":"品川区側は品川区、目黒区側は東京都で実施しているというようなことです。２つ目の区民避難所での障害者団体の方の参加の話なのですけれども、個人であれば参加出来ます。","id":"exchange-027"},{"speaker":"中塚委員","kind":"確認","question":"確認なのですけれども、聴覚障害の方もいらっしゃいますので、手話通訳と要約筆記の配置は必要だと思うのですけれども、状況を伺いたいと思います。これまでも述べてきましたけれども、やはり障害がある方に話を伺うと、首都直下大震災への備えや発災後にどう動いたらいいか、避難生活がどうなるのか、とても強い不安を抱いております。","respondent":"五十嵐災害対策担当課長","answer":"訓練参加に障害者の方々がストレスにならないようにと考えておりまして、事前に我々も勉強しながらご対応させていただかなければならないと同時に、今後、今回この訓練だけで終わらせるのではなく。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"東京都も品川区も手話言語条例ができておりますし、やはり今後と言いたいけれども、いつ起きてもおかしくない首都直下大震災ですから、そういう意味では直ちにという言い方にはなりますけれども、防災訓練の際に手話通訳や要約筆記の配置、またその配置をしていることの告知をぜひ進めていただきたいと要望したいと思います。","respondent":"五十嵐災害対策担当課長","answer":"やはりそこは、訓練を推進する者がしっかりその実情を知った上で訓練に参加を促さなければ、訓練を受けることが大変なストレスになってしまう可能性もあって、ひいては訓練はもういいやと、災害対応はもういいやとなってしまうと。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"それは決して全く情報がないわけではなくて、過去の災害を通じて様々団体の方が意見を上げておりますので、東日本大震災をはじめ、熊本の地震や水害など、国や東京都も意見を聞き取っておりますので、その辺を品川区も把握していただいて、積み上げていただきたいと要望しておきたいと思います。つまりは実際の被害を想定した訓練の実施が必要だと思いますので、この点についても伺いたいと思います。","respondent":"平原防災課長","answer":"今ご指摘の東京都と品川区のテレビ会議システムですが、こちらの通信形態が防災行政無線網の活用ですので、災害時にも非常に強い電波網を使っているということで、いわゆる一般の回線とは全く異なる電波形態ですので、そういったところでは。","id":"exchange-030"},{"speaker":"つる委員","kind":"質問","question":"予算の関係なのですが、当初予算では１,３０９万８,０００円ということで、これ品川区の一般財源で、都のお金は入っていなくて品川区として分担なのか分からないですけれども、そういったところで出ていると思うのですが、品川区を含めて東京都全体、その予算が分かれば、まず教えてください。","respondent":"五十嵐災害対策担当課長","answer":"東京都からは１億円というふうに聞いております。","id":"exchange-031"},{"speaker":"つる委員","kind":"確認","question":"丸まった数字、１億円ということで、それで、昨年実施するということで、当委員会での報告の議事録を見るときに、「確認します」というふうになっていて、詳細はその議論の中ではなかったのですけれども、予算特別委員会のほうもまだやり取りを確認はしていないのですが、お金の出し合いというのでしょうか。","respondent":"五十嵐災害対策担当課長","answer":"さらに小山台小学校も様々な体験車両、はしご車も含めて入ってきますので、その養生とかそういった部分は東京都で実施するということで、それ以外、区に関わる部分については区で予算措置させていただいたところです。","id":"exchange-032"},{"speaker":"つる委員","kind":"質問","question":"分かりました。停車する場所なのですが、区境のほうではなくて補助４６号線沿いという理解でいいのかな思うのですが、停車する道路の場所、これを教えてください。","respondent":"五十嵐災害対策担当課長","answer":"停車位置は、小山台小学校の正門にほど近い部分と考えております。","id":"exchange-033"},{"speaker":"つる委員","kind":"質問","question":"そういった人の流れが、ちゃんと小山台小学校の校庭ないし林試の森公園のほうに流れていくとか、また近隣の方がびっくりしないようにというか、係員がどういう体制でつくのかなというところが気になるのと、チラシをポスティング等で周知と言っているのですが、見ている人、見ていない人というのは、これは一般論である中では、立て看板とかを１週間前ぐらいから立てて。","respondent":"五十嵐災害対策担当課長","answer":"バスの停車位置なのですけれども、かむろ坂の小山台一丁目１９番付近に停車位置を設ける予定です。バス停は表示物を掲示するのではなく、区の職員が２名ほどなのですけれどもそこに立って、フリップ的なものを持って、ここは停車場だというような表示をしていく予定です。","id":"exchange-034"},{"speaker":"つる委員","kind":"質問・要望","question":"あそこの林試の森公園の水車門のほうに抜けていくルートと、それから小山台小学校に入ってくるところでは路地というか、そこも当然住宅街となっているのです。当然そういう意識を持って参加していただく方はそういう意識ではないと思うのですけれども、近隣の方にとってのご協力という観点でも、やはりそういう体制は必要ではないかなと思うので、ここはあえて答弁いただきたいと思います。","respondent":"五十嵐災害対策担当課長","answer":"それでも人員が足りないということであれば、訓練対策本部を品川区役所の災害対策本部室に作って、何かあったらそちらのほうに飛んでいけるように手配しています。そういうような体制を取って、有事、何か緊急時の際は対応したいと考えております。","id":"exchange-035"},{"speaker":"おくの委員","kind":"質問・要望","question":"この点いかがお考えかということをお伺いしたいと思います。そのことの周知用のポスター等の提供を要望されていますけれども、この点、いかがでしょうかということを伺いたいと思います。その上で、そういう賠償責任の保障を明記し、予算措置もしてほしいということを要望されているのですけれども、その点いかがお考えになっているのかということを伺いたいのですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/170605?Template=document&Id=6622#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":42843,"voices":91}},{"id":"r04-20220825-10","meetingId":"r04-cm08","date":"2022年8月25日","dateIso":"2022-08-25","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件抜き出しています。","topics":[{"id":"topic-01","title":"令和５年度予算（議会費）","agenda":"令和５年度予算（議会費）","exchanges":[{"speaker":"のだて委員","kind":"提案","question":"これまでも旅費などは政務活動費の中で対応してきて問題はないと思っていますので、今回の議会政策立案費は必要性が感じられないのですが、なぜ計上するのかというところを伺いたいと思います。前回のコンサル費としては、例えば、５００万円というところでお聞きしたのですけれども、議会政策立案費全体としての金額はどのくらい想定しているのかというところも伺いたいと思います。","respondent":"工藤区議会事務局長","answer":"考え方といたしましては、今いろいろとお話にありましたように、議長主催の議員研修会等があるわけですが、その研修費用につきましては、僅かな額、２回分しか計上されていないということでございまして、例えば、議会全体で取り組むような新たな課題。","id":"exchange-001"},{"speaker":"のだて委員","kind":"意見","question":"前回の説明では、予算をつけるということで意識も変わってくると思うという説明もあったのですけれども、必要性がないというところで、取りあえず予算をつけるというのは区民の理解を得られるものではないと思います。共産党としては、この議会政策立案費を予算に計上するのは反対だという意見を述べします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"}]},{"id":"topic-02","title":"の２、令和４年第３回定例会","agenda":"の２、令和４年第３回定例会","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"先ほど議会費の要望事項のところで、共産党から７つ目のところで、予算・決算特別委員会の民生費の款別審査の充実を図るために国保、介護、後期高齢者医療の特別会計を別な日にするなど、２日間に分けて審議を行うというふうに求めていまして、今回決算の日程はもう近づいていますので、これでいくとしても、今後議会改革推進会議等のしかるべきところでぜひ検討していただきたいと思うのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"渡辺委員長","kind":"提案","question":"私のほうから、今またご要望、ご提案という趣旨のものなのですが、扱いについて、まず議会運営委員会でのご発言なので、議会運営委員会の正副で検討させていただき、その後どこがふさわしい会議体なのかも含めて、正副でお預かりしたいと思いますが、よろしいでしょうか。先ほどの確認に戻ります。それぞれ発言いただいた、資料No.２の原案のとおり進めてよろしいでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"}]},{"id":"topic-03","title":"東京都後期高齢者医療広域連合議会の報告","agenda":"東京都後期高齢者医療広域連合議会の報告","exchanges":[{"speaker":"石田（秀）委員","kind":"意見","question":"７月２８日、午後２時から開議されました。同意第１号から９件の議案があります。損害賠償金の請求をしましたということであります。出産予定日の６週間というのを、場合によっては多胎児だと１４週間とか、あとは当該出産の日後８週間経過する日までの範囲内とか、その期間をもっと広げるということが併せて行われているということであります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/369281?Template=document&Id=5476#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":7005,"voices":32}},{"id":"r04-20220916-6","meetingId":"r04-cm09","date":"2022年9月16日","dateIso":"2022-09-16","committee":"区民委員会","time":"午後 １時００分～午後 ３時１５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","topics":[{"id":"topic-01","title":"まちぐるみ文化イベント","agenda":"まちぐるみ文化イベント","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"あるいは、まちぐるみ文化イベント自体は、今回もちろん初めての事業なのですけれども、類似の文化事業というのをこれまでもやっていたのでしょうか。そこら辺をちょっとお伺いしたいのと、もし発展系とか類似の文化事業をやってきたのであれば、どういうことをやってきたのか、そして、今回の事業との関係はどんなものなのかお伺いできればと思います。","respondent":"篠田文化観光課長","answer":"品川の場合は、いわゆるイベントですとか、観光というと、旧東海道とか、水辺とか、どうしてもあちらの、海寄りのところに注目が集まってしまうので、区内を広く見れば、目立った観光地はなくても、それぞれの地域ごとに、地域に根差した様々な文化活動が結構行われていますので。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"初めてということで、荏原地区ということで期待しております。予算額が１,１００万円ということなのですけれども、これは品川の単費なのでしょうか。それとも、国や都の補助がついているのでしょうか。もしついているなら、その内訳を教えていただければと思うのですが、いかがでしょうか。","respondent":"篠田文化観光課長","answer":"こちらは全部区費です。補助金等は該当するものはございませんので、今年度に関しましては区費で、来年度以降も実施していくようなことがあれば、様々、そのときに補助金で利用できるものがあれば利用していくです。今年度に関しては特になかったです。","id":"exchange-002"},{"speaker":"塚本委員","kind":"意見","question":"この３つをうまく人が回って回遊するような形でにぎわい、人が動く、人が来て動くというようなことを想像するのですけれども、案内状というか、パンフレットとか、そういうのも多分作られるとは思うのですが、会場に来られた方というか、１日ここで遊んでくださいというパンフレットなどですね、そういったものについての仕込みとかはどうなっているのかというところと、あと人が集まってこられるように。","respondent":"篠田文化観光課長","answer":"そちらの方ですとか、明和電機とか、そのほか、品川ゆかりのアーティストにも出展していただくということで、今調整しているのですけれども、ゆかりのアーティストは８０名弱ぐらいはいらっしゃいますので、どのぐらい出ていただけるかはまだ確定していないのですけれども。","id":"exchange-003"},{"speaker":"塚本委員","kind":"確認","question":"今、商店街との連携という話で、武蔵小山商店街パルムはまさに３つの会場の基幹的な通りになると思うので、ここは来るかなと思うけれども、あと荏原のほうでいえば、共栄会とか、なかのぶスキップロードとか、戸越銀座はもしかしたら、中原街道を通ればということもあるので、商店街としての連携というのはこの３つの会場から発生している、放射状にというのではないですけれども。","respondent":"篠田文化観光課長","answer":"あわせて、例年１１月に行っていましたにしこやまつり、こちらも同日開催という形で、あわせてやるということにしていますので、そういった意味では、荏原全体をかなり広く取った形でイベントができるのかなと思っているところです。","id":"exchange-004"},{"speaker":"藤原委員","kind":"質問","question":"改めて具体的にお伺いしますけれども、荏原地区は具体的にどこかからどこら辺までが入るのですか。","respondent":"篠田文化観光課長","answer":"荏原地区ですと、荏原第１から第５地区までで、今回エコルとごしまで含めれば、武蔵小山から区役所の手前のところまでずっと広い範囲を網羅した形でイベントが開催できることになっております。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"私はやるべきことなのかなと思って、話をしますけれども、例えば今荏原地区という中において、宗教的なということは置いておいて、各神社でお祭りをしていますよね。商店街もすばらしいし、点と点が線になって、線と線が面になって、やる必要があるのかなと思う。そうすると、荏原地区だけでなくて、大井地区、大崎地区はやっていくのですか。その辺についてはどうですか。","respondent":"篠田文化観光課長","answer":"そうはいっても、そういった姿勢で見れば間違いない、そうではあるのですけれども、どうしても観光ですとか、イベントというのは、実際問題、海寄りのところで行われているのも間違いないところだということで、区としても、そういった意味でバランスを取りながらということで。","id":"exchange-006"},{"speaker":"藤原委員","kind":"確認","question":"部長でも課長でも確認なのですけれども、ということは、おみこし等のイベントで、品川と同じぐらい、さっきバランスとおっしゃっていますけれども、荏原のほうでもそういう声が上がったときに、おみこし中心で、それは品川とのバランスでやっていただけるということですよね、バランスなのだから。品川のほうが多い気がするのですよ、おみこし。","respondent":"山崎文化スポーツ振興部長","answer":"それぞれニーズにお応えし、かつ、にぎわい創出ですとか、社会貢献に資するようなものでありましたら、区のほうで事業スキームを考える中で様々検討してまいりたいと考えています。","id":"exchange-007"}]},{"id":"topic-02","title":"旧東品川清掃作業所（アイルしながわ）暫定活用開始","agenda":"旧東品川清掃作業所（アイルしながわ）暫定活用開始","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"説明、ありがとうあります。２点ほどお伺いしたいと思います。暫定活用ということですけれども、恒常的な活用の希望は何かないのでしょうか。それから、暫定活用した後の用途は何か考えていらっしゃるのか、この点を伺いたいというのが１つです。それから先ほどと同様、１億７,４００万円弱の予算が単費なのかどうなのか、補助があるなら、その内訳もお伺いしたいということが２点目です。","respondent":"辻スポーツ推進課長","answer":"用途、暫定活用の後の話なのですが、そちらは私どもではなくて、区全体として考えることですので、今のところは白紙という状態です。すみません、もう一つの質問は、恒常的な……。","id":"exchange-008"},{"speaker":"おくの委員","kind":"確認","question":"確認ですけれども、恒常的な活用としては、スポーツとか、アートとか、一応希望はあるけれども、予定としては決まっていないという理解でいいわけですね。分かりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"おくの委員","kind":"質問・要望","question":"すみません。それで一応意見だけ、アイルしながわが周辺再開発の種地にならないように、されないように、今一応意見としては述べさせていただいて、所管に伝えていただきたいということで、意見として述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/277018?Template=document&Id=2940#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":9718,"voices":36}},{"id":"r04-20220916-7","meetingId":"r04-cm09","date":"2022年9月16日","dateIso":"2022-09-16","committee":"厚生委員会","time":"午後 １時００分～午後 ２時５５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","topics":[{"id":"topic-01","title":"令和５年度分品川区立高齢者住宅（単身用）補欠登録者の募集","agenda":"令和５年度分品川区立高齢者住宅（単身用）補欠登録者の募集","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"高齢者住宅は毎年募集されるわけですけれども、前年度の応募者数と入居者数。前年度から３年ぐらい分かったら教えていただきたいと思うのですが。","respondent":"川原高齢者地域支援課長","answer":"こちらをご報告します。令和２年度につきましては、申込者数５５名に対して実際に登録をされた方が５４名。そのうち、入居できた方は１９名となっています。令和３年度につきましては、申込者数５８名、登録者数は５６名、入居者数は１７名です。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"申込みが年に１回しかできないので、立ち退きなどが急遽出た場合、この申請資格(1)から(5)になった方は、申込みがそのタイミングでできるかどうか。そういう様々なタイミングがあると思うので、毎回要望はさせていただいているのですけれども、この応募を年間を通して、もしくは複数回応募できるようにしていただきたいなと思っています。","respondent":"川原高齢者地域支援課長","answer":"募集回数を年に複数回に増やすことはできるかというご質問についてですが、残念ながらこの実績、例年見ていただいているように、どうしても退去者の数が少ないという状況がございまして、これを仮に年に２回としましても、実際に住める方は限られているということと。","id":"exchange-002"}]},{"id":"topic-02","title":"荏原保健センター等の仮移転","agenda":"荏原保健センター等の仮移転","exchanges":[{"speaker":"石田（ち）委員","kind":"確認","question":"荏原複合施設は、保健センターと、あとどういう種類の施設が複合するのかというのが分かれば教えてもらいたいのと、荏原健康センター。それなので、これまで利用されてきた方々や地域の方々との話合いというか、そういうのは今どうなっているのでしょうか。","respondent":"若生健康課長","answer":"健康センターの取扱いですが、委員ご指摘の、こちら旧第一日野小学校跡地に移転するということは、まだ、旧第一日野小学校跡地の本格活用について、企画部門のほうで整理をして検討をしていますので、それについては。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、その後旧第一日野小学校跡地でずっとやるわけでもなく、検討ということなのでどうなっていくか分からない状況ですけれども、行き場がなくて廃止になりますということがないように、そこは丁寧に進めていただきたいと思いますし、区民の健康の増進の場ですので、ぜひそこは今利用されている方への配慮なり、丁寧な説明とともに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"分かりました。そうですよね。それは今後のお話というところと、地域の方へのご説明をこれから始められるのですか。こういう仮移転の話と併せて、今後の本移転の話と全体のお話。これは厚生委員会の話ではないのかもしれませんけれども、地域への説明というところと、あと地域ニーズをしっかり受け止めるということを丁寧にやっていただきたいということを要望して、以上といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-03","title":"新型コロナウイルス感染症流行下における高齢者等に対するインフルエンザ定期予防接種費用の自己負担への助成","agenda":"新型コロナウイルス感染症流行下における高齢者等に対するインフルエンザ定期予防接種費用の自己負担への助成","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"要は自己負担が全額助成されずに、自己負担が発生する、今までのインフルエンザの予防接種であったというところでは、まだコロナは終息していないので、令和３年度もインフルエンザの予防接種は自己負担なしでできるようにすべきだということを、私たち共産党は求めていたのですが、そこは否定されまして、今回またこれが実施されるというところでは、新型コロナウイルスがまだ終息していないという状況と。","respondent":"坂野保健予防課長","answer":"ただ、今年は夏にかなりオーストラリアで流行したという、そういう医学的な理由でこれは決まっているというようなことです。財源ですが、昨日議決された東京都の補正予算で、東京都がこの事業にということで、７８億円計上したというのが財源です。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私たちは、無料にすべきだと思っているのです。その立場でずっと求めているのですけれども、港区、千代田区や渋谷区等々でも無料で接種を始めています。都の補正予算がついたからやるということだと思うのですけれども、であれば東京都にもぜひ求めていただきたいと思うのです。ですので、そうした観点からもぜひ引き続き東京都にも求めていただきたいなと思うのですけれども、いかがでしょうか。","respondent":"坂野保健予防課長","answer":"当該事業をずっとやってはいかがかということなのですが、今回東京都の補助金が決まって、結構急遽決まった事案でございまして、８月になってから急に決まったような状況なのですが、これをずっとということなのですが、なかなか財源の問題もありますので。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"以前コロナが流行してきた際には「インフルエンザで亡くなっている人だって多い」みたいな話が対立したりする部分もあって、インフルエンザという部分で亡くなる方もいるし、コロナでも多くの方が亡くなられているというところでは、予防していくことはすごく大事だし、命守るという立場で考えると、ほかの区でもやられているインフルエンザ予防接種の無料化というのは、十分区民の命を守るということでは。","respondent":"坂野保健予防課長","answer":"今、ご意見頂いたところです。我々もいろいろな要素を考えていきたいと思います。ご要望として受け止めさせていただきたいと思います。","id":"exchange-008"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"もう１回、先ほどの財源のところを伺いたいのですが、都が昨日議決をしたということなのですけれども、区としては大体どれぐらいの予算規模なのかというところと、これは品川区もこれから補正予算を組んでやるということなのかどうか。区で立て替えてやるのか、その辺についてのスケジュール感を教えていただきたいということが１つ。その辺りを教えていただきたいのが１つ。この３つを教えてください。","respondent":"坂野保健予防課長","answer":"これは一応国のほうがリーフレットを作っていまして、これは区のホームページで掲載する予定になっております。ただ、詳細はまだ分からない部分が結構あって、今日の午後２時半から、国の説明会があるというふうに聞いております。","id":"exchange-009"},{"speaker":"あくつ副委員長","kind":"質問","question":"最後の部分の国の説明会、オミクロン株対応ワクチンの説明会のときに、インフルエンザのことについて説明があるということなのですか。","respondent":"坂野保健予防課長","answer":"どの範囲まで説明が入るか分からないのですが、今回、この次の案件でもあるのですが、非常にいろいろ変わるものですから、今日もこの後３つ説明会が予定されています。","id":"exchange-010"},{"speaker":"あくつ副委員長","kind":"意見","question":"いろいろなことが走りながらで、初めてのことばかりだと思うのですけれども、なるべく多くの媒体を使って、高齢者の方等、障害者の方も含んでいますので、周知をぜひよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今回６５歳以上の方が対象なのですが、その人数をお知らせいただきたいのと、令和３年度の対象者数とインフルエンザの予防接種をした人数。去年ので分かれば教えていただきたいのですが。","respondent":"坂野保健予防課長","answer":"ボリューム感としては、大体６万人弱ぐらいでございまして、令和３年度で接種数が４２,１３０人です。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"対象者が６万人前後で、接種者がそのうち４万人ということですか。","respondent":"坂野保健予防課長","answer":"今年の４月１日時点の住基台帳ベースで８１,０００人ほどです。ただ、６０歳から６５歳未満の障害がある方等のカウントはこれに乗っかるという形です。","id":"exchange-013"}]},{"id":"topic-04","title":"品川区における新型コロナウイルス感染症対策","agenda":"品川区における新型コロナウイルス感染症対策","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"だからこそ、区としてできる、命守る対策が必要だと思うのですけれども、こうしたホームページの資料で出されている、２ページ目の数字等々も見て、区としてどうお考えなのか。そして、命守るための検査にしても、医療逼迫に対しての対応にしても、区でできるできないには関わらず、国としてもどうしていくことが必要なのかというのはあると思うのですが、そこは区としてはどうお考えでしょうか。","respondent":"坂野保健予防課長","answer":"そのとおりかと思います。死亡数がというお話もあったのですが、中身を見ていきますと、９０代、１００歳とかそういう方がかなり多くて、これをどう評価するかというのはいろいろな意見があろうかと思います。国が全然オミクロン株の対応策を示してないではないかというお話。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"医療が逼迫している。電話が通じたとしても「３日間は様子を見てください」と言われるのです。それをどう見るかという、そういうことでいいのですかとすごく思うのです。そういうことに対して、区として国に対策を求める。経済的な支援にしても、人材的な支援にしても必要だというふうに思いますけれども、そういったことをお考えにはならないのかどうなのかというのを伺いたかったのですけれども。","respondent":"坂野保健予防課長","answer":"８月の上旬、中旬ぐらいはかなり厳しいというのは、かなりありましたが、資料でもお示ししておりますとおり、かなり急速に減ってきておりまして、今の時点では、状況として厳しいというお話は、９月に入ってからはあまり聞いていないという状況です。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"話を聞いていても、我関せずみたいな感じがしてならないのですけれども、そういう部分では、命守る立場であって、そして専門家なわけですよね。医療機関からも、医師会からも何ら支援は施されておりませんという厳しい声も現に寄せられておりますので、そうしたところにしっかり耳を寄せていただいて、そこに対応するという姿勢をぜひ見せていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"今のところ何かお考えがあれば、教えていただきたいということが１つ。これは毎回言われていることですけれども、そういうことを考えたときに、区内の主要駅のそばに、接種会場を置いたほうがいいのではないかというような意見がありまして、ひろまち保育園がなくなってしまったので、その辺りについて、何かそういうお考えがないのかどうかというところで、２点お伺いしたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、坂野保健予防課長","answer":"今すぐにここでというお話はできないのですけども、現在もいろいろ東京都と連携しながら、場所を探しながらできるようにということで、調整を進めているです。逆にこの４類型に入っていないのは、発生届は要らないということで、ある程度ヘビーなものに関しては、医師の判断で発生届が上がるという形になっていまして、細かいところはまだ未定なのですが。","id":"exchange-017"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"前段の部分の、今、少し漏れ伝わった部分もありますけれども、主要駅でのというところをしっかり今後もなるたけ可能性を追求していっていただきたいなというところと、後段の部分については、今ご説明あったとおり、アウトラインは決まっているけれども、これからだというところで、課題は当然現場である区とすると、一番お声も届くと思いますので、まだアウトラインというところですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-05","title":"予防接種に関する事務における「特定個人情報保護評価」の実施結果","agenda":"予防接種に関する事務における「特定個人情報保護評価」の実施結果","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"配っていただいた資料の個人情報保護評価の評価書の全項目評価書というのを見ても、専門的な感じなので、よく分からないなという。それから、今後のスケジュールのところではこの評価書を提出して、公表していくということなのですけれども、公表日というのは大体どれぐらいになってくるのかというのを伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今後のスケジュールですが、まだ日にち等々は、当然確定はしておりませんが、今後評価書等々の公表は、本年度１０月以降に行っていくということで、これから調整を進めてまいりたいというふうに考えてあります。","id":"exchange-019"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"すごく受け止めてくれて、的確な答えも返していただけるので、前にも何度か求めているのですけれども、ここの相談支援センターの存在、周知をもう少し広くしていただくと、本当に医療的なところは専門的で分からないのですが、相談された側も何とかしてあげたいなという思いになるので、こういうがん相談支援センターがあるというのが分かると、相談された側も楽になるなという思いが実体験からしているので。","respondent":"若生健康課長","answer":"拾うのは難しいところなのですけれども、いわゆる生涯のうちに約２人に１人はがんになり得るということで、そういったようなかなりの率で罹患をされているということが分かっているところですが、現在罹患者数を把握しておりませんので、申し訳ございません。","id":"exchange-020"},{"speaker":"せお委員","kind":"質問・要望","question":"ご説明ありがとうございました。２点ほどお聞きしたいのですけれども、がん検診なのですが、検診の実施医療機関は、現在どうやって決められているのかお聞きしたいです。２点目が、最後の相談体制のところで、マギーズ東京とか、地域医療連携のところのがん相談支援センター。そこの具体的な流れとかが分かれば教えていただきたいです。","respondent":"若生健康課長","answer":"がん検診の実施医療機関をどのように決めているかですが、がん検診はそれぞれ部位別で実施しておりまして、実施方法が集団型と各医療機関での個別実施というところと分かれるものでございまして、まずは大きくは２つです。","id":"exchange-021"},{"speaker":"せお委員","kind":"質問・要望","question":"ありがとうございました。相談体制のほうに関しては理解いたしました。そこも大事なのですけれども、そこからつなげていくこと。地域医療連携の部分というのもすごく大切にしていただきたい。引き続き、よろしくお願いします。医師会所属にしろ、区独自にしろ、見直す時期というか、定期的にそういったこともやっていただけるとうれしいと思って、そこは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"あくつ副委員長","kind":"確認","question":"所管事務調査、がん対策についてということで、まとめていただいて、ありがとうございました。本当に現健康推進部長が品川区にいらっしゃってから、がん対策については、飛躍的に進んだのかなと個人的に思っています。それで、幾つかお伺いをしたいのですが、まず、すみません。そういうところをまず教えてください。","respondent":"若生健康課長","answer":"こういった方法というのは視野に入れて、検討していきたいと思います。","id":"exchange-023"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"結論まで言っていただいてあれなのですけれども、江東区。これは若干距離的なものがあった中で、国道３５７号の海底トンネルが開通して早くはなったのですけれども、なかなかすぐに行けない方もいる中で、オンラインの活用というのは、区民にとって利便性もありますし、こういったこともぜひ内容に加えていただきたい。そこのところを教えてください。","respondent":"若生健康課長","answer":"ただ、令和２年度は前半緊急事態宣言があって、そこでは国の通知等に基づいて、検診を当面やらない対応としていたこともあって、全体として見ると、伸びが見えづらくなってしまって、微増にとどまってしまっているのですけれども。","id":"exchange-024"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"厚生労働省とか東京都のほうも、コロナでもがんは待ってくれないというような、結構きつい文言のポスター等で周知をしていましたが、品川区としては、そこのところは強く周知をされているのかどうかというところと、品川区において、コロナの受診控えについて今何か情報があれば教えてください。","respondent":"若生健康課長","answer":"コロナ禍によって、受診控えの影響というところで言いますと、令和２年度の前半の、先ほど申し上げた緊急事態宣言のところで、休止があったものですから、そこで受診ペースが落ちたということがありますが、その後順調に回復をいたしまして、令和３年度に関しましては。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/831364?Template=document&Id=3640#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":30504,"voices":82}},{"id":"r04-20220916-8","meetingId":"r04-cm09","date":"2022年9月16日","dateIso":"2022-09-16","committee":"建設委員会","time":"午後 １時００分～午後 ３時４３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","topics":[{"id":"topic-01","title":"会議の運営上、予定表の順番を入れ替えまして、(3)令和４年１１月都営住宅入居者募集","agenda":"会議の運営上、予定表の順番を入れ替えまして、(3)令和４年１１月都営住宅入居者募集","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"これまでの実績を伺いたいと思うのですが、募集戸数と応募数、倍率を伺いたいと思います。それで今回、資料では申込用紙配布期間として１１月１日から１１月１０日となっておりますが、申込み期間はいつまでになるのか、伺います。","respondent":"竹田住宅課長","answer":"過去の募集状況ですが、前回、令和４年５月が、東京都全体で３,７０７戸でございまして、品川区内では８住宅１９戸の募集がございました。申込み期間は、それも含めましてプレス発表ですので、承知していないところです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"分かりました。この間の募集の倍率を見ても、５月には最大１３７倍で、前年度同時期は３９倍ということですので、やはり都営住宅というのは求められているなと思いますので、区としても都営住宅の増設を求めていただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]},{"id":"topic-02","title":"地震に関する地域危険度測定調査（第９回：東京都）結果報告","agenda":"地震に関する地域危険度測定調査（第９回：東京都）結果報告","exchanges":[{"speaker":"横山委員","kind":"確認","question":"ご説明ありがとうございました。理解いたしました。こちらの係数の変更ということで、実態に即したものが採用されているということですけれども、今回こういった都の調査の公表があって、この結果を受けて、今後、品川区ではどのように計画ですとか計画以外の部分に反映されていくのかというところだけ確認させてください。最後にお願いします。","respondent":"大石木密整備推進課長","answer":"今後の対応ですが、建物倒壊・火災危険度につきましては、先ほどご説明したとおり、危険度がほとんどの町丁目で減少しており、特に不燃化特区指定地区における火災危険量の減少は大きいものとなっております。事業の成果が一定程度出ているものと考えます。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"今回の地域危険度測定調査、先ほど総合危険度については変更点のお話があったのですけれども、ほかのところの変更があったのかどうか、そこを伺いたいのと、この評価は相対評価で行われていると思うのですが、なぜ相対評価で行われているのかということを伺いたいのですが、というのは、その地域が改善されていっても、ほかがよくなってしまうと、最悪の場合、ランク５にもなり得るということで。","respondent":"大石木密整備推進課長","answer":"なぜ相対評価かということですが、東京都から詳しくは説明を受けていないもので、確定的な発言はできないのですが、確かに委員がおっしゃったとおり、各地域で防災の取組みを行って、ただ、ほかの地域が頑張って、そうすると。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"危険量に着目されているということです。今回、基本的には改善しているということかと思うのですが、総合危険度のところで見るとあまり変わりないという状況になっておりますけれども、先ほど少し説明がありましたが、こういった結果になっている理由と、改善した理由を伺いたいと思います。","respondent":"大石木密整備推進課長","answer":"総合危険度についてですが、先ほど申したとおり、前回から、まちの中の状況を見ましても、データ的にもそうですけれども、状態が悪くなっているとは考えてございません。こちらは、不燃化特区の取組みを平成２５年度から導入いたしまして、前回調査ではそこまで反映し切れていなかったものが、除却や皆様のご協力の下、防災活動広場だとかが順次整備されてきておりますので。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"これをさらに推進していくことが重要だと思うのですけれども、今、２９号線など特定整備路線の整備が防災性向上を口実に進められていますが、木造住宅の建て替えを進めていくということを、それを大きく推進していくということを行っていけば、特定整備路線は必要なくなると思うのですが、いかがでしょうか。","respondent":"大石木密整備推進課長","answer":"特定整備路線につきましては、東京都により事業が実施されているものです。特定整備路線は、震災時の延焼遮断や避難路、緊急車両の通行路となるなど、震災時に特に甚大な被害が想定される整備地域の防災性の向上を図るものです。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"引き続き特定整備路線を進めていくということですが、道路を２０メートル造っても、火の粉が飛んでしまうということもありますし、そうした事業の下で住民が追い出されると。多くの方が追い出され、これまで住み続けてきたのに住み続けられなくなってしまうという重大な問題がありますので、特定整備路線は進めないようにしていただきたいと、これは強く要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"こんの委員","kind":"質問・要望","question":"参考までに伺いたいと思います。例えば大井２丁目なんかも木密に入りました。ここも感覚的に言うと、そう活動できるスペースがある地域かなと思うと、そんなふうには。なので、活動できる空間とはどういうものを指し、どんな活動ができるものなのかを教えていただきたいと思います。","respondent":"大石木密整備推進課長","answer":"強いて言うならば、今お伝えしたとおり、広大なスペースがないだとか４メートル以下のところが多いだとか、そういったことが危険量に反映されているものと考えております。","id":"exchange-008"},{"speaker":"こんの委員","kind":"質問・要望","question":"イメージが湧きました。そういったところを見て、危険度の中の１００位に入ったところの危険度も入ってきていると。どうしてもこういうものが出ると、それで安堵してしまう地域と、もっと危険を感じてしまう地域とがあって、でも、やはり数字だけでは表せない危険な実態はあるかと思いますので、その辺を、これを参考に、これからも進めていただきたいと思います。お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"西村副委員長","kind":"質問・要望","question":"こんの委員と重なってしまうところがあるのですが、災害時活動困難係数を下げるには、防災広場と地域の方々の理解とご協力が必要になるということで、ご説明を受けて理解したのですが、一見、この資料を拝見しただけでは、特に二葉地域の総合危険度が上がったのだなと感じまして、今細かくご説明を受けて見ていきますと、なるほどと理解したところがありまして、ホームページなどに告知をしていただく際に。","respondent":"大石木密整備推進課長","answer":"周知の方法ですけれども、東京都の公表資料ですので、区のホームページに掲載するかどうかというのは今後検討しなければいけないですが、今、実際、二葉、西大井とか豊町のほうでも、まちづくり協議会だとか勉強会だとか、こういったところで職員が自ら説明して。","id":"exchange-010"},{"speaker":"西村副委員長","kind":"意見","question":"すみません。２から４に上がっております。これだけ見ると確かにびっくりしたのですが、町会のほうまで来てご説明いただいていることも知っておりますので、引き続きお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"}]},{"id":"topic-03","title":"品川区まちづくりマスタープラン改定に向けた検討状況","agenda":"品川区まちづくりマスタープラン改定に向けた検討状況","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"第５章以降の骨子案の最後のところで、マスタープランの進行管理というのがありますが、これは５年のサイクルで行っていくということで、いろいろ、都市計画基礎調査ですとか、評価指標を設定して、その後もまた都市計画基礎調査をやるのですかね、こういったところ、まちづくりの改善検討とありますけれども、どういった検討を行っていくというか、仕組みというのですか。","respondent":"鈴木都市計画課長","answer":"いただいた主なご意見の中では、第４章で強靭なまち、改定計画でも防災の取組みを積極的に進めていくと記載しておりますが、それと、もともとのマスタープランの住み続けたいまちというところ、それから強靭なまち、見え方が非常にダブる。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回新たに書かれたのだと思いますが、この中身というのですか、どういうことなのか、ブランド力というのは何なのか、伺いたいと思います。そして、戸越公園駅周辺では、踏切の解消に向けて立体化を進めていくということがありますけれども、その立体化と一体にまちづくりを、特に再開発を進めていくというのはやめていただきたい、位置づけない、位置づけるべきではないと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"最後のマスタープランの進行管理のところで、東京都の基本的な調査が５年ごとに行われているですので、サイクル的には、直近に行われた調査が来年度以降に公表されてくるようなところもございまして、そうしたものを見ながら、いろいろな指標を検討しながら、次の５年後。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、ブランド力というところで、戸越公園駅周辺まちづくりビジョンだと思いますけれども、それが書いてあるということで、今、具体的な整備計画はないということでしたが、公共施設の整備検討という中には、荏原第四中学校跡地が入ってくるのかどうか伺いたいのと、ブランド力というのが、再開発のマンションなどを売るためのブランド力向上という印象を受けるのですが。","respondent":"鈴木都市計画課長","answer":"当然、その過程で、地域周辺への説明ですとか合意形成ですとか、そうしたところは区もしっかり支援させていただきながら、丁寧に進めていっていただくように、区としても最大限支援させていただきながら進めていきたいという考え方は。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"荏原第四中学校跡地はエリアに入るということですので、ここを再開発に利用していくということがないようにしていただきたい。これは要望しておきたいと思います。そうした下で再開発を進めていくというのはやるべきではないと、これも強く求めておきたいと思います。先ほども述べさせていただきました。耐震化・不燃化こそ進めていくことが必要だと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"東京都が進めます特定整備路線、これは延焼遮断帯の形成に資するとともに、道路ネットワークの形成にも資するというところで、こうした取組みとともに、これだけでは当然、地域の防災性の向上にはつながっていきませんし、一方で。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうした下で、住民の生活は救えないと思います。そして一緒に伺わせていただきますが、今回、羽田空港アクセス線の駅設置の要望も検討すると書かれておりますが、これは以前にも発言させていただきましたが、この要望はやめるべきだと。多額の税金がかかってくると思いますので、コロナなど、様々、区民の生活を支えるためにこそ、大切な税金は使っていくべきだと求めていきたいと思います。","respondent":"鈴木都市計画課長","answer":"特定整備路線だけで喫緊の防災対応に向かっていけるのかですが、それは、何度も繰り返しの答弁になりますが、特定整備路線の整備だけで全ての防災性の向上が進んでいくとは考えてございません。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"特定整備路線は位置づけないように、これは強く求めておきたいと思います。それと、以前、中延を生活拠点に位置づけた理由をお伺いしたのですが、今回、新たに立会川も位置づけるということで、立会川を位置づけた理由も伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"その中に立会川駅も含まれてありますので、やはり区としては、そこを含めて地域のまちづくりをしっかり進めていきたいというところで、今回、生活拠点としての位置づけをさせていただいたです。","id":"exchange-017"},{"speaker":"こんの委員","kind":"質問","question":"参考までに、この素案の各ページにあるのですが、ページ数でいうと４－１４ページ、だけではないのですが、作成中という絵、イメージ図ですか、作成中ということで、特に４－１４のところをお聞きしたいのですが、これは特に都市基盤というところなので、どこかステーション、駅を中心に絵を描かれると思うのですが、作成されるのはアナログの絵なのですか。そこをお願いします。","respondent":"鈴木都市計画課長","answer":"各分野別に、今、ラフスケッチで置かせていただいている絵については、将来的なまちづくりのイメージになりますので、どうしても写真だけで全てを表すことは難しいということで、一方で、文字だけではなく、パース的なところの絵として。","id":"exchange-018"},{"speaker":"こんの委員","kind":"質問・要望","question":"４－１５ページと４－１６ページに記載があるところの具体的なイメージを教えていただきたいのですけれども、「2)多様なひとの移動や回遊を支える環境を充実する」の中の黒丸４つ目のところです。再開発事業等に合わせた道路やデッキ等の整備により、駅とまちをつなぐ安全で快適な歩行者ネットワークの形成を推進します。具体的に何か計画を模索しているものがあるのか。その辺を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"東京都が数年前に２ルート目の考え方を示しているところもあって、それは国のほうの法律だったか要綱だったか、記憶があれなのですが、国のほうでもこれまではまずは１ルート整備しましょうということだったのですけれども、より多くの方に利便性を高めて利用していただくために。","id":"exchange-019"},{"speaker":"こんの委員","kind":"質問","question":"大井町駅周辺エリアというところで、「4)バリアフリー計画に基づく、歩いて安全・安心なまちづくりの推進」、5)については「にぎわいと居心地の良い空間を創出する道路空間の柔軟な活用を推進」とありまして、上の図で見ると、大井町駅の紫色に囲った１のところで、これは本当に細かいことで恐縮ですが、この地図のこのエリアを見ると、私の勝手な解釈ですが、駅のちょうど南側。","respondent":"鈴木都市計画課長","answer":"それとともに、大井町周辺は、大井町エリアのバリアフリー構想もありますので、その中では間違いなく書かせていただいておりますし、今後、バリアフリー構想のほうも、このマスタープランを踏まえて、場合によっては見直しをかけていかなければいけないわけですけれども。","id":"exchange-020"},{"speaker":"こんの委員","kind":"質問","question":"この地図上だけではまだ分からないところだと思いますが、今ご答弁いただいたように、入っているものと信じていきたいなと思うのですが、いずれにしても、大きい駅、小さい駅、これからのまちづくりでバリアフリー化して、皆さんが歩きやすい、また、そこからいろいろなまちにつながっていくこの歩行空間というのは非常に大事な視点だと思いますので、ここがより具体化できるような、また、言葉の表現で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"横山委員","kind":"質問・要望","question":"ご説明ありがとうございました。私は、資料２の７ページ、第６章のところを中心にお伺いさせていただきたいのですけれども、「マスタープランの実現とまちづくりのマネジメントの展開」というところで、特に2)ですが、今後、地域主体でまちをつくる取組みとともに、つくられたまちを地域主体で育てることが重要ということが書かれています。","respondent":"鈴木都市計画課長","answer":"そのときに、やり方は、手元にないのですけれども、若い方にも抽出の過程で、年齢を一定程度入れたかどうかで、若い方からも意見をいただけるようなアンケートの取り方で、工夫を重ねて、アンケートの結果についてもその辺が分かるように整理をして。","id":"exchange-022"},{"speaker":"横山委員","kind":"質問・要望","question":"この間、静岡県焼津市に視察にいってきまして、一般社団法人トリナスの土肥潤也さんという、子ども・若者のまちづくりをやっている方のお話を伺ってきたのですけれども、詳しくは時間の関係上、割愛しますが、やはり子ども・若者を中心としたそうした取組みというところで、中心といいますか、本来は子ども・若者を含めて全世代の皆さんで中心になって進めていくというところだと思うのですけれども。","respondent":"鈴木都市計画課長","answer":"ある意味、そうした方が、家に帰ってお子さんにいろいろ聞いたり、あるいは周辺のお母さん、あるいはそのお子さんに聞くとか、まさに関わり的には薄いのですが、そうしたご意見の募集の仕方、いただき方というのは、今、委員にご説明いただいて、しっかり頭に入れて。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"ワークショップなど、具体的に問題点・課題点、住民の皆さんと一緒に問題や課題解決に向けて話し合うワークショップを実施したほうがいいのではないかと思うのですが、いかがでしょうかというのと、あと、今回、冊子になっている改定素案の中で、イメージ図で作成中となっているのが結構あるのですけれども、今までこういったものがいっぱいあるというのはあまりなかったかなと思うのですが。","respondent":"鈴木都市計画課長","answer":"改定計画を進めていく中でのワークショップの実施についてですが、基本的にはまちづくりに関する区民アンケート、それから明日以降のオープンハウス型説明会、全体的には公募区民の方あるいは地域の方にも入っていただいて、区内関係団体の方にも入っていただいて改定委員会。","id":"exchange-024"}]},{"id":"topic-04","title":"（仮称）勝島人道橋整備事業説明会","agenda":"（仮称）勝島人道橋整備事業説明会","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"住民への周知についてですが、ビラの掲示とポスティングをするということで、ホームページにも掲載するということでしたが、ビラのポスティングをする範囲を伺いたいと思います。特に勝島方面がどうなるのか、八潮の人にもやるのかどうか、そういったところも含めて伺いたいと思います。","respondent":"森道路課長","answer":"ビラのポスティングにつきましては、全部で８,５００世帯ほどを予定しておりまして、場所といたしましては、東大井１丁目、東大井２丁目、勝島１丁目、勝島２丁目のそれぞれ全域と、南大井１丁目の競馬場通りよりも北側の部分と考えているところです。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ多くの方に知っていただきたいということで、周知をお願いしたいと思います。これから設計なので、細かいところは分からないと思うのですが、概算などあれば伺いたいと思います。災害時の避難にも資するということで今回計画されておりますが、そうすると、首都直下地震とかが起きたときに、どこまで耐えられるのかという耐震性のところがどういうふうに進められているのか、伺います。","respondent":"森道路課長","answer":"耐震性ですけれども、当然最新の耐震技術に基づきまして設計・施工を行っていくということでございまして、レベル２地震動についても耐えられるものを造っていきたいと考えています。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"水面の幅を３０メートル確保するということだったので、今はそれ以上あるということですよね。それと、今、花海道の上と下のところで歩けるところがあると思うのですけれども、こういったところはどうなってくるのか。イメージ図で見るとよく分からないところがあるので、そこのところを伺いたいと思います。","respondent":"森道路課長","answer":"ですので、運河の幅が変化するところですので、多少、今の護岸を改修する必要も出てくると思いますけれども、イメージパースですので、今、そこまで詳細に詰めているわけではございませんが、こういった形で今は考えているです。","id":"exchange-027"}]},{"id":"topic-05","title":"源氏前公園・源氏前特定児童遊園改修工事","agenda":"源氏前公園・源氏前特定児童遊園改修工事","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"確認で、トイレのところですが、バリアフリートイレ１基ということで、そうすると、便器が１つという、個室が１つという形になるのかどうか、そこを伺いたいです。","respondent":"高梨公園課長","answer":"最初にトイレですが、申し訳ございません、詳細に説明しておりませんでしたが、現在、男女それぞれ和式便器１基ずつなのですけれども、改修後は、男性用のトイレ、小便器と大便器、女性用のトイレ、大便器、それとバリアフリートイレ１基ということで。","id":"exchange-028"},{"speaker":"横山委員","kind":"質問・要望","question":"そうしたことが進んでいくといいなという思いがありまして、こうした一部分でも、例えば都ですとかの予算をうまく使っていけるといいのかなという、これは区の問題、区の課題ではないのですが、そうした要望ですとか、何か意見交換の際には、使いやすい、こうした単費で実現した事例等もうまく説明といいますか、事例といいますか、そうしたものにしていただきながら。","respondent":"高梨公園課長","answer":"これからも、東京都を含めて、インクルーシブ遊具については、品川区以外の各区市町村、積極的に設置が進んでいくものというふうに考えているという話を東京都から聞いてありますので、引き続き様々な情報を得て、財源等については積極的に活用できるように。","id":"exchange-029"}]},{"id":"topic-06","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"横山委員","kind":"質問","question":"治水対策について、まず表面のところからお聞きしてまいります。今後の改定スケジュールというところですけれども、２点お伺いさせてください。都の検討会が今年８月に設置されて、基本方針の改定を検討中ということで、こちらに２つ、方向性と論点ということで書かれております。","respondent":"栗原河川下水道課長","answer":"ただ、それだけでは、せっかくこれまで検討していた内容が、２年間ほど後ろになってしまうので、今年度にこれまでの総合治水対策推進計画で取り組んできたことの成果をしっかりまとめようと考えております。","id":"exchange-030"},{"speaker":"横山委員","kind":"質問・要望","question":"こうした都が行うような役割分担があると思いますので、大きなといいますか、様々役割分担の中でできることというのが変わってくるかと思うのですけれども、こうした助成の部分、このコロナ禍で、全額助成というわけではないので、数字で表れてくる部分というのはなかなか難しいところもあるのかなと思うのですが、こうした取組みがされているということ、また、区にできること、今。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"こんの委員","kind":"確認","question":"３点伺いたいと思います。裏面の立会川のことですけれども、丸ポチの２つ目です。この能力増強、どれぐらいの能力が増強されたのか、今一度、確認したいと思います。３点目が、その下の暫定対策として品川区で溢水防止板を整備済みということですが、この地図上でその溢水防止板が見当たらないのですが、これはどういうものだったのか、確認させてください。お願いします。","respondent":"栗原河川下水道課長","answer":"浜川幹線の役割といたしましては、浜川ポンプ所に流れ込む雨水を下流の勝島ポンプ所に切り替えるものです。当該流域は、浜川ポンプ所というのが昔の設計基準で設置されたものでございまして、５０ミリの雨に対して５０％の雨が染み込むという設計をかつてしたものです。","id":"exchange-032"},{"speaker":"こんの委員","kind":"質問","question":"ご説明ありがとうございました。よく分かりました。増強されたということは、５０％から８０％の雨が流れ込むような形にしてくださったということで、大変ありがたいものが完成したと思います。この取りまとめといったところは、どんなイメージでこれを取りまとめていくのか、教えてください。","respondent":"栗原河川下水道課長","answer":"２年先送ったときの影響、先ほどありましたけれども、河川や下水道の整備そのものにつきましては、都の計画に基づいて実施していくものですので、影響はないものと考えております。","id":"exchange-033"},{"speaker":"こんの委員","kind":"質問","question":"分かりました。今のご説明でいくと、区の役割の部分を中心に取りまとめていくといったところですので、そうすると、東京都の検討状況を踏まえた改定検討となると、東京都は東京都でどういう計画で来るか、それをベースにですが、それを待たずしても、品川区としての役割分担のところでは、改定というか、ある程度の改定計画、推進計画、こうしたものは進められるという理解でいいのでしょうか。","respondent":"栗原河川下水道課長","answer":"今年度まとめようとしております取りまとめの中でも、従前の計画に基づいてやってきた成果、それから都の検討状況を踏まえることではあるのですけれども、引き続き品川区の役割というのは流域対策をしっかりやっていくですので、その旨をしっかりと取りまとめ。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問","question":"先ほど各区内での浸水被害の発生状況をご説明いただきましたが、直近で浸水被害があったのはいつで、どこなのかというところを伺いたいのと、品川区での取組みが今どこまで進んでいるのか。都の基本方針だと区部では時間７５ミリというところですけれども、そこに対して区がどこまでいっているのかというところを伺いたいのと、全体の計画として、改めて区が課題と感じているところを伺いたいと思います。","respondent":"栗原河川下水道課長","answer":"こちらが完成すれば、取組みは進んでくるものかなと考えています。課題というと、立会川周辺と戸越周辺につきましては、現在整備を進めているという状況ですので、これらの整備を着実に進めていくことと考えているところです。","id":"exchange-035"},{"speaker":"のだて委員","kind":"確認","question":"なかなか具体的には答えづらいでしょうか。目黒川のところでは、一定対策をしてきて、そうすると、時間７５ミリ降雨への対策は、この工事ができれば完了するということなのかどうか。戸越、立会川についてもそうですけれども、この工事が終了すれば、７５ミリ雨量に対しての対策ができるのかどうか、そこを確認したいと思います。","respondent":"栗原河川下水道課長","answer":"優先順位が高いところから７５ミリ対策はやっていくというのが都の方針ですので、引き続き都と連携して事業は進めていきたいと考えています。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問・要望","question":"まだ５０ミリ対策をしていかなければいけないところもあるというお話だったので、そういったところも含めて、ぜひ東京都にも求めるなり、品川区としても浸水被害がなくなるように対策を進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"西村副委員長","kind":"質問・要望","question":"先ほど区内全域での貯留効果の成果を伺ったのですけれども、雨水浸透機能の重要性について区民の皆様により知っていただくためにも、特に河川に近い地域ですとか、雨水の流出を抑制する施設の効果ですとか、下水道の河川整備との関係性など、地域ごとに見ることが可能なのかどうかを、不勉強ですみません、お伺いさせていただきたいのと、あと、このような人工的な浸透施設が今後増えていったときに。","respondent":"栗原河川下水道課長","answer":"浸水対策に関する地区のＰＲですけれども、特に工事を実施している近傍、今、第二戸越幹線等の工事を実施しておりますが、地域の方には工事の実施についてお知らせして、河川と下水道の役割ですとか必要性等は説明させていただいているところです。","id":"exchange-038"},{"speaker":"西村副委員長","kind":"質問","question":"雨の降り方が昔と大分変わってきたなと思っていますので、区民の皆さんの水害関係の関心も随分高まってきているなと思いますので、これぐらい雨水の流出がこの施設で抑制されたよというようなことが分かれば、より皆さんにも知っていただけるのかなと思いましたので質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/979224?Template=document&Id=4360#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":47757,"voices":135}},{"id":"r04-20220916-9","meetingId":"r04-cm09","date":"2022年9月16日","dateIso":"2022-09-16","committee":"文教委員会","time":"午後 １時００分～午後 ６時０４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を69件抜き出しています。","topics":[{"id":"topic-01","title":"令和３年度保護者アンケートおよび児童・生徒アンケートの結果","agenda":"令和３年度保護者アンケートおよび児童・生徒アンケートの結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"自由に遊ぶ時間というものが取りづらい状況の子どもも多いのだなというように実感しました。これは感想です。質問に入ります。保護者のほうですけれども、６番の「義務教育段階で重要だと思うことは何ですか」という質問なのですが、今、学びからの逃走とか、勉強嫌いの増加ですとか、あるいは精神的幸福度が国際的に著しく低いという点が、度々調査などでも指摘をされています。","respondent":"中谷指導課長、矢部教育総合支援センター長","answer":"毎年こちらについて質問していく中で、ちょうど今年までの３年間で一回りアンケート項目を実施できた形になりますので、次年度また新たなアンケート項目をつくる中で参考にさせていただきたいと考えています。コミュニティ・スクールにつきましては、学校によっては、コーディネーターが通信を出していましたり、各ボランティアの方たちが関わって、学校にいろいろ協力してくださっている、それはもうお子さんたちを通して、また学校公開等で。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"そうですね。子どものアンケートなのです。これは別に品川区に限ったことではないかもしれませんけれども、ここはやはり課題として向き合って、現場の意見を聞いて、その課題をどう解決するかというところで頑張っていただきたいと思いますということと、あと何で学年が進むにつれて減ってしまっているのかということを、どのように考えているかということもお伺いしたいということが１つです。","respondent":"中谷指導課長","answer":"教育委員会では教育検討委員会という組織を持っておりまして、教科部会というところで、今英語科で授業改善を話し合うという会を持っておりますので、そこでも話題にしていきたいなと考えています。それから、ＩＣＴに関して申し上げます。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"それは口で言うほど簡単なことではないのですけれども、ぜひ現場の教員の方々のご意見をしっかり聞いて、そういった学んで楽しいというような学校をつくっていっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"ですから、保護者による学校満足度が９割以上肯定的な回答であると受け止めるのは、少し違うのではないかというところを、まず伝えたいなと思います。これに安心しないでいただきたいというか、保護者も本当に今、コロナ禍もあって、なおさら学校の中が見えていない状況があるので、実際の声はこれとは違うのではないかなということは、保護者の１人として思いました。そして次です。","respondent":"中谷指導課長","answer":"「義務教育段階で重要だと思うことは何ですか」の説明に関しての経年変化というところなのですが、こちらの設問が、３年に一度取るというタイプになっております。３年前とあまり変わらないという分析結果を持っております。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問","question":"このアンケートの教育施策の成果の検証という目的からはちょっとそれてしまうかもしれないのですけれども、２年生以上の全児童・生徒とその全児童・生徒の保護者を対象にされているアンケートであるならば、ぜひ自由記述を設けてもらって、子どもたちがふだん本当に悩んでいることなども言えるような、これから体罰調査などがされると思うのですが、そこでも書きづらいようなことなどが。","respondent":"中谷指導課長","answer":"ただ、今区としてやっているアンケートと並行して、各学校の中で学校評価というようなこともやっておりますので、１つの学校の中で今後何が行われるかというと、この区全体の傾向と自分の学校で出てきた結果、ある程度この２つを見ることで、自分の学校の中でより。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"自由記述のところ、いろいろな子どもたちの声をいろいろな場面で聴く体制があるよという姿勢を見せるためにも、ぜひ前向きに、自由記述の項目は何でも書いていいよということを示した自由記述の項目をぜひお願いしますということを求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"渡部委員","kind":"質問","question":"ちょっと回答率のところを見ていて、保護者のアンケートは子どもに持ち帰らせて、いついつまでに出してね、なのですか。逆に児童・生徒のアンケートというものは、ホームルームか何かの時間といいましょうか、どこかの時間でやってもらっているのか、それともやはりこれも持ち帰りでやってもらっているのか、ちょっとその辺をまず先に教えてもらっていいですか。","respondent":"中谷指導課長","answer":"そしてお子さんについては、その場で、学校の中で書いていただくというようなところで取っているものになります。毎年回答率というものは、ここ数年ずっと大体約９割というような形で推移しているところになります。","id":"exchange-007"},{"speaker":"渡部委員","kind":"質問・要望","question":"それとついでにといいましょうか、聞きますけれども、例えば近隣自治体、これはもう品川区の教育施策のアンケートですから、これはこれで皆さんがデータを毎年蓄積して、このようなものなのだということの確認であり、次の施策に活かすのはいいのですが、もし他自治体などで似たようなことをやられていて、それと何か比較をしたりなどということはやったりしているのか。","respondent":"中谷指導課長","answer":"３ついただいたかと思います。１つ目なのですけれども、子どもの回答率が１割足りていないというところなのですが、１年前に取った回答率よりも、若干低い傾向になっています。","id":"exchange-008"},{"speaker":"若林委員","kind":"質問","question":"保護者のアンケートの６番の「義務教育段階で重要だと思うことは何ですか」と、この数字がすごくどう解釈したらいいのかなと微妙な、「基礎学力をつけること」で、複数回答なので１００とか９０に近いぐらいの数字があるのかなと思ったのですけれども、６０％の後半ぐらいと。ちょっと教えてください。","respondent":"中谷指導課長","answer":"一方で、先ほど申し上げたその他の回答の中で、人間関係を非常に大事に、重きを置いてというような項目が、その他の自由記述のところであったところなのですが、これも一定の割合で出ているということもあるので、学力。","id":"exchange-009"},{"speaker":"若林委員","kind":"質問","question":"ほかの項目と比較する必要は、私はないのかなと思うのです。義務教育だから基礎学力をつけるのは当たり前でしょといって、あえて丸をつけない人もたくさんいらっしゃるのかなと。そのように解釈したとすると、それは大分保護者の気持ちに近いものなのでしょうか。もう１回聞かせてください。すみません。","respondent":"中谷指導課長","answer":"できればこの項目も９割、１００％を目指さなければいけない項目だとしっかり思っておりますが、義務教育段階で重要だと思うことに期待するというのは、やはり個々によっても認識が違うということが、この項目だけでもかなりいろいろなばらつきもありますので。","id":"exchange-010"},{"speaker":"渡部委員","kind":"質問","question":"１点だけ、すみません。今の若林委員の質問、まさにそのとおりだと思うのですけれども、先ほど冒頭聞いて追いかけなかったのですが、複数回答可ですかというところで、制限しなかった場合は、答える側が、私だったら全部丸をしてしまうといった人もいれば、１つしか丸をしない人もいます。ですから、その設問の仕方を少し気をつけていただければ、ぐっと上がってくるのかなと思います。答弁結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"松澤副委員長","kind":"質問","question":"市民科もコミュニティ・スクールもすごくいい取組なので、何かアンケートの中でもっと掘り下げて、ではコミュニティ・スクールで、例えば何がいいですかとか、このように掘り下げてやることが、子育て、親育てにつながるのかなと思っていまして、コミュニティ・スクールも市民科も、もう少し掘り下げたアンケートをやっていただけると、理解度もますます広がっていくのかなと思うのですけれども、そこの２点。","respondent":"中谷指導課長","answer":"その意味においては、年齢によってその扱う活動というものが異なるわけなのですけれども、その中で、好奇心に応えられるような活動であったりとか、何か難しいタスクではあるけれども乗り越えられた、英語を使えたのだというような達成感を持たせられるような活動を計画し。","id":"exchange-012"}]},{"id":"topic-02","title":"特別支援学級（難聴通級指導学級）の移設","agenda":"特別支援学級（難聴通級指導学級）の移設","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと、台場小学校の通級の実態なのですが、現在専用の教室を充てているということなのか、教員の配置の人数や、あるいは専科の方なのか兼任なのか、そのような指導体制についての現状をお伺いします。","respondent":"矢部教育総合支援センター長","answer":"基本的には、補聴器をつけてどのようにして聞いたらいいかとか、また、そのことで保護者や先生方に指導方法の工夫をお伝えするお仕事ですので、何か専科などということではなく、全体的に２人の先生が難聴の指導しているという体制になっています。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと利便性が大変ですねというような、そのようなことがあったのかをお伺いしたいということと、あとその方針決定に至る検討経過というのは、今回このような報告があったわけですけれども、どのような検討をいつぐらいから重ねていたのかということをお伺いしたいと思います。","respondent":"矢部教育総合支援センター長","answer":"そこが大きなところでございまして、総合実施計画の中でも、２年前から開設準備という予定を立てておりまして、人数の多い少ないはありますけれども、個々に事情を考えた中で、教育委員会の中で学校とも話し合いながら情報収集して判断したものです。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと経過が分からなかったので伺ったのですけれども、台場小学校の通級移設後の体制なども先ほど聞いたのですが、特に場所が空くとか、そのようなわけではないということなのか、台場の通級を移設したら、台場で使っていたところが空くなどということではないということなのか。","respondent":"矢部教育総合支援センター長","answer":"２点いただきました。場所はこちらでもきちんとご説明を申し上げて、移設ということになれば、この後はそこの部屋は、現状はまだ計画しておりませんので今のところは空くというように考えております。計画はまだそこまでは詰めておりません。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"昭和３９年から活動していたということもありますので、当事者、実際に今台場小学校で在籍されている児童への配慮というものは聞きましたけれども、よく関係者の方々に説明の上でご意見を伺って、そのご意見をきちんと踏まえて、進むなり戻るなりしていただきたいと私は思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"周知なのですけれども、いつ頃保護者会などが行われるのかを伺いたいということと、あと難聴の通級があるから台場小学校の近くに引っ越したとか、そこを選んだという方、就学前の方たちもいらっしゃると思うので、そういった方たちへの周知の部分などをどのように考えているのかということを伺いたいということと、あと現在豊葉の杜学園にあるのは、中学生からの後期課程のものだったということですけれども。","respondent":"矢部教育総合支援センター長","answer":"こちらでご説明させていただいて、早速学校のほうで、周知については、保護者会のほうも含めて、きちんと詰めて進めていきたいと考えています。できるたけ早めにとも考えています。","id":"exchange-017"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２つ目、２枚目のほうなのですけれども、１年間の指導期間の話で、変更点の理由が書いていますけれども、その前に変更点が１年ということですが、ほかにも特別支援担当教員が担当する子どもの人数が、これまで１０人だったものが１２人になってしまったということも重大だと思うのですけれども、この変更点の記述がないのはなぜなのかなということをお伺いしたいということと。","respondent":"矢部教育総合支援センター長","answer":"変更については、東京都が示してきたところもありますので、東京都の理由がこのようなところで、制度変更という意味では、我々としましては、お子さんが原則１年の指導で教室に戻ってくるというような認識でございまして、そもそも、これも東京都の説明にもなりますが。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"現状より悪くなってしまっている、国は１３人になっていると言うかもしれないですけれども、１人で１０人だったものが１２人になっているわけですから、現状は改悪なのです。やはり１人、しかも特別支援ですから。ですから、１２人でなく、きちんと加配もして区独自にやってほしいという要望が出ております。ぜひいかがでしょうかと。それと、これは即時に解決すべきだと思いますけれども、いかがでしょうか。","respondent":"中谷指導課長、矢部教育総合支援センター長","answer":"先ほどの教員の数というところですけれども、今回の変更についても把握しておりまして、今回、こちらの都のスキームについては、またこれから特別区のほうでも要望を出していきたいなと思っているところです。専用教室については、基本的には専用教室はあると認識していますが、指導主事が観察に学校によく参りますので、実態をよく把握して、これからも子どもたちに良好な環境が届けられるように進めてまいりたいと考えています。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"改善すべきだと思うのですけれども、どのような改善策を取るのかはいろいろあると思うのですが、その辺をお伺いしたいということが１つ。なおかつ、その延長終了後には３年目以降の継続等についても総合的に判断するというふうにあるのですけれども、実態に応じて柔軟に、やはり継続ですとか、これを可能とすべきだと思うのですが、その辺についての考えをお伺いしたいと思います。","respondent":"矢部教育総合支援センター長","answer":"それとＷＩＳＣにつきましては必要ですので、間に合わない場合は申し訳ないのですが、保護者のほうでお医者さんへ行って取ってもらっていることも実際はありますし、体制のほうは、こちらもこれまでも整備していっているつもりですので。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後ちょっとごめんなさい、延長可否を判定する委員会というところでは、品川区ではどこで判定するとか、どのような仕組みになっているのか、もう当然つくっていると思いますけれども、そこについて最後にもう少し具体的にお聞かせいただいて、ぜひ柔軟に継続なども可能にしていただきたいというような要望も改めて申し上げまして、最後の質問とします。","respondent":"矢部教育総合支援センター長","answer":"メンバーは就学相談でもお世話になっている先生たちにもお世話になるということになりますけれども、基本的には校内でゆっくり検討していただいた後、教育センターで受けるということになります。","id":"exchange-021"},{"speaker":"田中委員","kind":"質問・要望","question":"区として、やはり障害を受け入れること、障害を理解する機会を奪うということにもつながりかねないということから、そういった国連の今の要請の状況なども考え、区としての今後の特別支援教育の在り方をどのように考えているのかちょっと伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"当該の児童・生徒にどのような支援がその学級でできるかどうかということを検討することになりますが、現在は、繰り返しになりますけれども、学習支援員や介助員で私どもは支援しておりますが、今後は国連の考えも受けて、国のほう、また東京都のほうで動きがあれば。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問","question":"それは本当にすてきなことで、子どもたちが障害を理解して、ちょっとまだその子のことが見られていなかった先生に対してそのような助言ができたということは、とてもいい事例だと思っているのですけれども、そのような機会も、特別支援教育に分けることになってしまうと、その子どもたちが障害のあるなしでわけられて、障害を持っていない子どもたちが障害を知ること。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"若林委員","kind":"質問","question":"ここで、国連のそのようなことが出てきて、今一定の質疑がありましたけれども、私は今の段階でここまでたどり着いたという特別支援教育の実態があって、それはメリットもあるし、デメリットもあるし、もっとこうしなければいけないということもあるけれども、でも国連の提言によれば、日本の今の特別支援教育の在り方というものは、逆行しているのだというふうな解釈でいくと、日本というか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"田中委員","kind":"意見","question":"言葉がまとまらずに申し訳ございませんでした。インクルーシブの考え方がそもそもちょっと日本は違うのではないかという指摘がされていて、今その当事者の方たちもパラレルレポートを提出しているところで、その返答待ちだったか、ごめんなさい、今その結論はまだ分からないのですけれども、インクルーシブ教育はやはり本来そうあるべきです。伝わったかな。ごめんなさい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"若林委員","kind":"質問","question":"長くなりそうなので、１回この議論は、すみません。お考えをお聞きしました。別に肯定とか、否定とか、そのようなつもりは全くございませんので。それで、ではこのまま私のほうから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"若林委員","kind":"確認","question":"いわゆる一対一という関係かなというように先ほどの質疑で理解したのですけれども、そこの確認と、医療的ケア児の方を学校で受け入れて、看護師を配置してというところの背景は、当然医療的ケアをしっかり支援するという専門家を置くということと、もう一つは、保護者が学校まで連れてくるとか、そういった保護者の負担をもう少し軽くするためにも、こういった方々の通学ですか。","respondent":"矢部教育総合支援センター長","answer":"保護者につきましては、今までは一緒についていてもらわなければいけなかったお子さんが、看護師がつくことで大分負担が軽減されたのではないかなと考えておりますが、実際には一緒に連れて、学校の中で看護師が対応しますので、外の通学については、学年にもよりますが。","id":"exchange-027"},{"speaker":"若林委員","kind":"質問・要望","question":"特別支援教室のほうの、特に今年度から導入されている発達障害教育支援員について、ちょっと確認をさせていただきたいと思います。","respondent":"矢部教育総合支援センター長","answer":"来年は来年で、そのお子さんではないかもしれませんけれども、いよいよ１年間で戻ってきた、教室にずっといる、発達障害等があると思われるようなお子さんの対応をするための支援です。","id":"exchange-028"},{"speaker":"若林委員","kind":"確認","question":"そうすると、もうどこかで質疑はしているのだろうけれども、この発達障害教育支援員と、学習支援員および介助員の役割としては、もう全く同じですという、今の理解でいいですよねという確認をまずさせてください。","respondent":"矢部教育総合支援センター長","answer":"ただし、ちょっと名称が違っていまして、学習支援員というのは、じっとはしていられるのだけれども、学習、読み書きですとか、そのようなところが弱いので横にいる場合もついていまして、介助員という名前の人は、通常の学級でどうしても安全管理をしなければいけない。","id":"exchange-029"},{"speaker":"若林委員","kind":"質問","question":"そのようなことですね。学習支援員と介助員の２つの役割を教育支援員が担っているということは、ちょっと中身に入りづらいけれども、今後は教育支援員の配置があれば、学習支援員と介助員は、もう配置は要らないねと。会計年度職員で、週４日だけれども、空いた日もちゃんとやりくりしてという考え方で進んでいくのでしょうか。","respondent":"矢部教育総合支援センター長","answer":"今、モデル実施で半年たちますので、今後の動向を見ながら、最終的には決めていきたいと考えています。","id":"exchange-030"},{"speaker":"渡部委員","kind":"質問・要望","question":"だから、国連があのようなことを言っても、おかしいな、何ということを言っているのだろうと思っているのは私だけではないのかもしれないのだけれども、私はそのように捉えているから、今は立派なことをやっているわけで、周りがどうしろと、逆に言えば国からでも、都からでも、今回の１年の話も去年あたりから出てきて、どうなるのだろうと思ったら、今年の４月から始まっているわけだから。","respondent":"矢部教育総合支援センター長","answer":"一方で、やはり教員の指導力向上、または時代も変わってきていますので、きちんと検証していかなければいけないなということを改めて思っています。","id":"exchange-031"},{"speaker":"松澤副委員長","kind":"意見","question":"いろいろお話を聞いた中で、要は特別支援という言葉が広がったのが、支援を必要とする児童・生徒が莫大に増えてきている背景の中で、品川区としてそのような莫大に増えた支援を必要とする人の裏に何があるというお考えなのか、ちょっとお聞かせください。","respondent":"矢部教育総合支援センター長","answer":"それくらい、やはり認識が広がっているなと思いますし、当然学校も地域も、ＰＴＡの方たちも認識が広がっているということで、増加しているというようには言えるのではないかなと考えています。","id":"exchange-032"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"すみません。確認していなかったので、お答えいただけるところをお答えいただきたいのですけれども、お願いします。多分区長のところにも声が届いていると思うのですけれども、今その状況をちょっとお知らせいただきたいということと、保護者の声をどう東京都に届けているのかというところをまずお知らせください。","respondent":"中谷指導課長","answer":"授業についてなのですけれども、品川区では、特に今回スピーキングということで、話すことというところだと思うのですが、これに対応した授業というものは、やはり小学校１年生からの積み上げの部分でも、そういった意味では。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問","question":"その申請のときの情報漏えいなどを考えたという趣旨だったのかなと思うのですけれども、そのモデル校があったということだったのですが、これは品川区にある学校ではなく、東京都が指定した、ほかの学校ということでよろしいですか。","respondent":"中谷指導課長","answer":"こちらについては、東京都のほうが都内の幾つかの学校に対して指名をしてという体制を取っておりまして、品川区内では、実績はない〔「１１月１日文教委員会にて「正しくは実績あり」と発言あり〕というところです。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問","question":"ＥＳＡＴ－Ｊに対応した授業について、区は小学校から英語教育をやっているので、それで対応ができるのではないかという趣旨の説明だったと思うのですけれども、ベネッセがやっているＧＴＥＣなどという学習のものは、品川区では取り入れていないということでいいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"若林委員","kind":"質問","question":"その他のところですが、私は予備知識もないし、中学３年生の子どもと、来年の４月のご心配ということでご質問されたと思うので、そこから先の、何か個別の企業の名前が出てきたりなどというところの質疑はうまく、委員長のほうでまた整理して選んでいただくよう、議事進行をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問・要望","question":"やはりそのテストのときに差が出てしまうということの不安感と、個人情報の流出、顔写真つきなのでとても怖いという声、この２つがすごく大きくいただいているご意見です。やはり生活者ネットとしても、いろいろ問題がある中でこれを進めるべきではないと思っていて、区教委としても、それは東京都のほうに伝えていただきたいということを強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問","question":"今のご説明は、資料にはないものですか。ごめんなさい、ちょっと聞き取れなくて。","respondent":"立木保育課長","answer":"本日特に資料等はご用意しておりません。内容的には前回、令和２年のご報告の内容と同じとなっています。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"すみません。この資料を見ても、厳しい意見が出ていると思います。それを開かない理由というのはなぜなのでしょうかということを１つお伺いしたいということと、それと保護者の方から、品川区宛てに陳情書、署名が提出されたと思うのですけれども、何人ぐらいから提出されたのかということと、その内容と、その内容に対する区の対応はどのようにしたのか、伺いたいと思います。","respondent":"立木保育課長","answer":"これに関しましては、私どもの基本的なスタンスといたしましては、区の方針を今のところ変更する予定はございませんので、そちらのほうを丁寧に説明するというような形になろうかと考えています。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問・要望","question":"行き先確保のため延期してほしいと。これは大変ささやかでもあるとも思います。そこは勘違いをしないでいただきたいですし、まずは関係者の方へという話もありましたが、今後、地域への住民説明会を開いていただきたいと思いますけれども、そのお考えはあるのか、改めて伺いたいと思います。そして、それはなぜ再来年度ではなくて来年度と早めるような決定をしたのか、そこについても伺いたいと思います。","respondent":"立木保育課長","answer":"地域の皆様へのご説明のことに関しましては、そういったご意見もあるということで、今後検討させていただきたいと考えています。それからパターンの件ですけれども、今区のほうで決定をしました方針としましては、令和５年度末ということで、令和６年３月ということになります。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"地域の説明会、ぜひやっていただきたいなと改めて要望したいと思います。２パターンあったにもかかわらず、１年早めてしまえというように決めた、そのような今の決定の内容ですけれども、そういったことを、この当該保護者の意見を聞かないで、なぜ決定したのですかと、それはしっかりお伺いしたいところです。きちんとこのような、今課長が説明したようなことを聞かないと、初めて分かるわけではないですか。","respondent":"立木保育課長","answer":"今ご質問いただきました内容では、ご意見の部分を聞かずにですけれども、区としましては、きちんと需要調査、前回の委員会でもご説明させていただきましたが、３,１０１人の方から需要調査の回答いただいております。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"今、できる部分についてはということですが、ちょっと前後しますけれども、保護者会の議事録や資料については配布できるということなのか。それと約３,０００の需要調査、なぜ当該当事者の話を聞かないでという話をしましたけれども、需要調査というものはあくまで区全体で捉えていかないとと言いますが、実際に通っている方たちの幼稚園がなくなるかどうかという話ではないですか。","respondent":"立木保育課長","answer":"検討会等の検討経過などの資料や議事録等については、検討をするということでお話をしています。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"決定について、最後に２つお伺いしたいのですが、これを実施するとですよ。これはいつなのでしょうか。入園募集を停止した後に、条例を変更して閉園ということになると思うのですが、それはなぜなのでしょうかということは１つ伺いたい。それと区長の決定、区の決定ですから区長決定なのです。この決定を変えるには、これは区長の判断で変わるのかというところというのは、どうなのでしょうか。","respondent":"立木保育課長","answer":"その閉園に向けての手続といいますか、方法といいますか、そういったところで入園停止ということを行っているところでございまして、在園児がいない状態でないと閉園という形にはならないというふうに認識しておりますので、条例改正、上程する段になりましたらば。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問","question":"ぜひ、繰り返しますが、これは決定を１回撤回してほしいのですけれども、今様々な手続を経て、庁内で区としての決定をすると思うのですが、区長が、やはりこれはひどいと。今度区長選挙もありますけれども、今の区長から誰かには替わるわけではないですか。区長が、この決定を変えますとなったら、それは区の方針というものは変わるのでしょうか。そこを再度しっかりとお答え願います。","respondent":"立木保育課長","answer":"これは品川区での決定ですので、その決定権を持っている者が決定したものに関しましては、組織としての決定ということになりますので、それはそのとおりだというように認識しております。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"今日の文教委員会のその他で報告となった理由を教えていただきたいと思います。机上配付が決定したのはいつなのか、そして説明会、保護者会と説明会、９月８日の保護者会でしたか、そのときに配られた当日の資料があったと思うのですけれども、それが配付されないのはなぜなのかという、まずこの２点教えてください。","respondent":"立木保育課長","answer":"当初報告等は、私どももこのような形でしっかり進めているところですので、そこの段につきましては、通常の行政運営の中でのお話という形だと思っておりまして、特に報告等の予定はなかったのですが、このような保護者の皆様からの意見も出ている中では、一定程度情報のほう。","id":"exchange-045"},{"speaker":"田中委員","kind":"質問","question":"今週ということは、では１２日の時点では、もうこのような形で報告をするということを決定していたということでいいですか。","respondent":"立木保育課長","answer":"１２日ということではなく、週の中ぐらい、おとといぐらいですか、ちょっとスタートのところがはっきりしないのですが、今週になりまして検討を始めているというところになりますので、火曜、水曜日ぐらいで、内部で少し検討を始めているところです。","id":"exchange-046"},{"speaker":"田中委員","kind":"質問","question":"ですから、１３日、１４日で、もしもこの伊藤幼稚園の報告をするというのであれば、そのときに報告しますと一文加えることは可能だったと思うのです。それがなぜできなかったのかということを伺いたいです。伊藤幼稚園の説明をするのであれば、そのときに配付された資料も一緒に添付されるべきだったと考えますが、そこのところを伺います。おかしくないですか、あまりにも。子どもたちも。","respondent":"立木保育課長","answer":"先ほどのご説明の期限のところなのですけれども、期限が短いから説明できないということではなく、期限が短い中でどうしたら早く伝えられるだろう、どうしたら考える時間を少しでも取っていただけるだろうかというところで、とにかく早く保護者の方。","id":"exchange-047"},{"speaker":"田中委員","kind":"質問・要望","question":"今のお話だと、地域の方たちはその関係がある人には入らなかったということでいいですね。そして、先ほど私立幼稚園を回った、職員はそういった汗をかいているというお話だったのですけれども、前回８月２２日のときにも伝えたのですが、区立幼稚園の意義というものがあると思うのです。一枚のものなので。それぐらい配付できたと思うのですけれども、そこの部分もお知らせいただきたいと思います。","respondent":"立木保育課長","answer":"これは私どもが誠意を持って対応させていただいているです。","id":"exchange-048"},{"speaker":"田中委員","kind":"質問・要望","question":"今回の伊藤幼稚園の閉園に関しては、需要調査を主にメインとして、そこから閉園を決定したということだったのですけれども、本当にそこに通っている、伊藤幼稚園がよくて選んでいる方たちの声を無視して、需要調査のほうで決定をしていくという、その決定の在り方も分からないですし、私立幼稚園に通っている保護者から話を伺ったときに、今このコロナの状況で。","respondent":"立木保育課長","answer":"最初に、二葉幼稚園は遠いのではないかというお話ですが、これは保護者会の中でもご意見いただいておりまして、回答といたしましては、自転車等使えるように、こちらのほうとしてもそういったご意見があるということを真摯に受け止めて。","id":"exchange-049"},{"speaker":"田中委員","kind":"質問","question":"でも、今はそこは区としてはもう見ていかないというご答弁と受け止めていいですか。そして、先ほど質問したのが、そこに伊藤幼稚園を選んで通っている保護者に、今後についてどうしていくという促しはなく、需要調査で閉園を決定した理由を聞きました。なぜその伊藤幼稚園利用者に聞かなかったのかというところをもう一度お知らせください。","respondent":"立木保育課長","answer":"繰り返しになりますが、やはり区の、これからのニーズの部分でありましたり、社会情勢等いろいろ判断した中で、今回区の大きな方針として決定をしていますので、個別のご要望やご事情に関しましては。","id":"exchange-050"},{"speaker":"田中委員","kind":"質問・要望","question":"説明会のときに配付された１枚の資料の中で、文言が正確ではないのですけれども、多様な保育機会の確保というような、とにかく多様という言葉が使われていて、それを受け取った伊藤幼稚園の保護者からは、この「多様」の中に伊藤幼稚園は含まれなかったのか、単独幼稚園のことを多様なうちにどうして区は含めてくれなかったのだろうという声などが届いていました。議会の場なのに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"渡部委員","kind":"質問・要望","question":"であれば時期をそろえて、もう来年一斉にというぐらいのほうが、私はご理解いただけるのではないかと思うのですけれども、何か前回私たちがそのような、自民党としての発言だったのですが、させていただいた後に、その辺何かお考えになられたのかどうかということも、逆にこういう機会だから聞いてみたいと思いますし、そのような政策転換だったら、やはりそれなりにしっかり言っていかないと。","respondent":"柏原子ども未来部長","answer":"ですから、そういった観点からいいますと、今、ご提案という形になるのでしょうか、いただいたお話の中で、伊藤幼稚園の部分の閉園のタイミングですか、こういったところも様々なご意見があるということは十分承知しているところでもありますし。","id":"exchange-052"},{"speaker":"渡部委員","kind":"質問・要望","question":"再度申し上げると、やはりある程度まとめてそのようなものはやってほしいなという思いは、いろいろ地域のバリエーションなどを様々考えたときにあると思いますので、当然決まり事は決まり事で動いてほしいのですけれども、やはり私たちとしては３園同時に、１年遅れてでもいいから３園同時にやってほしいなという思いがありますね、副委員長。一応そのような要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"若林委員","kind":"質問・要望","question":"いずれにしても、ずっと、８月２２日も含めたご説明をされている中で、区の、いわゆる今までの厳しい姿勢での判断という意味で、大きな３園廃園という大方針が出た。今日の議会の声を聴くという場であればということが１つです。うちの考え方として届けさせていただきたいと思いますので、どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"田中委員","kind":"質問・要望","question":"自民党の中では１０年間、そのような要望ですか、意見をしてきたのか、それとも区とやり取りをしてきたのかは分かりませんが、プロセスがあったということでした。ただ、生活者ネットワークは、情報公開した中で、あと前回の８月２２日の文教委員会でも、庁内会議がされたのが２０２１年で２回でしたか。その法的なところなどの兼ね合いも含めて教えてほしいのですけれども、すみません、無知で。","respondent":"柏原子ども未来部長","answer":"廃園というものをいきなりやって、さあ次から来られませんよという手続というよりは、最初に方針を出す中で、このような決定になりましたというところで、先ほどの園児がいなくなったという言い方が、もしかすると若干気になったのかもしれませんが。","id":"exchange-055"},{"speaker":"田中委員","kind":"質問・要望","question":"今のご説明があった、条例改正を突然やるのはよろしくないということだったのですけれども、法的にこの順序というのは間違いない、間違いないというか、法的な手続ではどうなのですかというところを知りたくて、その根拠法なども知りたくて、ごめんなさい、無知で。それを教えていただきたいということと、私が情報公開をしたと言ったではないですか。","respondent":"柏原子ども未来部長","answer":"毎年毎年募集の上、園児の方にいらしていただいていますので、そこを考えたときには、どこかで入園という手続を止めないと、いきなりそれで条例改正という話になると、あしたから、決まったらもう園に来られないのですかという話になりますので、方針を先に出して。","id":"exchange-056"},{"speaker":"田中委員","kind":"質問・要望","question":"その規則でどこか変わったところがあったなら、それをお知らせいただきたいということと、何を聞きたいかというと、条例改正がいつされるのかと。では次の３定では条例改正はないという話ですよね。質問しますけれども、その今の閉園に向けた手続が正しいのかどうかというか、どこに沿って、今この手続がされているのかということをお知らせください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"渡部委員","kind":"質問","question":"今の議論を聞いていますと、行政の手続だ何だというのは、そこは関係している話では全くなくて、要は、この閉園することに対するご報告をいただいた、だけれども、この報告いただいたことによって私たちがいろいろ質問できるような形ですから、少なくとも安藤委員にしても、若林委員にしても、私どもにしても、それに沿った質問をしていました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"田中委員","kind":"質問・要望","question":"その区の手続が要綱などではなくて、区として今回この伊藤幼稚園のためにつくられた方針だけ、区立幼稚園の閉園の方針だけということなのですか。いや、このスケジュール感がずっとこの後ももし続いてしまうようだったらすごい困るのです。それが、この方針だけで決定していくのであれば、今後は絶対変えていただきたいと思うのですが、いかがでしょうか。","respondent":"柏原子ども未来部長","answer":"区の重要決定事項に基づいて、区の決め、進め方によって方針を決めて、その方針を決めるというのは、区長であったり、部長であったり、決定権者がいて、それに基づいて方針を決定するというところです。","id":"exchange-059"},{"speaker":"安藤委員","kind":"質問","question":"すみません。質問なのですが、１点だけ。先ほどから私はなぜ当該保護者の意見を聞かずに決定したのかと伺ってきましたけれども、いろいろご答弁いただきましたが、要するに区としては、この全体の大きな方針の決定だから、今回の伊藤幼稚園の閉園に当たっては、当該保護者の、あるいは利用者の意見を聞かないで決めてもいいという考えなのでしょうか。そこだけちょっと伺いたいと思います。","respondent":"柏原子ども未来部長","answer":"そのような方針の中で、今回の件につきましては、まず時間的なところというのが大きく、それは我々も意識の中にありますので、何ができるかというところでまずいち早く説明であったりとか、お話をするであったりとか、そういったところもありますので、議会のほうに。","id":"exchange-060"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのは、やはり何というか、方針を決定するに当たって、当該の保護者、子どもの意見を聞かないで決定するということ、方針を決めるということはおかしいということを、私は先ほどから問題として指摘していると。そしてそれを改善してほしいということを述べて質疑をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"}]},{"id":"topic-05","title":"を改めて聴取いたします。審査順を入れ替えまして、(5)オアシスルームの運用変更","agenda":"を改めて聴取いたします。審査順を入れ替えまして、(5)オアシスルームの運用変更","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"とてもいいことだと思うのですが、ＳＮＳ、ＬＩＮＥとツイッターなどでも、ぜひ周知をですね。そういった層に届くように、ぜひやっていただきたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"田中委員","kind":"確認","question":"私もよかったなと思います。１つ確認したいのですけれども、これまでは各オアシスルームでその利用者の情報を保管していて、共有ができていなかったと。それをシステムで共有ができるようになったということなのかという確認をさせてください。","respondent":"中元保育支援課長","answer":"今委員ご指摘のとおり、それまでは各オアシスルームの中で情報を持っておりましたが、それをシステムのほうに反映を、入力をしまして、保護者の了解がいただければ、次のオアシスルームでもそれを見られるという形にシステム改修を今進めているところです。","id":"exchange-063"},{"speaker":"安藤委員","kind":"確認","question":"ひがしやつやまのほうなのですけれども、この暫定保育園の土地なのですが、品川区所有で、品川駅南地区再開発の品川浦周辺地区再開発協議会で検討している、まさに地区内にあるということで、昨年の文教委員会のこの保育園の１年延長の報告の際にこの兼ね合いについて聞いたのですが、課長の答弁ですけれども、「例年、毎年この開発のところの部門に対して。","respondent":"立木保育課長","answer":"今回は供給量の維持が可能であるという見込みから、延長については、特に開発のほうには問合せ等はしておりません。","id":"exchange-064"},{"speaker":"安藤委員","kind":"質問・要望","question":"そのようなことですか。定員を下回っていると言いますけれども、まだ半数以上は実際通っていますし、この公有地を活用した公立保育園を閉めるということは、私はやるべきではないなと思っておりまして、さらなる継続の判断こそすべきなのではないかと思いますけれども、それは求めたいと思いますが、区のご見解をお伺いします。","respondent":"立木保育課長","answer":"こちらの園は令和９年４月には閉園となりますけれども、その時点でも６５％程度の供給量は見込めるといった形ですので、このスケジュールで閉園をするということになったものです。","id":"exchange-065"},{"speaker":"田中委員","kind":"質問","question":"ひがしやつやま保育園です。そして運営期間終了の理由のところで、近隣園で必要な保育の供給量が維持できる見込みとあったのですけれども、この近隣園というものの距離感、どれくらいをもって近隣と言っているのかという部分を知りたいということと、今通っている子どもたちの保護者への説明というのはもうされているのかを伺いたいです。","respondent":"立木保育課長","answer":"この範囲の中には認可保育園が１０園ほどありますので、そちらのほうで維持できるというような判断をしているところで、あと在園児の保護者の皆様に関しましては、保護者会や掲示等で、今回の報告以後、周知予定になっております。","id":"exchange-066"},{"speaker":"田中委員","kind":"質問・要望","question":"しながわ区民公園内の保育園の状況についても、今回は延長ということなのですけれども、最終的にはまた閉園するかもしれない、可能性があるというときに、その説明が今の時点でされているのかという部分と、閉園にもうなるというときには、早い段階からそこに通う子どもと保護者に周知をしてほしいのですけれども、どういったスケジュールを持っているのかというところを伺いたいと思います。","respondent":"中元保育支援課長","answer":"区民公園内の保育園の件ですが、こちらのほう、今回もその先５年後を見越しまして、ゼロ歳の方が卒園できるまでというところを意識しまして、このタイミングでの判断をし、ご説明をしていますので、この先になりましても、また同じような時期に。","id":"exchange-067"},{"speaker":"田中委員","kind":"確認","question":"１点確認したいのですけれども、ひろまち保育園が閉園するときにも、入園のときに閉園の可能性があるということが示されずに、延長の可能性のほうが高いという説明を受けたからここを選んだという保護者の方の声がすごい多かったのです。今、ここのにじいろ保育園の入園のときには、そういった説明が前もってきちんとされているか、そこの確認だけさせてください。","respondent":"中元保育支援課長","answer":"そちらのほうきちんとした、５年後はこのようなことで閉める予定のほうがありますと。ただ、この近隣というものは割とお子様が多いのです。果たして５年後閉められるかどうか、ちょっと私どももまだ見通しが難しいところです。","id":"exchange-068"},{"speaker":"渡部委員","kind":"質問","question":"簡単に１点だけ、すみません。質問を忘れてしまうからしますけれども、今の公園法のは分かりました。では無限に延長というか、今のところはできる仕組みがあると。逆に今品川区というのは、期限が決まっている、このような公園につくった国家戦略特区制度を使ったものや、暫定活用のような園はほかにもあるのでしたか。","respondent":"中元保育支援課長、立木保育課長","answer":"昨年度延長しました西大井広場公園内のまなびの森保育園西大井が同じ理由です。荏原四中跡地のところに、ほうさん保育園という期間限定園があります。","id":"exchange-069"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/449994?Template=document&Id=5078#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":69864,"voices":194}},{"id":"r04-20220916-5","meetingId":"r04-cm09","date":"2022年9月16日","dateIso":"2022-09-16","committee":"総務委員会","time":"午後 １時００分～午後 ３時１１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","topics":[{"id":"topic-01","title":"先ほど申し上げましたとおり、取り上げる順番を変更し、初めに、(2)源氏前公園・源氏前特定児童遊園改修工事請負契約","agenda":"先ほど申し上げましたとおり、取り上げる順番を変更し、初めに、(2)源氏前公園・源氏前特定児童遊園改修工事請負契約","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"主な工事の工種というものが、４の工事内容のところに書かれているのですけれども、この１億５,２６８万円が、どこに幾らぐらいかかるのかということを、おおよそのところでいいのですけれども、教えていただけたらと思います。それから、キャッチボールができるところというのは、このような公園はすごく貴重な公園で、地元でも貴重な公園だと思っているのです。その点を教えていただきたいと思います。","respondent":"東野経理課長","answer":"キャッチボールができる公園ということで、ボールが飛び出さないかということですが、頭上といいますか、上のところについては網掛けをしていると聞いてあります。高さ的なところまでは、こちらで把握しているところではございません。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"老朽化が進んでいるということなのですけれども、老朽化というと、どのくらい経っているのかということ。それから、公園は、品川区内にたくさんあると思うのです。区として何かしらの予算があって、その中でやろうとしているのか、経費のかけ方はどのようになっているのか、教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"質問ではないですが、別に躯体工事があるわけではなくて１億５,０００万円を超えるということは、随分高いような感じがするのですが、やはり時代の流れ、物価の上昇、賃金の上昇なのかなという印象を受けます。この公園も、いざという災害に備えて、例えば、井戸水の給水装置などをつけていくという傾向はあるのでしょうか。そして、ここには、そのようなものはないということなのでしょうか。","respondent":"東野経理課長","answer":"災害に備えてですが、こちら（資料）の主な工種のところに書いてあります、マンホールトイレの工事を併せて行うと聞いております。こちらに記載はないのですが、現在のベンチを改修して、かまどベンチ、災害時に備えて、そういったものを設置すると伺っております。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"今のお答えですと、主な工種はここ（資料）に書かれている４つだけれども、そのほかにかまどベンチを設置するということもこの金額に含まれると理解してよろしいでしょうか。それを確認したいです。そうすると、インクルーシブ遊具工１基というのは、どれか１つという意味なのでしょうか。すみません、初歩的なことで申し訳ないのですけれども、それも教えていただければと思います。","respondent":"東野経理課長","answer":"私のほうで聞いている範囲としましては、車椅子利用の方が車椅子から遊具へ乗り降りしやすい高さをもったデッキや、小さな子どもも利用できるような低い滑り台といったものも備わった複合型遊具を１基設置するということで伺っております。","id":"exchange-004"}]},{"id":"topic-02","title":"豊葉の杜学園ほか２施設照明ＬＥＤ化工事請負契約","agenda":"豊葉の杜学園ほか２施設照明ＬＥＤ化工事請負契約","exchanges":[{"speaker":"西本委員","kind":"質問","question":"豊葉の杜学園は割りかし新しいと思ったのですけれども、そのとき既にＬＥＤ化されていなかったのだなと、今さらながら驚いてしまって、時期的なものだったのでしょうか。もう既にＬＥＤにしなければならないという決まりが法的にあったと思うのですけれども、これがどうしてずれたのかなと思うのです。","respondent":"小林施設整備課長","answer":"特にＬＥＤにつきましては、開発された当初、いわゆるちかちかするような状況の製品として、ある意味では、技術の進化がまだ進んでいる最中の商品だと認識しておりましたので、そのときの判断の中で、その当時は蛍光灯、あるいは白熱電球を採用したのではないかと推測されます。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"大分ＬＥＤの開発が進んでいなかったので、当然今のほうが性能もいいし、見え方も違います。いいと言えばいいのですけれども、少し全体的な話になってしまうのですが、まだまだＬＥＤ化を進めなければいけないというものはどのぐらいあるものなのですか。ざっとでいいのです。大体半分ぐらい終わっているとか、３分の１ぐらい終わっているとか、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"先だって、築４０年ぐらい経った工場だったのですが、そこが普通の蛍光灯からＬＥＤ化したのです。そのとき、ちょうど１か所当たり２灯、この委員会室のようについていまして、それが１か所当たり１万円しなかったのです。ですが、今回、照明器具が３,４６５台で、仮に１万円としても、３,４００万円ぐらいなのかなと。非常照明器具がありますけれども、誘導灯もそんな数ではないのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問","question":"先ほどの西本委員の質問の続きみたいな感じなのですけれども、結局、これだけＬＥＤ化を進めれば、豊葉の杜学園については、全てＬＥＤ化が済んだと理解してよろしいでしょうか。それを教えてください。","respondent":"小林施設整備課長","answer":"所管課からは、今回のＬＥＤ化工事をすることによりまして、全ての照明器具につきまして、ＬＥＤを完備すると聞いてあります。","id":"exchange-008"}]},{"id":"topic-03","title":"旧第一日野小学校跡地の暫定活用","agenda":"旧第一日野小学校跡地の暫定活用","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そのような方向であれば、荏原健康センターは仮設ということではなくて、きちんとした建物として建ててしまって、荏原保健センターには戻らないということになると、そこには仮設ではなくてきちんとした建物が建てられるというイメージなのでしょうか。何でこれだけ違うのかなと、これ（資料）を見たときに思っていたのですけれども、今後どうなるのかということがよく分からなかったので教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"全体の計画ということになるので、ここでもいいのかなと思うのです。旧第一日野小学校跡地をどのように活用していくかという全体像みたいなものは、いつ頃までに、どのような形で検討して、どのように明らかにされていくのかということも併せて伺いたいと思います。","respondent":"佐藤（憲）企画調整課長","answer":"その施設の中に、荏原健康センターを一部入れるという方向性を、今、検討しているというところで、すごく大きい荏原健康センターを建てるということではないのですが、ご案内のとおり、品川健康センターは３,０００平米以上の広さで、荏原健康センターは３００平米しかないので。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"この旧第一日野小学校跡地をどのような形で活用するかということは、本当に私たちもずっと提案し、そして、区民の大きな関心にもなっていますので、その検討過程のところから、ぜひ議会にもご報告いただいて、区民の要望も反映される形で検討していただきますように、お願いをしておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"資料の経緯というところで、「厚生・文教・行革の各委員会で」「仮移転について報告」なのです。これ（跡地）を何に使うかということは、どのような経緯で決まるものなのですか。どのような経緯があって、最終的に荏原健康センターを含んだ形という流れになっているのか。どのように検討されているのか、その決定経過がよく分からないので、教えてもらえますか。","respondent":"佐藤（憲）企画調整課長","answer":"２点目の荏原健康センターの件に関しましては、そういった検討の中で、実施設計を進めていったところで、先ほどの答弁と重なりますけれども、広さの面で荏原健康センターと品川健康センターを比較して、大分手狭で。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"有効活用ということで、品川区は狭いですから、仮施設というのは当然だと思うのです。それはいいとして、その検討をする中で、そのような用途にするとなってきたのかなと思うのですけれども、全体像が見えないなと思っているのです。品川健康センターと、広さだけを見たら、確かにこちらは狭いです。でも、そういう問題ではないと思うのです。それは、どのような話が進められていたのですか。","respondent":"佐藤（憲）企画調整課長","answer":"本格活用施設の全体像に関わるご質問だと思うのですけれども、先ほども答弁差し上げたとおり、それは今後検討していくところで、これまで区でも検討しているところと、世論調査等で、区民に望む施設を把握しているところですし、当然。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"だから、それだけの機能だけではなくて、いろいろな考え方が入れるし、区の考え方ももちろんいいのですが、もっといろいろな視点から考えられるような、審議会をつくったほうがいいのかどうか分かりませんけれども、区民の人たちの要望もさることながら、そこだけで考えているのは少しもったいないような気がします。意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"すみません。聞きそびれていたら申し訳ありません。それは、今後は、そちらでやっている複合施設でやっている荏原健康センターの機能、区民サービスはやめて、将来的にはこちらのほうに全部移ると考えていてよろしいでしょうか。それとも複合施設に少しは残るのだということなのでしょうか。すみません。あまりよく聞き取れなかったので、お願いします。","respondent":"佐藤（憲）企画調整課長","answer":"今回、実施設計を進めまして、荏原保健センターの機能を拡充するというところで、いろいろな構造壁なども設計しておりますので、荏原健康センターが現実的に戻るということは、可能性は非常に少ないというか、ないです。","id":"exchange-015"},{"speaker":"つる副委員長","kind":"確認","question":"すみません。１点だけ確認させてください。先ほど、鈴木ひろ子委員との質疑の中で、令和９年度から云々という答弁のくだりがあったかと思います。もう一度、同内容で結構なので、そこだけ教えてください。","respondent":"佐藤（憲）企画調整課長","answer":"その後、水色の部分の仮設が撤去されて、新しい建物を建て終わるのが、例えば令和１１年度だとすると、荏原健康センターは令和１１年度まで仮設で運営しますので、そのまま引っ越しして、令和１２年度以降。","id":"exchange-016"},{"speaker":"つる副委員長","kind":"確認","question":"すみません。先ほど、「令和９年度」という表現があったかと思うのです。もう一回、そこだけ。議事録には載ることだと思います。そこだけ確認させてください。","respondent":"佐藤（憲）企画調整課長","answer":"荏原保健センターが令和５年７月から令和８年度までは仮設で運営するので、令和９年度以降に着工するという意味です。","id":"exchange-017"},{"speaker":"つる副委員長","kind":"質問","question":"そうすると、今、北面にある荏原健康センターの仮設の部分と、中原保育園・児童センターの仮設の部分と、全体の跡地の活用についてということが出てくると、令和９年度からの着工予定となってくると、工事の関係で、既存の水色の部分だけ、ないしはもう少し狭くなるのかどうか分かりませんけれども、あとは、どのような施設が建つかによって、当然、駐車スペースや駐輪スペース、その他、空地的な形など。","respondent":"佐藤（憲）企画調整課長","answer":"ご質問いただき、ご指摘いただいたところは、今現在、そのような方向で考えているのですが、今後、検討を進めていく中で、より広い敷地を有効活用するという話になれば、ご指摘のとおり、黄色い部分は令和１０年度まで保育園で使いますので。","id":"exchange-018"},{"speaker":"つる副委員長","kind":"意見","question":"１年のラグという、先ほどの話ですけれども、そう遠くない先だと思うので、当然、不測の事態があれば延びる可能性もあるわけなので、あまりタイトに組んでもきつい部分があるかと思いますが、いろいろな行政ニーズの取捨選択の中での方向性ということはあるかと思いますので、その辺を含めて、先ほどもありましたけれども、極力可能な限りの早い段階の議会への説明等を引き続きお願いしたいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今の話を聞いていて、水色のところであれば令和９年度から、黄色のところまで含めたら、令和１１年からという形で着工するとなると、旧第一日野小学校跡地を活用する全体像の計画というのは、いつ頃までに示されることになるのか。おおよその計画ができて、それから、本当に具体的なところの細かい設計に入っていったりすると思うのです。そこのところだけ教えてください。","respondent":"佐藤（憲）企画調整課長","answer":"本格施設の内容については今後になるのですけれども、例えば、水色の部分を活用した場合、令和９年度から着工になりますので、逆算すると、実施設計と基本設計と基本計画で３年ぐらいかかるとなると、来年度以降に細かい検討が必要になってくると認識しております。","id":"exchange-020"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区が目指す職員像のところに、「品川区人材育成基本方針」というものが、平成３０年４月改定ということであるのです。これをホームページで調べようと思ったのですけれども、見つからなかったのです。これは公表されていないのでしょうか。公表されていないのであれば、なぜなのかも教えてください。職員が意見を言えるような場があるのか。この品川区人材育成基本方針について伺いたいと思います。","respondent":"崎村人事課長","answer":"品川区人材育成基本方針については、委員がお話しのとおり、特にホームページ等に公表しているものではなく、職員の内部向けの基本方針になっておりますので、確かに、他自治体では公表されているところもあるかと思いますが、今のところ。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これがどのような形で使われているのか。職員が意見を言える場があるのかということをお聞きしたので、そのことについても伺いたいのです。私たちは、この総務委員会で、先日、静岡市に人材育成の件で視察に行ってきたのです。そのようなところで、人材育成基本方針に対して、今後、他の自治体のように公表していくことは検討されていないのか。その考え方についてもお聞かせいただけたらと思います。","respondent":"崎村人事課長","answer":"区民に分かるように公表してはというところについても、公表することによって、区の取組、区の人材育成の考え方を示すことにもなりますし、また、採用に当たっても、区がどのような育成を考えているのかを示すことにもなるかと思いますので。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、静岡市のものを見せていただいたときに、静岡市は平成１７年度に初めてつくられて、平成２４年に新人材育成ビジョンというものがつくられて、平成２７年に改定されて、４年ごとに見直していくという形で、市民に寄り添える市の職員として育て、また、様々なところで、そのときそのときに合わせた形で、求められるものに対して。","respondent":"崎村人事課長","answer":"今後の人材育成基本方針の考え方、改定に関するご質問かなと思うのですけれども、確かに、平成３０年、約５年前に改定してから、その間でも、先ほども触れましたように、長期基本計画の策定や、今回の新型コロナの感染拡大という社会経済状況の変化や、定年年齢の引き上げで。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"まだ質問はあるのですけれども、多分、皆様もあると思いますので、取りあえず、一旦終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"今、民間企業も、ＡＩで面接をしたり、インターンシップ制度を拡充して、１週間ないし２週間、その人をずっと見て、働き方、対応などを見て、きちんとした人を採用している。２度、３度の面接でその人が分かればいいですけれども、１度面接しても、１人２０分、３０分、長くても１時間。その辺について、最初に教えてください。最初、その前段として、それについて少しご見解をお聞かせください。","respondent":"崎村人事課長","answer":"委員がおっしゃいますように、育成を考える上で、その前段となる採用は大切ではないかというご指摘は、先ほどもご説明がありましたけれども、人材育成基本方針の中でも、やはり採用は重要であるというところをしっかりと位置づけて取り組んできているところです。","id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"それは何が原因なのか、私は分からないのですが、結構そのような方たちが大手企業でも入ってきているということを思うと、やはり世の中が変わっているのですから、今、２３区は統一して人事採用をしているのですけれども、品川区は品川区で独自の採用基準をつくって、若い人に対する独自の手当などを出してあげて、ああ、ここなら僕たちも安心して働けるなとか、それから、会社に入っても。","respondent":"崎村人事課長","answer":"自分の技術もそうですけれども、区のことを教えるとか、仕事のことを教える、プライベートな相談にも乗れるようなＯＦＦ ＪＴの部分での受入研修、ＯＪＴ研修も実施しております。","id":"exchange-026"},{"speaker":"須貝委員","kind":"質問・要望","question":"いい上司がその部署、課、部にいれば、やはり部下の皆様も、新入社員も尊敬するし、また、温かい上司がいればやりがいも覚えるし、辞めないと思うのです。私は、まず、上に立つ人、管理する方がしっかりしていれば、きっといい職場ができて、いい人材もたくさん残ると思いますので、今後も様々な取組をして、いい人材確保に努めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問","question":"希望を考慮した人事を、どのように整合性を図っているのかなということを一つ伺いたいです。「ＯＪＴ支援研修」は「係長２年目」と書いてあるので、ＯＪＴをする立場の人への研修です。同じように、「人材育成研修（管理職）」というのは、多分、管理職向けの研修ということになると思うのですけれども、どのような立場の方が研修をしておられるのか、伺いたいと思います。この３点を伺います。","respondent":"崎村人事課長","answer":"１０月１日に、また育児休業制度が大きく変更になりますので、この機会に、これまでの育児休業制度の変更や取組、取得促進について、改めて通知を出す予定です。","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"最初に、これは難しい質問だなと思いながら聞いたのですけれども、やはり希望の職に就きたいという人と、一方で、これから区としてこのような事業を行うから、このような人員をこの人数で配置してほしいというのは、どうしてもどこかでぶつかるし、その中で整合性をつくっていかなければいけないのだと思うのですけれども、現状のことについては分かりました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"人を活かす人事制度ということで、区の職員、公務員という括りの中で、今までは仕事を選ばず、何でもできるようにという方向だったと思うのです。私は、経験者採用をもっと増やしてほしいという思いがあるのです。１割ぐらいなのかなという思いがあるのです。人材を新規採用するときも、方向性として、今後、区はどのような方向に行くのですかということが気になるのです。そこをお聞きしたいのです。","respondent":"崎村人事課長","answer":"他自治体でも、恐らくそういったスペシャリストの育成という部分で取組等々が行われておりますし、今後の職員の異動についての方向性を考える上での１つの検討項目かなと捉えているところです。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"やはりどんどん変わってきているのだろうなと思うのです。その仕組みと、管理職は、かなり管理職としての能力がないと、結局、若い方々が一生懸命やったとしても、上の頭が硬かったら、皆様がそうだとは言っていませんが、そのような状況だとうまく使えなかったりしてしまうので、そういう管理職の方々の研修というのは、どのようなものをされているのですか。","respondent":"崎村人事課長","answer":"管理職は、先ほどご説明しましたように役職定年制が始まりますので、そういったところで、管理職になってからも、能力向上や資質の向上を図るための研修メニューがあるということをしっかりと示しながら、不安の払拭に努めていきたいと思います。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"仕事の能力という以上に、人をどう使うか、人の気持ちがどれだけ分かるかというところが非常に大きくなってくると思うのです。よい職場環境は管理職にありというところがあるので、ぜひお願いしたいなと思います。２点あるのですけれども、精神的なサポートです。そのようなところをどうされるのかが心配なので、それが１点。報酬の件はどうなるのかだけ確認したいと思います。そこだけ確認したいと思います。","respondent":"崎村人事課長","answer":"窓口のクレームという部分では、特別区の研修でも、品川区の研修でも、「悪質クレーム対応研修」というものも実施しておりますので、そういったところで対応法を学びながら実践しています。","id":"exchange-032"},{"speaker":"湯澤委員","kind":"質問・要望","question":"私は静岡市に視察に行かせていただいたときに、説明をしてくださった方が女性職員で、たしか５０代ぐらいの女性だったと記憶しているのですけれども、同世代の女性は結婚・出産を機に退職されたり、そこでキャリアがストップしてしまったりしたということをお聞きしたのです。そこは、品川区としてはどういったお考えの下でやっていらっしゃるのかということをお聞きしたいと思います。","respondent":"崎村人事課長","answer":"現在も区の職員報の中で、女性管理監督職のお話などの特集を組んだりしながら、そういった昇任意欲の醸成や、無理なく働ける職場というものをお示しはしているのですけれども、今後、引き続き、現在の取組について。","id":"exchange-033"},{"speaker":"湯澤委員","kind":"意見","question":"今回、「区がめざす職員像」と書かれているのです。これもとても大事なことだと思うのですけれども、やはり区民のための行政サービスでありますので、区民が目指してほしい職員像というものもあるかと思うのです。そういったところが、この区がめざす職員像にどのように反映していくのかというところをお聞かせいただければと思います。","respondent":"崎村人事課長","answer":"区がめざす職員像という部分と、区民が求める職員像というところをどうマッチさせるかということなのですけれども、確かに今回の人材育成基本方針をつくるときに、そういった区民の声は聞いていないのですが。","id":"exchange-034"},{"speaker":"湯澤委員","kind":"質問・要望","question":"やはり区民に対して、人が人に対してというところがあると思いますので、ぜひ職員もやりがいを持ち、そして、笑顔で対応できるような環境、もちろん苦情やクレームなどもたくさんあるとは思うのですけれども、その中で、１日仕事をした中でやりがいが持てたなといったことが実感できるような区であってほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"会計年度任用職員のところなのですけれども、１,３６２名ということで、この会計年度任用職員の方がかなり増えていると思うのです。いろいろな働き方の方がいらっしゃると思うのですけれども、専門職の資格もあり、かなり重要なところも会計年度任用職員の方がお仕事をされているという部署もあると思うのです。どのように研修がされているのか、伺いたいと思います。","respondent":"崎村人事課長","answer":"会計年度任用職員につきましては、特に人材育成基本方針の中に研修等を位置づけているものではないのですけれども、研修メニューとしては、一般職の非常勤職員となりましたので、先ほど言った地方公務員法の適用があるといった部分では、地方自治法や地方公務員法。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほど、今年度の有給休暇取得は１０日が目標ということなのですけれども、現在、何日になっているのかということと、あと、時間外労働の管理はどのようになっているのかと思うのです。その辺の残業をどのように把握して、管理して、そのようなことをなくすために、人員の配置につなげたり、改善のための対策をとるなど、そのような仕組みはどうなっているのかについても伺いたいと思います。","respondent":"崎村人事課長","answer":"最初の会計年度任用職員の研修という部分で、少し誤解を与えたのは申し訳ないのですけれども、会計年度任用職員で、１会計年度ごとに雇用している関係ですので、何かしら体系的に研修を実施するというのは、なかなか難しいというのが現状です。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"目標はもっと高いところにあると思うのですけれども、目標が何日かも教えていただきたいと思います。その点も伺いたいと思います。児童相談所の体制というのは、子ども家庭支援センターの体制とも合わせて、児童虐待の問題などの対応がしっかりとできる体制がすごく求められていると思うのですけれども、なぜ任期付採用なのか、恒常的な採用ではないのかということを教えていただけたらと思います。","respondent":"崎村人事課長","answer":"年次有給休暇については、説明の中でお話ししましたように、全職員が１年間で１０日以上取得することを目標にして取り組んでいるところです。","id":"exchange-038"},{"speaker":"つる副委員長","kind":"質問","question":"人材育成の具体的方策の中の部分になろうかと思うのですが、もしかしたら先ほど来の質疑の中にあったかもしれません。人事評価の部分に関連して、区がめざす職員像のところに、「寄り添い傾聴」とあるのです。先ほど、幾つか感性の部分や、高い倫理観を持つというところで、この「寄り添い傾聴」というところについては、どのようなところで具体的に方策を図られているのか、まず教えてください。","respondent":"崎村人事課長","answer":"人事評価と傾聴ということが直接ダイレクトに結びつくというものではないかもしれないのですけれども、人事評価を行うに当たって、幾つかそういった評価項目を設ける中で、例えば、コミュニケーション力といった部分でこのような部分の評価をしている状況です。","id":"exchange-039"},{"speaker":"つる副委員長","kind":"質問・要望","question":"シンギュラリティなどがあると思うのですけれども、冒頭のＡＩやＩＣＴというところで、公務員というのは、本当にボタンを押したら結果、答えが出るというのは、来庁されたり、住民サービスなどを求めている区民の人たちが、まず、すごく大きい重点として置いている、求められる業務、結果というところがあるのだと思うのです。その辺りの人事評価について、あれば教えてください。","respondent":"崎村人事課長","answer":"ただ、まだ職員の中でそういった取組がなされていないという部分では、まだまだしっかりとこれを伝えていかなければいけない、人材育成の観点からも取り組んでいかなければいけないのかなと考えているところです。","id":"exchange-040"},{"speaker":"つる副委員長","kind":"質問・要望","question":"非常に重要なポイントなのかなと思いますので、そこはいろいろな形でぜひ推進いただきたい。もう一点、休憩中のあり方というところで、この辺の庁舎等の職員の、まさにあり方、めざす職員像というところで確認させていただきたいのです。これは、いろいろな形であるわけです。この後半のところについて、今、休憩中だということを何か明示することは、大きい部分でできないですか。できるのですか。","respondent":"崎村人事課長","answer":"窓口職場が多い区役所ですので、「職員が休憩中です」ということで、例えば、お客様が並んでいるのに、休憩中ですから出ないということはなかなかできませんので、何か明示をするというのは難しいのかなと思うのです。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982063?Template=document&Id=2244#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":39961,"voices":106}},{"id":"r04-20220920-14","meetingId":"r04-cm09","date":"2022年9月20日","dateIso":"2022-09-20","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 １時２２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を6件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私はこの日程を回覧板で回していただくというところまでされるものだと思っていたら、そうではなかったので、ぜひこれをしていただきたかったと思っているのですけれども、それがなぜされなかったのか、周知というところでは、これだけの参加にとどまったという点では、もっと周知の方法を工夫すべきではなかったかと思っているのですけれども、その点についても伺いたいと思います。","respondent":"山下新庁舎整備課長","answer":"こちらといたしましては、広報しながわをはじめ、ＳＮＳの発信でしたり、今ご紹介いただいた町会の回覧板に回せるような形でということで、各地域センターを通じて配布に努めたところですけれども、やはり皆様の目に触れるところに。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は回覧板にも、この日程そのものを区民の目に触れるところに回していただきたかったなというふうに思っているのです。それからもう一つお伺いしたいのが、これからのことですけれども、これから説明会というのはどういう場面でされることがあるのか、基本設計とか実施設計とかいろいろされていくことになると思うのですけれども、区民への説明という場面があるのか、その点についても伺いたいと思います。","respondent":"山下新庁舎整備課長","answer":"感染症でしたり、様々な事情等が出てくるとは思いますけれども、基本設計の段階であれ、実施設計の段階であれ、機会を捉えての説明というのは必要であろうというふうに考えてございまして、先ほど申し上げましたように、そういった説明の機会に際しましては。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"計画で、説明会の中でもちょっと質問が出されていたところで、自分自身もどうなっていくのだろうと疑問な点を１点だけお聞かせいただきたいのですけれども、新庁舎の中に保健センターの機能が新たに入っていくということで、２,０００平米が新たに追加される方向ですけれども、これはどういう形になっていくのか。","respondent":"山下新庁舎整備課長","answer":"区の保健センター管轄区域の再編成ということで、その一部機能の移転ということでお示ししておりまして、今ある品川保健センター、大井保健センター、荏原保健センターそれぞれについて、今後どういった形で対応していくかという検討はこれからというところではありますけれども。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうしますと、大井保健センターはそのままそこに残って、品川、大井、荏原の３つの保健センターの一部の機能が庁舎内に入るということで、大井保健センターはそのまま残るということで考えていいのでしょうか。","respondent":"山下新庁舎整備課長","answer":"現時点としましては、整理や統合といったような視点ではなくて、一部機能の移転ということでこちらとしては聞いてございまして、新庁舎整備課としてお答えできるところといたしましては、一部機能の移転というところになります。","id":"exchange-004"},{"speaker":"石田（ち）副委員長","kind":"提案","question":"説明会のときも出されていたのですけれども、現庁舎跡地になったときに、私たちとしては、超高層にせずに、現庁舎跡地も含めて中低層で、福祉施設の併設、こういう形がいいのではないかということも提案させていただいているのですが、現庁舎跡地については検討中ですということですけれども、これが検討されて、おおよそこういう形になっていくというのが出されるのは、基本設計とか実施設計とか。","respondent":"山下新庁舎整備課長、佐藤企画調整課長","answer":"今回はパブリックコメント実施に当たっての説明会ということで、パブリックコメントとしてお出しいただきたいというのが一番の趣旨ではあったのですけれども、当然その中でいろいろ質問したいこと。現庁舎跡地の活用につきましては、今後の検討課題だと考えております。","id":"exchange-005"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"意見のほうは、策定委員会のほうでもまとめて出されてくるということで、分かりました。現庁舎のところは検討中、その検討が検討ではなくなるときというのは、今も全く見通しはないということでいいのでしょうか。","respondent":"佐藤企画調整課長、若林委員長","answer":"今後検討を進める中で、また適宜議会のほうには報告していきたいと思います。ほかにご発言がなければ、以上で質疑を終了いたしますが、先ほどの新庁舎整備課長からの説明にもありましたとおり、１０月１７日月曜日に新庁舎整備基本構想・基本計画策定委員会の開催が予定されております。","id":"exchange-006"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/893508?Template=document&Id=6138#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":7169,"voices":21}},{"id":"r04-20220921-19","meetingId":"r04-cm09","date":"2022年9月21日","dateIso":"2022-09-21","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ３時０９分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"説明、本当にありがとうあります。この一番最後の４つ目の資源化率は、平成２３年で２６％だったところを、目標で３１％まで上げるといったのが、２６％のままであったというような感じなので、これはこれから分析ということなのですけれども、その目標が達成できなかった原因は何だと今の段階で考えていらっしゃるか、大雑把なところでもお伺いできればと思います。","respondent":"品川品川区清掃事務所長","answer":"ただその中で、どうもグラフの推移等を見ていても、やはりこのリサイクルの方法が少し固定化してきているなという雰囲気もあったりしますので、やはり何か新たなもののリサイクルというのも、これから考えていかなければいけないのかなと考えています。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"資源化率だけではなくて、ほかの３つのことについても、大雑把でも考えているところを伺いたいと思いますが、いかがでしょうか。","respondent":"品川品川区清掃事務所長","answer":"こういったところをどこまで区民の皆様に知っていただくかとか、そういうところがやはり今後の一つのポイントになるのではないかなと考えています。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"ご説明の中にもありましたけれども、啓発の工夫の余地というのは本当に大きなことだと、大きな要素の一つかなと私も思います。それからもう一つ質問として、この資料の中で、集合住宅の急速な増加に注目されています。この点で、何が問題だと考えていらっしゃるのか、どういう問題意識を持っていらっしゃるのかを伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"別紙１の右側下になります住居形態のところで、集合住宅が増えているという傾向ですけれども、いわゆる廃棄物の出し方としては、ざっと見ている傾向ですと、集合住宅はきちんとやっているところと、ちょっとなというところの差が大きいかなというところはあります。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問・要望","question":"なるほどと思いますけれども、私もそういう印象を持っております。区としてもこれだけたくさん増えてきているという意味では、管理組合に対しての啓発活動を強めるのも、かなり大きな手段になるのではないかと思いますので、啓発活動、それから協力を求めるというのを意識的に行うべきではないかということをご意見として述べさせていただきたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう一つはこの事業系ごみの発生抑制になるのですけれども、家庭ごみの発生抑制は区民の皆様に理解や協力を様々求めていくということは当然なのですけれども、事業系ごみというのは理解はしていても、商売上なかなか、では包装をどうしようかという、また段ボールだとか輸送をどうしようかと、理解だけではなかなか進まない分野だと私は思うのです。その考えを伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"現状としまして、現在何社かは区のほうに訪れて、こういうようなことをリサイクルでやりたいとか、こういうような製品を作って、作った段階でリサイクルしやすい素材を使ってやっていきたいだとか、そういったような説明をしに来る企業もいらっしゃったりしますので。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、区民から見るとどこの企業がどのような工夫をされているのか全然知られていないし、企業の努力が区民の評価にもつながっていないというのが私の実感なので、ぜひこういう自主的なリサイクルシステムを行っている事業者は率直にやはり区としても評価して、例えばＰＲするとか、またそういう仕組みをほかの事業者にも紹介していくとか、そういうふうに発展していくと。","respondent":"品川品川区清掃事務所長","answer":"これも、計画の中でどうしていくかというところは検討していきたいと考えています。それから、リサイクルの計画書ということなのですが、これは各事業所のほうに毎年廃棄物処理の計画を出してもらっております。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"今後、第四次品川区一般廃棄物処理基本計画が具体化されるということですので、そうした視点も明記というか、具体化していただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"田中委員","kind":"確認","question":"示されていないですか。この次の計画の中で示していくということでしたか。そこをまず確認したいのと、今年の４月から施行されて、ごみの収集のこととプラスチックのことに関心がある区民の方たちはきちんと分けていることは分かるのですけれども、そうでない方たちにまだまだ全然知られていなくて、やはりごみの収集場所を見たときに少し悲しいと思うようなことが多々あるのです。","respondent":"品川品川区清掃事務所長","answer":"２点目の周知なのですけれども、これはもう本当に非常に難しい問題で永遠の課題になるとは思うのですけれども、これもいろいろアンケートだとか分析データをこれから見て、どのようにやっていけばいいかというところは考えていきたいと思いますので、データを基にして。","id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"キャッシュバックをやるとか、何かそういった徹底した教育がなされているということに対して、そういったもの、ごみ処理というのは自治体で行うもので、なかなか日本の国全体がどうとかという問題ではないので、すごく難しいとは思うのですけれども、やはり自治体から特別そういった新しい手を打っていく必要があるのかなと思うのですけれども、どうでしょうか。","respondent":"品川品川区清掃事務所長","answer":"なかなか啓発方法というのは非常に難しいところがありまして、これもほかの自治体なども参考にしながらやっていったり、そういう方法をやりましていろいろと工夫をしていきたいと考えております。","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問","question":"そうですか。子どもたちに対してすばらしい取組ですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"たけうち委員","kind":"意見","question":"今後の課題としてもっとそういうものを増やしていくのか、その辺のところはどう考えていらっしゃいますか。","respondent":"品川品川区清掃事務所長","answer":"ですので、そういうところからすると、品川区としてはまだ真ん中ぐらいのところにいるのかなとは思っております。２３区の中でもリサイクルに力を入れている自治体等もありますので、そういった区なども非常に参考にしながら、今後もやっていきたいと考えております。","id":"exchange-011"},{"speaker":"たけうち委員","kind":"質問","question":"そうすると、それの成果をどのように見ているかということと、何かそれ以外に、今後こういったものをそういうふうにやっていこうというものが何かあるのであれば、どのような感じかということと、それからこの別紙のほうで、１人暮らしが随分増えてきているという中で、これはなかなか難しいかもしれないですけれども、何となくイメージとしてはご家庭だと、男女差別になってはいけないのだけれども。","respondent":"品川品川区清掃事務所長","answer":"ただ、先ほど委員のお話があったように、やはり時間がない方というのはリサイクルもなかなかやっている時間、洗えばすぐだろうというのもあるのですけれども、やはりそこの時間も惜しいという方もいらっしゃったりもすると思いますので。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"説明ありがとうございました。出す時間帯も含めてごみの出し方、あと仕分の仕方とか、ぜひそういう外国人向けに分かりやすいような、都営住宅にお住まいだから東京都がやるということではなくて、品川区民として、何かそういうところの外国人への対応をぜひご検討いただきたいと思うのですが、まずそこら辺をお伺いしたいと思います。","respondent":"品川品川区清掃事務所長","answer":"今後の対策としましては、最近は清掃のアプリを入れているような自治体も多くなっていまして、そういうところで外国語対応とかそのような機能も付いておりますので、そういうところなどもうまく導入していけるようになっていけばいいかなというような形で考えてはおります。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"そういうところに何か区としての支援といいますか、何かそういう仕組みもぜひつくっていただきたいということもあるのですけれども、何かそういうところでの取組支援、経営支援にもしかしたらなってしまうのかもしれませんが、今日は環境というところでのお話で、何かそういうものができないものかと思うのですが、どうでしょうか。","respondent":"河内環境課長","answer":"今後、脱プラと言いますか、廃プラといいますか、そういった動きが活発になってきて、それで一巡して、それが流行るという言い方はおかしいのですが、多く生産されればされるほどコストも下がってまいりますので、そういったところも視野に入れながら、細やかな啓発に努めて。","id":"exchange-014"},{"speaker":"新妻委員","kind":"意見","question":"ぜひお願いをしたいと思います。今後、もったいない推進店の、食品部門ですけれども、そういう資源に関するところでも、努力をしているところを、またぜひ啓発の意味も含めて推奨していただけるような、そういう取組もお願いをしたいと思いますので、ぜひご検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"つる委員","kind":"質問","question":"先ほど、松澤委員の質疑のところで、ごみ処理の最終地までの体験でしたか。ここのところをもう少し詳しく教えてください。","respondent":"品川品川区清掃事務所長","answer":"「ごみ・資源追っかけ隊」という事業なのですけれども、ごみ収集の部分から車等に乗っていただいて、ずっと流れを追いかけていただくというような事業になっておりまして、最後にそこで総括する形で、環境学習的なものをやっていくようなものになっています。","id":"exchange-016"},{"speaker":"つる委員","kind":"質問","question":"今言われて思い出しました。ごみ収集車にも一緒に乗っているのですか。すみません、このように細かいやり取りで。","respondent":"品川品川区清掃事務所長","answer":"ごみ収集車は、いろいろ危険な部分もあったりするので、基本的にはごみ収集車に乗せるということはしてございません。後を車で追いかけているというようなことをやっています。","id":"exchange-017"},{"speaker":"つる委員","kind":"提案","question":"分かりました。「しゅふ」と言っても２つの意味がある。２つだけではないですけれども、主に家庭のそうした一日の流れを担っている方、両方とかいろいろな家族で分担もあるでしょう。１週間。そういう部分の啓発とか教育のまさに効果的な施策に工夫が必要であるので、今後の具体的な、今検討段階にあるものがあれば、今の提案的なことを言わせていただいたことも含めて、何かご答弁いただければと思います。","respondent":"品川品川区清掃事務所長","answer":"先ほどもお話ししましたように、現在は割とアプリの時代ですので、そういったところで何かうまく啓発できないかなとか、いわゆるプッシュ通知というのは、すごく効果的だなという思いがありまして、Ｔｗｉｔｔｅｒ等でもあるのですけれども。","id":"exchange-018"},{"speaker":"つる委員","kind":"質問","question":"これはいろいろなことで毎回関連づけてあるのが、やはり品川区の広報広聴課との連携というのが、やはり品川区の各事業、各部と課がすごくいいことをやっていても、その発信とか周知がというのがいつもついて回ると言われていて、行政の広報の仕方というのは、世代だったりいろいろな方に対応する形で、どちらの意味でも平準化させられてしまって、あまり突飛な形の周知にはならなくて。","respondent":"品川品川区清掃事務所長","answer":"これもまたやるにあたって、広報広聴課との連携というところですけれども、基本的に広報広聴課も今はいろいろなメニューをそろえて周知をしていると考えています。ただ、いろいろな周知方法があって、それを同じように周知していくという技術は非常に難しいのかなと考えています。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"そもそもが、我々消費者が購入するにあたって、ジュースでもビールでも食料品でも、それぞれもうスーパーへ行けば決められた容器で我々は食したり、利用しているわけですから、根本的にはやはり生産者、製造業者が国とタイアップして、新しい容器なりを開発しなければ、なかなか解決はしにくいのかなとは、今お話を聞いていて思いました。それについて教えてください。","respondent":"品川品川区清掃事務所長","answer":"そういう中で、毎年国に対しての要望というのはその中でも上げております。当然そういう中で上げているものとしては、補助金を上げろとかそういうような話は毎年出しているというような動きはあります。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"様々な予算をいろいろなところに配分するのは分かるのですけれども、やはり大都会はもう本当に今後どうするのかという話になりますよね。環境課長にもお聞きしたいのですが、この廃棄物を何とか資源化する、何かエネルギーに転換するというような、要は循環型社会を構築するような動きというか研究というのはされているのですか。そうでないと、このままずっと残りますよね。その点について教えてください。","respondent":"河内環境課長","answer":"そのような方向性がまずは達成されてから、行き着くところまで行き、さらにまたそれがエネルギー転換できればというようなところでいいのかなというように、私の収集できる範囲では限られておりますが、日経新聞などを読んでおりましても。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"あれは理想的ですよね。我々が使ったものを、缶から卵の殻からもう全部入れて、それがエネルギー源になるというのは本当に理想だと思うのですけれども、そこまで一気に行くというのは無理だと思うのですが、当面大幅に減ることがない廃棄物を何かエネルギー等に転換していくように、区のほうでも国に要望していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-02","title":"はじめに、(1)令和４年度 ウォームビズキャンペーンの実施","agenda":"はじめに、(1)令和４年度 ウォームビズキャンペーンの実施","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"確かにもともとは、原発事故を経験して電力がひっ迫する中で、どう省エネルギー化を進めていくかという議論の流れだと思うのですけれども、きっかけはきっかけとしてあったにしても、いずれにしても省エネルギー化を進めていくということ自体はＣＯ２を減らしていくための大きな柱になるわけなので、この目的のところに電力需要の増大する云々というだけでなく。","respondent":"河内環境課長","answer":"その２２度から２０度まで我慢することによって、１日あたり８０ｇぐらいのＣＯ２が削減できるというふうなところで、たくさんの本にも出ている状況です。そういった認識の中で、しっかりと進めてまいりたいと考えていますので、よろしくお願いいたします。","id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"少し確認をさせていただきたいのですけれども、実施内容の（１）のところで「庁舎等」とあるのですけれども、この「等」が指しているのは、ほかの例えば子どもが過ごす施設とか、そういうところも含めての等なのかというところを確認させてください。","respondent":"河内環境課長","answer":"お子さんがいらっしゃるところも含めまして、温度について適宜調整するようにですが、一方で実用本位というのは変ですけれども、例えば保育園の０歳児室などというのは床面でお子さんがいらっしゃったりして、どこで温度をどう捉えるかというのは大事なところでありまして。","id":"exchange-024"},{"speaker":"田中委員","kind":"質問・要望","question":"０歳児の部分は本当にそのとおりだと思います。なので、子どもたちもこのウォームビズに無理なく参加ができるように、上着をかけるところを充実するとか、荷物を置くところを少し増やしてもらうとか、何かそういった工夫をしていただきたいと思うのですけれども、そこのところはどのように考えているか伺いたいと思います。","respondent":"河内環境課長","answer":"そういった畳むところだとか置くところにつきましては、例えばですけれども、そこにいらっしゃるまでに、冬であればダウンだとかいろいろなものを着ていらっしゃると思うのですが、そういったところを工夫していただきながら、ぜひ地球全体のことというか。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"子どもたちは本当に素直なので、もし置ける場所がここと言われたときに、そこに入らなかったと。ではもう駄目だと思って諦めてしまったりするので、ぜひ促してもらえるような、あと、子どもたちも我慢を強いられることなく過ごせるような環境の整備というものを、ぜひ促していただけたらいいなということを求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"須貝委員","kind":"意見","question":"私も実証実験として、扇風機を回して温度設定を２８度にしてずっと風を起こしながらやっていたら、結構効いたのですね。冬場なのですけれども、冬場は暖かい空気が天井にいきますよね。実際そういう実証実験としてやってみる価値はあると思うのですが、その辺についてどう思われますか。ご意見だけ聞かせてください。","respondent":"河内環境課長","answer":"省エネした分を、新たな電気料金でキャンセルされるとあまり意味がなくなってまいりますので、そういったところを捉えながらやっていくことが大事かなと考えているところです。","id":"exchange-027"}]},{"id":"topic-03","title":"粗大ごみリユース事業の開始","agenda":"粗大ごみリユース事業の開始","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"それと、日曜日に直接持ち込んだものだけが対象になっているのはなぜか。そこの確認もしたいのですが、このジモティーがやっていくのか。そのこともお知らせいただきたいと思います。せっかく商品が欲しいと思っても、ここまで行けないねという声が出てきてしまうことが残念かなと思うのですけれども、その受取りに関しての工夫が何かできないのかというところをお伺いをしたいと思います。","respondent":"品川品川区清掃事務所長","answer":"１つ目、開始と同時に商品があるのかというところで、こちらは先週、先々週ぐらいに粗大ごみで出されたもので、どれぐらいリサイクルできるかというのを試しにやってみまして、その試しの商品をストックしておりますので、開始のときからできるような形で考えております。","id":"exchange-028"},{"speaker":"新妻委員","kind":"質問・要望","question":"ありがとうございました。委託をするということなのですが、そうすると、この清掃や修理の費用はジモティーが持つという流れということでよろしいのですか。その１点だけ確認をします。この八潮の資源化センターに持ち込まれたもの、ここでのお渡しということなのですが、ここに関しても利用状況を見ながら、ぜひ前向きな検討を進めていただきたいと思います。","respondent":"品川品川区清掃事務所長","answer":"一定程度の本当に簡単な清掃、それから少しの作業で直るだろうというところぐらいはやるのですけれども、もうそれ以外は本当にそのままで出していくというような形を取っていきたいと考えております。","id":"exchange-029"},{"speaker":"小芝委員","kind":"意見","question":"私からは、周知方法といいますか、ジモティーのサイトか、もしくはアプリをダウンロードされて申込みをされるということなのですけれども、そこのところ、もちろんスマートフォンがもう普及していますので、基本持っていることを前提にされて進んでいることと思いますけれども、持っていない方の場合は、知り合いの持っている方に代理で、一応会員登録が必要ということなのですけれども。","respondent":"品川品川区清掃事務所長","answer":"それで、なかなかスマートフォン、それからパソコン等を使えない方がいらっしゃるのはもう私も認識しているところで、そういったところについては既存の「くるくる」という情報紙などもあって、そういう中でもリサイクルできたりとかいうところがありますので。","id":"exchange-030"},{"speaker":"小芝委員","kind":"質問","question":"例えば最寄りの地域センターでも何か代理で受けてくれるような、そういったフォローをしていただければとは思います。例えば考えようによってはそういった車、もちろん手配までするとそれは費用もかかってしまいますのでどうかと思いますけれども、その辺のパックのようなものを何かお考えいただければなとは思うのですけれども、そのあたりの考えを教えていただければと思います。","respondent":"品川品川区清掃事務所長","answer":"いろいろと手段というのはたくさんあるのかなとは思うのですけれども、とにかくシンプルにやっていきたいというのが、この事業の一つの課題としてなっているところもありますので、今後またやるにつれて、非常によい方法がないかというところはいろいろと探りながら。","id":"exchange-031"},{"speaker":"田中委員","kind":"確認","question":"このリユース事業をすごく楽しみにしていたのですけれども、私がイメージしていたのは、港区で行っている家具のリサイクル展みたいな形で実施されるのかなと思って楽しみにしていたのです。直してリボンに並べているといった議会でのやり取りがあって、そうなのだなと思っていたのですけれども、今はもうそれがやられていないということなのかというところも確認したいです。","respondent":"品川品川区清掃事務所長","answer":"今回我々のほうで考えているやり方というのは、非常に新しい方法でやることができないかというところで、ひとつインターネットを介してという形で、これだけでやってみようという試みでやっているものです。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"効率のよいリサイクルということだったのですけれども、それは区にとって効率がよかったということですか。今はまだ始めるばかりだから、インターネットでということだったと思うので、今後はぜひ展示というのも考えていただきたいというのと、さっきご答弁がなかったのですけれども、これまで直接持込み以外の粗大ごみの部分のところをもう一度ご答弁いただけたらと思います。","respondent":"品川品川区清掃事務所長","answer":"詳しく説明ができなくて申し訳なかったのですけれども、引渡しのときに見ていただいてちょっと違うなということであれば、基本的にはそのままお返しいただくということもできますので、引渡しの際に現物を見てご判断をする機会というのは設けているつもりです。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほど八潮のほうに行くのが大変とかそういう話があったと思うのですけれども、ごめんなさい、私は場所とかをよく把握できていないのですけれども、持込みになったら、やはり先ほどもご意見があったとおり、大きな荷物はなかなか運べなくなってしまうから、並ぶ商品も大きなものはもうないというのが大前提で進めていくということなのかということを確認をさせてください。","respondent":"品川品川区清掃事務所長","answer":"リボンのときには、かなり少量の大型粗大ごみをリサイクルしていたというところがあるのですけれども、今回の事業につきましては、大体年間で２,４００点ぐらいはやっていきたいと思いますので、リボンのときよりかなりの数をリサイクルしていきたいと思いますので。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問","question":"地理的なことの文句を言ったわけではなくて、ただ大きなものはもう扱わないというのがもう前提となっているということでいいのかというところを伺いたかったのです。","respondent":"品川品川区清掃事務所長","answer":"すみません。大きなものも扱うようになりますので、そこのところはよろしくお願いいたします。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ冒頭あったように、この場所は、少し間違えてしまうと湾岸線に入ってしまうというところで、いろいろ通るたびに、こちらですよという看板は大きくあるものの、初めて行かれる方はどうしても迷ってしまうという話、もう所長もよく聞く話だと思いますので、それは引き続き工夫はお願いしたいと思います。そこの仕組みをご説明いただきたいと思います。その仕組みをご説明いただきたいと思います。","respondent":"品川品川区清掃事務所長","answer":"「０円のものから」ということで今回出すようになりますけれども、値段は、区が設定していると、やはりこれは時間がかかってしまいますので、委託先のジモティーのほうで価格設定をしていきたいと考えております。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはりリユース品として気軽に提供できて、またリユース品を気軽に受け取ることができる、そういう仕組みをぜひ検討していただきたいと要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"新妻委員","kind":"確認","question":"今の質問の中で、有償で提供してというところがあったのですが、確認ですけれども、これは例えば区民の人が粗大ごみを捨てるときに、今区のシステムとしては、ごみ券を買って、有料でごみを出すという仕組みがあって、そういう意味でのそのごみ券の代金という受け止めですよね。それはそのごみを捨てたときにジモティーがこれが商品になるかどうか、というのは判断されるのか。確認をさせてください。","respondent":"品川品川区清掃事務所長","answer":"今回のものは、あくまで区民の皆様が粗大ごみだと判断したものの中から、リユースできるものはないかというところでやっていくものですので、この辺の仕切りははっきりと分けて考えているというものです。","id":"exchange-038"},{"speaker":"中塚委員","kind":"確認","question":"得意な方は、もちろんＴｗｉｔｔｅｒにも品川区のホームページのリンク先があって自分で調べることができるかもしれませんけれども、全員が全員できるわけではないので、そういう意味では、目黒川の水位が上がりましたの警報の後に、必要な情報を区民にプッシュ型で届けてあげるという取組も、ぜひ検討していただけたら思うのですけれども、やはり今回の台風が大きかっただけに。","respondent":"平原防災課長","answer":"接近中ですのでこういうようなことに気をつけてくださいとか、よく言われているような側溝といったものの確認をお願いしますというようなことを入れさせていただきましたが、今ご指摘にございました、例えば目黒川の水位の情報が機械的に流れた後。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"今回、やはり大きな台風で私も怖かったし、どうなるのかとどきどきしていたのですけれども、今回もう向かってくることは分かっていたので、そのときに自主避難施設の開設はどうだったのかという部分を確認させていただきたいのと、目黒川沿いに住む方が、サイレンが聞こえなくて、でも何か言っているなと思っていて、でも外を見るのも怖くてということでご相談があって。","respondent":"平原防災課長","answer":"もう一つは暴風圏内に入るかどうかといったところの風害の発生の可能性がかなり低下したということの判断をもちまして、ぎりぎりのところ、かなり前日近くまで検討はしていたのですけれども、開かないというような結論に至りました。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/170605?Template=document&Id=6624#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":40108,"voices":111}},{"id":"r04-20220922-10","meetingId":"r04-cm09","date":"2022年9月22日","dateIso":"2022-09-22","committee":"議会運営委員会","time":"午後 １時００分～午後 １時１２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/369281?Template=document&Id=5478#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":4164,"voices":17}},{"id":"r04-20221012-10","meetingId":"r04-cm10","date":"2022年10月12日","dateIso":"2022-10-12","committee":"議会運営委員会","time":"午後 １時００分～午後 １時３５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","topics":[{"id":"topic-01","title":"の４、東京都後期高齢者医療広域連合議会議員の補欠選挙における候補者の推薦","agenda":"の４、東京都後期高齢者医療広域連合議会議員の補欠選挙における候補者の推薦","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"東京都後期高齢者医療広域連合議会というところでの意見や態度というのも異なる部分もありますし、この間、高齢者の医療費を２倍にするという議案も全会一致で可決してしまいましたけれども、やはり今、下げてほしいという声も多く寄せられておりますので、そういった立場の声もぜひ届けていきたいということで、立候補させていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/369281?Template=document&Id=5480#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":11697,"voices":47}},{"id":"r04-20221026-10","meetingId":"r04-cm10","date":"2022年10月26日","dateIso":"2022-10-26","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時４１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","topics":[{"id":"topic-01","title":"日程の変更","agenda":"日程の変更","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"資料No.２４について、３点ほど伺いたいと思います。そうすると、４定の質問等にほかの議員の皆さんも活かせるのではないかと思うのですけれども、施政方針や所信表明とまではいかなくても、区政をどう進めていくのかの姿勢や考え方を早めに示していただきたいと要望したいと思いますが、いかがでしょうかということ。","respondent":"工藤区議会事務局長","answer":"こちらにつきましては、これまで経営会議ということだったわけですけれども、経営会議の中には執行機関のほうで、答弁調整に要する会議と、政策決定的な会議という２つの会議が存在しておりまして、それを明確に分けるために。","id":"exchange-001"},{"speaker":"石田委員","kind":"質問・要望","question":"分かりました。日程のところは様々考慮していただいたということで、年内で終わらせるとなると、すごく詰め詰めで、投票直後に通告期限になってくるのかなという思いもしていたので、とてもゆとりといいますか、余裕が出ているので、よかったと思っているのですが、それで、２点目の新区長の姿勢や考え方を示していただきたいというところは、ぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]},{"id":"topic-02","title":"議席の変更","agenda":"議席の変更","exchanges":[{"speaker":"若林副委員長","kind":"確認","question":"本件について、前回の委員会でご説明しましたが、同議会議員の補欠選挙候補者届出期間の関係上、第３回定例会２日目に候補者を推薦する議案を議決する必要があります。これまで議会運営委員会のメンバーを提出者とする議員提出議案で議長に提出しています。資料No.９の議案をご確認ください。本案について、質疑等があればお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"のだて委員","kind":"提案","question":"前回、共産党としては、石田ちひろ議員を提案したのですけれども、それはどうなっているのか、考え方を伺いたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"若林副委員長","kind":"質問","question":"それは、議案として出すとか出さないとかという意味ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"のだて委員","kind":"提案","question":"なるほど、そういうことになっているのですね。私たちは石田ちひろ議員を提案させていただいたので、今回こういう形で議案を提案されているのですけれども、こうした立場もありますので、今回の議案の提出者にはならないということにさせていただけたらと思います。というところで、議案にも反対という立場でいきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"若林副委員長","kind":"質問","question":"今ご意見がございました本案につきましては、資料の記載から共産党を除いたメンバーを提出者とする議員提出議案とすることで、よろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"若林副委員長","kind":"提案","question":"異議なしと認めます。さよう決定いたします。採決方法につきましては、起立採決ということでよろしくお願いいたします。なお、本議案の提案説明については、私が行うということでよろしいですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"}]},{"id":"topic-03","title":"品川区議会防災訓練","agenda":"品川区議会防災訓練","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"確認なのですが、今回、地震発生から３日後を想定しているということで、メールの安否確認もするということなのですが、今の訓練のやり方の中で、毎日安否確認をするようになっているのだということですが、実際の仕組みの関係と今回の訓練との整合性といいますか、そこを伺いたいと思います。","respondent":"工藤区議会事務局長","answer":"区議会災害対策本部訓練につきましても、これまでは初動対応ということでございましたけれども、震度５強以上になりますと、強制的に区議会の災害対策本部訓練は設置されているという状況になりますので、そういった中で、区の情報をもらいながら、今後。","id":"exchange-009"},{"speaker":"のだて委員","kind":"確認","question":"分かりました。防災訓練をやるときには安否確認をするようになっているということだと認識してよろしいのですか。","respondent":"工藤区議会事務局長","answer":"防災訓練の手法というのはいろいろとありますので、やり方はいろいろとあろうかと思いますけれども、今回に関しましては、安否確認を行ったという部分が４年前になりますので、改めてもう一度やらせていただきたいということで、防災訓練のメニューに入れたということです。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/369281?Template=document&Id=5482#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":22302,"voices":65}},{"id":"r04-20221028-4","meetingId":"r04-c-settlement","date":"2022年10月28日","dateIso":"2022-10-28","committee":"決算特別委員会","time":"午後 ３時０６分～午後 ３時１５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"若林副委員長","kind":"意見","question":"以上で、副委員長の互選は終了いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"若林副委員長","kind":"意見","question":"ご異議なしと認めます。よって、当委員会に理事会を設けることに決定いたしました。理事につきましては、私より指名することにご了承願います。理事４名には、大倉たかひろ委員、須貝行宏委員、吉田ゆみこ委員、松本ときひろ委員を指名いたします。理事の方々は、前のお席にお着きの上、就任のご挨拶をお願いいたします。","respondent":"大倉理事、須貝理事、吉田理事、松本理事","answer":"理事を仰せつかりましたイノベーションしながわの大倉です。円滑な運営のため、委員長を支えて頑張ってまいりたいと思います。よろしくお願いします。理事を仰せつかりました品川改革連合の須貝行宏です。副委員長、委員長を支えまして、円滑な審査ができるように協力してまいりたいと思います。品川・生活者ネットワークの吉田ゆみこです。品川区議会日本維新の会の松本ときひろです。しっかりと円滑に進められるように協力させていただきたいと思います。よろしくお願いします。","id":"exchange-002"},{"speaker":"若林副委員長","kind":"意見","question":"以上で、理事の指名を終了いたします。以上で、本日の予定は全て終了いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/816325?Template=document&Id=1514#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":2059,"voices":18}},{"id":"r04-20221031-6","meetingId":"r04-cm10","date":"2022年10月31日","dateIso":"2022-10-31","committee":"区民委員会","time":"午前１０時００分～午前１１時１１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","topics":[{"id":"topic-01","title":"第８１号議案、品川区立五反田産業文化施設条例および(2)第６９号議案、令和４年度品川区一般会計補正予算（歳出等 区民委員会所管分）を一括して議題に供します。","agenda":"第８１号議案、品川区立五反田産業文化施設条例および(2)第６９号議案、令和４年度品川区一般会計補正予算（歳出等 区民委員会所管分）を一括して議題に供します。","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"産業文化施設をつくることが、条例の第１条にあるにぎわいのあるまちづくりの創出に寄与するということに、なぜつながるのか、どのようにつながっていくのかということをお伺いしたいと思います。それからもう１点、使用料が全日で約６０万円と、非常にお高い感じが私にはするのですが、これはなぜ６０万円なのか、何を参考に決められたのか、その点をお伺いしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"ただ、昔の客席があってのホールというのは難しいけれども、今回私どもで借り受ける四角い部分、ああいう形であれば、つくることは可能だけれども、先ほど申しました一般の企業ですので、本来であれば、より採算のいいものをつくるという部分があろうかと思います。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"むしろ、今のお話を伺っていても、あるいは第１条第１項の目的のところを見ていても、企業が使用することを念頭に置かれている。それで人を呼び込んでこようと。それと同様の需要を見込んでいるとおっしゃるのですけれども、値段は１割ほど低く設定しているとおっしゃるのですが、現状で本当に需要はあるのでしょうか。そこが不安要因ではないかと思うのですが、その辺はどうなのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"興行になりますと、そこでイベントが開催されますので、近くの区民の方も多く集まってこられる、区民として参加することもできるという部分がありますし、先ほど言った需要という部分も、いろいろな使い方ができるということで、需要については。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"そう言われれば、素人判断としては、そうかもしれないとは思えるのですが、そういう需要はあるのだと判断された客観的な根拠、あるいは何か調査して、こういう数字が出たのだという根拠といったものが何かあるのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"今回、それよりも条件がかなりいいようなものをうちのほうでやっておりますので、そういう意味では、７割ではなく８割、９割という需要が見込まれるのではないかというのが、そこのところは今言ったとおり。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"そんなに急ぐ必要もなかったのではないか。その需要も、言ってみれば怪しい需要だと私は思うのですが、そういうものをわざわざ補正予算で急いで組むというのは、どうもその必要性、急いで補正予算として組む理由はないのではないかと私は思うのですけれども、本予算でじっくり組むべきではなかったのか、あるいは、これからの本予算で組むべきではないのかと思うのですが、その点、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"今回、補正予算で出させていただいたというところですけれども、当初は令和５年度予算で出させていただこうというのは考えていたところです。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"私としては、今、自治体がこういうことをすべきなのかなと思います。そういうところに力を入れていくべきではないかと、私としてはどうしても思います。こういう施設をつくって、そこに予算を投入するのではなくて、今言ったような支援に予算を投入していくべきではないかと私は思うのですけれども、その点、いかがお考えでしょうか。伺いたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"今回の施設ですけれども、企業にとって産業の集積場所、産業の販売促進などという形で、ああいうイベントホールみたいなものがあるというのは、大変重要なところでございまして、どうやって売っていくかというところがありますので、あそこを企業がご自由に活用いただきまして。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問","question":"企業に対する支援といいましても、念頭に置かれている支援、あるいは念頭に置かれている企業が、私とは少しずれていると思うのです。そこに着目して、そういう支援をきめ細かにやっていくべきときだと私は思っております。そういう意味で、まだ不十分だと考えていますので、その点、いかがでしょうか。もう一度伺っておきます。","respondent":"遠藤商業・ものづくり課長","answer":"いろいろな手段があろうかと思います。東京都、国などでも、いろいろな支援策があります。その辺、何が一番効果的かというのを判断しながら、今後も企業にとって一番役に立つ支援を進めていきたいと考えていますので、よろしくお願いいたします。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問・要望","question":"ぜひ企業の実態を見ながら、直接支援もきちんとやっていっていただきたいと考えています。よろしくお願いしたいと思います。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"松本委員","kind":"質問","question":"今、おくの委員から、産業振興の点でいろいろあったかと思いますが、産業振興といってもいろいろな観点があると思っています。その中で、少しお伺いしたいのは、大崎のほうにも大崎ブライトコアホールがあるかと思います。","respondent":"遠藤商業・ものづくり課長","answer":"そういう部分で使い勝手が、当然お値段は少し高くなってはしまうのですけれども、そういう部分で差別化はできるのかなと考えているところです。","id":"exchange-008"},{"speaker":"松本委員","kind":"質問","question":"そういう意味では、どちらかというと大崎のほうが会議的な利用とか、説明会という部分の利用で、こちらは興行とかイベントをメインにやっていくという話になってくるのかと思うのですが、参考図面を拝見すると、イベントホールのところは中央にステージがあって、あとは椅子を置いているイメージなのですけれども、これはあくまでも参考図面になって、例えば先ほどプロレスの名前が。","respondent":"遠藤商業・ものづくり課長","answer":"ですので、例えば今言ったプロレスとか、あとは展示会をやるような場合には、例えば平らな状態にして、いろいろな形で持込みという形になりますけれども、真ん中にリングを設置して、見ていただくという形になろうかと考えています。","id":"exchange-009"},{"speaker":"松本委員","kind":"質問","question":"例えばギャラリーのほうからエレベーターで１階から利用できるようになっているのかとか、その辺りはいかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"ギャラリーの動線の部分ですけれども、エントランスロビーとか、四角く、分かりやすいように書いてありますが、実際にはギャラリーのほうには、エントランスロビーを通る形にはなりますけれども、邪魔にならないという部分では考えさせていただいて。","id":"exchange-010"},{"speaker":"松本委員","kind":"質問・要望","question":"こちらは要望です。イベントに来てくれた人に、星野リゾートに泊まっていただいてという形での、お昼から夜まで楽しんでいただけるということも想定できるのかなと思うのですが、その辺りは、星野リゾートと同じ建物を借りていくというテナントになっていくと思うのですけれども、そこで、星野リゾートと話し合いをしながら、「このようなやり方もあるよね」みたいな話はなされているのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"当然、いろいろな使い方があろうかと思いますので、一緒に入る方と同じ建物の中で、こちらの建物自体を盛り上げるという部分がありますので、様々な形で連携できればとは思っているところです。","id":"exchange-011"},{"speaker":"松本委員","kind":"質問・要望","question":"最後、これはあくまで要望ですけれども、イベントホールはイベントホールであって、ホテルはホテルでありますという、別々にやっていくというと、もったいない部分とか、連携できたらよりよいみたいなところが生まれてくる可能性はありますので、できれば早い段階から連携していただきながら、こういう使い方もあるのだというところを探っていただければ、より活性化につながるかなと素人ながら思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問・要望","question":"五反田産業文化施設となっているから、私は文化観光課長からも何か説明があるのかと思ったのですけれども、全くないではないですか。減額がこれからあるというのですけれども、その辺について、担当の今日説明してくれている課長はどうですかということと、できたら文化観光課長も、文化と入っているから、何かご意見があったら教えていただきたいのですけれども、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長、篠田文化観光課長","answer":"きゅりあんのイベントホールという名称自体は、こういう建物になりますと、特に区に携わっていると、きゅりあんのイベントホールをイメージするかと思うのですけれども。施設としての管理の問題の部分もあるものですから、あちらのほうからどうぞという形ではないのですけれども、地元の方とのいろいろな流れの中で、金額的には先ほどご説明のあったとおり。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"地域からの声で、例えばきゅりあんのイベントホールがもう予約が入ってしまっていた。だから、きゅりあんとかスクエア荏原みたいな施設とは違うのですよということを思っておいたほうがいいのか、産業振興の施設でというふうに、感覚的には、この金額を背景、担保にするならば、使用料を思っておいたほうがいいのですかというのは、はっきり伺いたいのが１点。細かいことではなくて、ホールという意味では。","respondent":"遠藤商業・ものづくり課長","answer":"これは産業文化施設ですので、きゅりあんのイベントホールとかというところは、形としては一緒ですけれども、内容としては、使い方は少し違う部分、どうしてもお金がかかってきてしまいますので、きゅりあんのイベントホールが取れないから。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"最後に、この施設は品川区立五反田産業文化施設という名称で、ずっといくのでしょうか。いずれはＳＨＩＰとかきゅりあんのような名称になっていくのか、教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"ですので、そういう部分がありますので、なかなか公募というのは難しいかと思うのですけれども、先ほど言った五反田は、今回はご要望を聞いたところがありますので、そういうところとお話ししながら、より区民の方に、広く公募というわけにはいきませんけれども。","id":"exchange-015"},{"speaker":"本多委員","kind":"質問・要望","question":"本当を言うと、当時１,０００人規模以上の施設があればいいのではないかという話も理事者側に求めてきましたけれども、構造的なもので、規模としては４００名程度だというやり取りをさせていただいて、本当に納得をしてきたところなのですけれども、これまで日本郵政と品川区が交渉してきたご苦労といいますか、交渉の取組等の概要をお聞かせいただきたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"実際にその交渉の部分に、私どもも建設委員会の部分でご説明を聞いているところですので、詳細については分からない部分がありますが、一応そのような形で聞いているところです。","id":"exchange-016"},{"speaker":"本多委員","kind":"質問","question":"交渉してきた部署が違ったので、なかなか質問が、すみませんでした。すみません。以前のゆうぽうとのホールはかなり大きい規模でしたので、できたときは４５年ぐらい前ですか、当時はアジア一の音響設備だと言われて、そのぐらいのホールで、品川区も区民芸術祭等で使われたりして、まちの人たちも我々会派としても、期待感がすごくあるのです。そこだけ意見を聞かせてください。","respondent":"遠藤商業・ものづくり課長","answer":"この後、指定管理の提案という形になりますので、実際どういうものが上がってくるか分からないところですけれども、そのような部分を含めて、地域の区民の方に見に来ていただいて、終わった後には近隣のところに寄っていただいてという形にできればと考えているところです。","id":"exchange-017"},{"speaker":"本多委員","kind":"質問","question":"最後に一つ聞きます。「コンサート（軽音楽）」と書いてあるのですけれども、この辺の内容、例えば太鼓がどこまで使えるのかとか、小さい太鼓は大丈夫だけれども大太鼓は無理だとか、あと、補正予算で内装工事が入っていますけれども、防音とかの絡みとか、その辺だけ最後に教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"こちらの建物なのですけれども、あそこのホールでは、１１０デシベルまでホールの中では耐えられるという形になっています。","id":"exchange-018"},{"speaker":"塚本委員","kind":"質問・要望","question":"説明を聞き漏らしたところがあるかもしれませんけれども、確認を幾つかさせていただきたいと思います。そういう賃料とか経費的なことが発生するのかどうか、教えていただければと思います。","respondent":"遠藤商業・ものづくり課長","answer":"金額といたしましては、まだ本契約にはなっていないので、来年度の予算という形になるかと思いますけれども、税込みで今のところ、年間で１億４,５２０万円程度となっているところです。","id":"exchange-019"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、指定管理者にこれからお願いして運営していくということで、指定管理者が運営の中で、イベントをやられる方に貸すほうの賃貸の賃料というのが、ここに書いてある６０万円という金額。指定管理料みたいなものは、契約としては、区は負担しなくてもできるということを視野に、契約というか、指定管理というのを考えているのかというのを教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"９０％を超えるようになりますと、ちょうどとんとんぐらいになるのではないかと考えているところですので、当然私どもといたしましては、できるだけとんとんに近いような形を目指したいと思っているところです。","id":"exchange-020"},{"speaker":"塚本委員","kind":"質問","question":"日本郵政不動産に払う賃料も含めた形で、とんとんもあり得るということなのですか。そういうことではないと。９０％というのは、指定管理者の指定管理料みたいな、指定管理に関わる経費がとんとんになるようにと。","respondent":"遠藤商業・ものづくり課長","answer":"それが大体、考えとしては９０％を超えるぐらいになれば、かなりゼロに近いような形になるのかなと。すみません、言葉の整理が、申し訳ございません。賃料の部分です。賃料の部分は、固定で決まっているところです。それから、指定管理の利用料収入。","id":"exchange-021"},{"speaker":"塚本委員","kind":"意見","question":"先ほどから需要について、どれぐらい使われるのかというところがポイントで、９０％を目指せば上出来というところだと思うのですけれども、質疑の中でありましたが、星野リゾートですとか、あと、かなりの部分がオフィスとして、建物そのものを使われるということで、どういう企業が誘致されるかというところもありますけれども、かなり洗練されたというか、今までの五反田の雑踏のような。","respondent":"遠藤商業・ものづくり課長","answer":"区民といったときに、私どもは、ある団体が使ったりとか、あとは区内企業も当然、区民という扱いで考えておりますので、一定程度の割引が適用されるものと思っているところです。","id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、これもうれしい悲鳴の一つになるかもしれませんけれども、非常に人気が出てしまって、なかなか使えない、取れないとなっていったときに、区民の割引の方とか、あるいは優先的に区が、ここは区の利用のために枠を確保するとか、使えない場合に、普通に予約をみんなで取ってしまうという事態を想定した、区民に優先枠みたいなものを予約の中に設けるような考え方というのはいかがですか。","respondent":"遠藤商業・ものづくり課長","answer":"１年前から、今のところ、予定では受付ができますというところもあろうかと思いますけれども、指定管理の中で、区民の方につきましては、それよりも１か月早くという部分の設定はできるかなと考えていますので、そこは協議しながら。","id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問","question":"最初は賛成するかと思ったのですけれども、賛成というか、何を答えればいいのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"松本委員","kind":"意見","question":"賛成なのですけれども、今の中小零細企業というところで、お話がおくの委員からありましたが、私は、中小零細企業といっても種類があると思っています。それで五反田のエリアが、五反田バレーがより発展していくという可能性はあると考えていますので、品川区の産業支援の政策として、賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/277018?Template=document&Id=2942#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":23809,"voices":71}},{"id":"r04-20221031-7","meetingId":"r04-cm10","date":"2022年10月31日","dateIso":"2022-10-31","committee":"厚生委員会","time":"午前１０時００分～午前１１時３８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","topics":[{"id":"topic-01","title":"第８３号議案、品川区立知的障害者グループホーム条例の一部を改正する条例","agenda":"第８３号議案、品川区立知的障害者グループホーム条例の一部を改正する条例","exchanges":[{"speaker":"石田委員","kind":"質問","question":"このグループホームは、今ご説明があったとおりだと思いますけれども、一部屋一部屋の平米数は今の段階で分かるのか、分かれば伺いたいのと、防災広場整備計画地というのは、ふだんは使える形になるのかを伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"部屋の平米数については、今後運営事業者とも協議してまいりますので、今、詳細は分かりかねます。防災広場については、ふだんは公園として開放しておりますので、地域の方が足を延ばすことは、もちろん可能となっております。","id":"exchange-001"},{"speaker":"石田委員","kind":"確認","question":"たしか説明会のときに、地域との交流を大事にしてほしいというご意見もあったかと思うのですが、こうした公園等を利用した地域交流や、このグループホームの中に多目的室というのができるのではないかと思うのですけれども、そこの確認と、そういうところでの地域との交流というのをどのように考えられているのかということと、指定管理になっていくのでしょうか。","respondent":"川崎障害者施策推進課長","answer":"こちらは指定管理となります。今後のスケジュールとしては、指定管理者の公募というのは、１２月以降ということで予定しております。","id":"exchange-002"},{"speaker":"石田委員","kind":"質問・要望","question":"分かりました。なので、理解を広げるという点でも、多目的室や隣の公園等を使って、催物とか、地域交流ができるようにしてほしいという要望も出ていましたので、ぜひお願いしたいと思います。それと、指定管理にしていくということで、そうすると、指定管理者の決定というのは来年の第１回定例会とかにかかってくると見ていていいのか、その辺の確認だけお願いします。","respondent":"川崎障害者施策推進課長","answer":"日程については、今後の流れになりますので、また決まり次第、ご報告します。","id":"exchange-003"},{"speaker":"石田委員","kind":"質問・要望","question":"施設入所者数とグループホーム利用者の区外利用、区外を利用されている方が３５６人もいるという数字も明らかになりましたので、区内で、家族の近くでグループホーム、地域生活ができるように、さらなる増設に向けて、また計画もぜひ立てていただきたいと改めて要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"あくつ副委員長","kind":"確認","question":"２点ほど確認をさせてください。新旧対照表を見ると、グループホーム条例の文言が、「入居」から全て「利用」に変更になるということ。これは、短期入所があるから入居ではないというところで、「利用」と変えたということでいいのか、それで全ての文言を変えたということなのかというのが一つ。","respondent":"川崎障害者施策推進課長","answer":"知的障害の方はご存じのとおり増えております。品川区も平成２９年から、この５年間で１１％増ということで、知的障害の方のグループホームの整備を進めていく必要があります。","id":"exchange-005"},{"speaker":"あくつ副委員長","kind":"質問","question":"前半部分のご説明は分かったのですけれども、身体障害の方は、基本的にどなたでも、利用とすると、どのような身体障害があるとしても短期入所ができるということでよろしいのでしょうか。","respondent":"川崎障害者施策推進課長","answer":"身体障害者の方につきましては、こちらも今後、運営事業者と協議ということになってまいりますので、実際入居している、例えば知的障害者の方との相性とか、そういった面もありますので、もろもろの面をクリアした部分で決まるという方向になってくるかと思います。","id":"exchange-006"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"これから結果が決まるということでしたので、ショートステイに関しては様々なご意見を、もう何年も各種いろいろな団体からいただいておりますので、そういう団体のお声をしっかり聴いていただいて、本来の目的に支障がない場合ということでは、もうなっていますけれども、そういうところの利用に支障がない形での、またそういう皆様のニーズを受け入れた形での利用にしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-02","title":"第８４号議案、品川区立高齢者多世代交流支援施設条例の一部を改正する条例","agenda":"第８４号議案、品川区立高齢者多世代交流支援施設条例の一部を改正する条例","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"それがなかなか話が折り合わなかったというのも聞いてきてはいたのですが、そうした意見がどのように取り入れられてきたのか、それから、それ以降、地域の町会や高齢者クラブとの意見交換といいますか、どういう施設にしていくかというところでの懇談や交流みたいなものは区とやられたのか、伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"工事業者が替わる関係で、本件で総務委員会で契約議案を諮るところではありますので、それが終わり次第、区民への説明会も年内には予定しています。","id":"exchange-008"},{"speaker":"石田委員","kind":"質問・要望","question":"なので、そこはぜひ今後も丁寧にやっていただきたいと思います。なので、なし崩し的な感じで建設が進んでいくというのではなくて、これからも引き続き、今も説明会はしますということでしたけれども、地域と丁寧な懇談や交流を進めながら、できてよかったと言ってもらえる施設にしていかなければいけないだろうと思いますので、その辺の考えをお聞かせください。","respondent":"川原高齢者地域支援課長","answer":"地域交流スペースというのを１階に設けて、利用しやすい部屋として幅広くいろいろな区民に使っていただきたいと考えていますので、引き続き区民の方のご意見は聞き取りながら、よい施設としていきたいと思ってあります。","id":"exchange-009"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"私の地元なので、基本的に説明会は全部出させていただいたかと思います。先ほどのやり取りの中で、あれと思ったところがあるのですけれども、かなり丁寧にやられていました。畳の部屋が前はあったのですけれども、今回は畳の部屋がないということなのですか、教えてください。","respondent":"川原高齢者地域支援課長","answer":"ここにカラオケの機器を設置いたしまして、カラオケができるようにする予定です。和室は委員おっしゃるとおり、今回は設置をしてございません。","id":"exchange-010"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"先ほども申し上げましたが、かなり丁寧に地元の方のご要望、各高齢者クラブの聞き取りもされていますし、地域住民の方の聞き取りもされていらっしゃると思いますので、全部が全部というわけにはいかないと思うのですけれども、なるべく今度は多世代ということで、最初は自分たちの居場所が奪われるのではないかということで抵抗もあったのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-03","title":"令和４年陳情第５５号、障害者を「タックスイーター」と呼び切り捨てることのないよう、共生社会の実現を求める陳情","agenda":"令和４年陳情第５５号、障害者を「タックスイーター」と呼び切り捨てることのないよう、共生社会の実現を求める陳情","exchanges":[{"speaker":"石田委員","kind":"質問","question":"今のご説明のところだと、差別解消法等々が出されて、障害者を差別しない、そして差別的な発言があったり、言動というところを、区としては認めない、そういったことをさせない取組を進めていくということでいいのか、伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"共生社会の実現について、品川区では各部署に事業ごとの内容に応じて、合理的配慮を行うよう取り組んでいますし、職員一人一人も自分の仕事を振り返って、障害のある方に対する意識、取組について確認する意識調査を実施しておりまして、全庁で努めております。","id":"exchange-012"},{"speaker":"石田委員","kind":"質問・要望","question":"分かりました。合理的配慮、社会的な障壁をなくし、障害があっても社会的障壁を感じることなく生きられるようにというものですけれども、それらがなかなか進んでいないということで、私たちも今回の一般質問でも充実を求めて質問してきています。","respondent":"川崎障害者施策推進課長","answer":"こちらは都議会で出た発言なので、どのような背景でこういった言葉が出てきたのかというのは、私どもには分かりかねます。陳情でもご説明させていただいたように、品川区としては全庁で、障害のある方への取組、意識調査というものを行っており、職員一人一人が努めております。","id":"exchange-013"}]},{"id":"topic-04","title":"令和４年陳情第４９号、介護施設のコロナ対策に関する陳情","agenda":"令和４年陳情第４９号、介護施設のコロナ対策に関する陳情","exchanges":[{"speaker":"石田委員","kind":"質問","question":"今の説明の中でも、コミュニケーションを取ってもらうことが重要であるとのことですが、区として施設に対して、コロナで大変な中だけれども、そういう対策といいますか、コミュニケーションを取っていく、そうしたところを指導するということはできるものなのでしょうかというのを伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"レクリエーションにおいては、付加価値といいますか、施設の中で交流を深める上でのサービスでありますので、やはり感染症の対策等を講じながらの実施ということになりますので、区としてレクリエーションをやってほしいとか。","id":"exchange-014"},{"speaker":"石田委員","kind":"確認","question":"特定施設ですので、介護保険財政も入っているわけですから、区としてこういうところに点検に入るということはできるのか。それで、おっしゃっている有料老人ホームがスタッフ不足で、言い方は極端な表現もありますけれども、表に出られない状況、そして、ケアにもなかなか入れない状況が、ここの施設にあったと確認し、点検し、それを改善させるというのは、区としてはできないものなのでしょうか。","respondent":"菅野高齢者福祉課長","answer":"各事業所における利用者の生活実態、サービスの提供状況、介護報酬の適合状況等を直接確認しながら、事業者の気づきを促すなど、よいケアの実現および保険給付の適正化を図るために有効であるということで実施しております。","id":"exchange-015"},{"speaker":"石田委員","kind":"質問","question":"６年に一度なのですね。コロナという特殊なというか、大変な感染症が広がっている状況の中でのこういう施設というのは、感染症を広げないために、クラスターを出さないためにというところで、職員の皆さんは懸命に頑張られているところだと思いますので、こういう大変なときには、点検の回数を区独自に増やすという対策というのは、区で取れたり、やろうと思えばできるということでいいのでしょうか。","respondent":"菅野高齢者福祉課長","answer":"今回のような新型コロナウイルス感染症の発生とか、そういうことになった場合には、施設から保健所および高齢者福祉課に報告が上がってきまして、状況によっては、都の即応支援チームがその施設に出向いてゾーニングするなど指示を行って。","id":"exchange-016"},{"speaker":"渡辺委員","kind":"確認","question":"先ほどのご説明の確認が１点です。その確認が１点。この施設とかではなくて、介護施設全般の傾向の中に、感染症を重視してほしいという声、あるいは、その逆というわけではないのですが、一方で、こういう認知症対策を大事にしてくれと。それぞれどちらも間違ってはいないご意向だと思うのですが、どうしても賛否ある現実があるのだということの傾向があるのか、それを教えてください。","respondent":"菅野高齢者福祉課長","answer":"どちらかというと、まだそちらのほうが少し多いのかなと、区としても認識しておりますので、今後、インフルエンザとの同時流行とか、そういうことも懸念されておりますし、施設ではオミクロン型対応のコロナワクチンの接種もそろそろ始められるというところになっておりますので。","id":"exchange-017"},{"speaker":"あくつ副委員長","kind":"意見","question":"そういう中で、今、緩めるということが、緩めるというか、この方がおっしゃることを認めるということ自体が、高齢者にとってはかなりの危険があるので、ご家族にとっても、そこが先ほどのお話のとおり、いろいろな意見がある中で、やはり願意に沿い難いというところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"石田委員","kind":"質問","question":"結論を出すで、趣旨採択でお願いします。そういうところで趣旨採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出すで、不採択です。それで、要望として、区の施設でも、今までお話しいただいたように、今後の状況を鑑みながら、できるだけ入所者の方々とのコミュニケーションが、コロナの状況をよく見据えながら、取れるようにしていっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"せお委員","kind":"提案","question":"本日結論を出すで、不採択でお願いします。レクリエーションを区でも提案してというお話もあったのですが、何かいい事例、好事例とかがあれば、それを区内の介護施設とかに共有する場がもしあるようでしたら、そういったこともできればいいのかなと感じました。そこは要望させていただいて、理由とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"}]},{"id":"topic-05","title":"議案審査を再度行います。 (3)第６９号議案、令和４年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"議案審査を再度行います。 (3)第６９号議案、令和４年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"生活困窮者自立支援金の申請期間が延長されたということで、これまでも伺ってきているのですが、直近のところの実績を伺いたいので、緊急小口資金と総合支援資金の部分を聞かせていただけたらと思うのですが、それぞれの支援総額。緊急小口資金と総合支援資金と、この生活困窮者自立支援金の実績と支援総額それぞれを教えていただきたいのですが。","respondent":"櫻木生活福祉課長","answer":"社会福祉協議会から報告を受けている限りでの緊急小口資金・総合支援資金につきましては、令和４年度は緊急小口資金、３０３世帯、５,９６５万円、総合支援資金については２５６世帯で１億２,６７５万円と聞いております。","id":"exchange-022"},{"speaker":"石田委員","kind":"質問・要望","question":"今おっしゃったのは令和４年ということで、令和３年のところが分かったら教えていただきたいと思います。なので、恒久的な支援金にしていただきたいと思うのですが、そこの考えを改めて伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"延長につきましては、国において新型コロナウイルス感染症の状況や経済状況を踏まえて、今回、再度延長されたです。国においては年内に申請を打ち切る可能性という報道がありますが、いずれにせよ、今後についても国や都の動向を注視してまいりたいと考えています。","id":"exchange-023"},{"speaker":"石田委員","kind":"質問・要望","question":"それで、もう１個の電力・ガス・食料品等価格高騰緊急支援給付金ということで、非課税世帯への給付金がまた行われるということで、一安心されるかなと思うのですが、この支給対象者が前回、昨年から今年の初めにかけての住民税非課税世帯の臨時給付金の部分は、非課税世帯は４万２,０００世帯だったのですけれども、今回４万２００世帯なので、非課税世帯が少なくなった、減ったと見ていいのでしょうか。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"なので、大体９割程度の見込みで予算を要求させていただいているです。","id":"exchange-024"},{"speaker":"石田委員","kind":"質問","question":"ですが、４万２００世帯よりも多く非課税世帯はあるけれども、前回の実績からすると、４万２００世帯ぐらいで大丈夫ではないかということなのですね。前回の実績からということだったのですけれども、そこを今から改めるということにはならないのか、それ以上に申請が来た場合には、出すということにできるのか、そこを伺いたいと思います。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"それと、多く来た場合ということであれば、もちろん要件が満たされる方は給付を行うということでございまして、予算につきましては、その時点の状況で、また様々検討もしくはご提案等をさせていただければと思います。","id":"exchange-025"},{"speaker":"石田委員","kind":"質問・要望","question":"分かりました。ぜひ、多く来てしまった場合には、給付が漏れないようにしていただきたいと思います。今、前回の実績だとあったので、すみませんが、非課税世帯への給付金の実績、令和３年・４年のところと、家計急変世帯のところを教えてください。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"令和４年度につきまして、家計急変世帯に対する臨時特別給付金については６１２件あります。令和４年度の住民税非課税世帯等に対する臨時特別給付金につきましては、支給決定が６,７７７件あります。","id":"exchange-026"},{"speaker":"あくつ副委員長","kind":"確認","question":"ご相談があった方は、仕事はされていらっしゃるのですが、特殊な仕事で、コロナの時期で全く仕事がないという中で、職業相談とか求人相談、これは前にも議論があったところかもしれませんけれども、取りあえず今を乗り切りたいというところで、転職ということはあまり考えていらっしゃらない中で、ここについてのそういう方については、今、どうなのかというところを、もう一度確認させてください。","respondent":"櫻木生活福祉課長","answer":"就労要件、求職活動要件につきましては、そもそもの制度の趣旨としましては、総合支援資金をお借りになられて、それでもまだ生活困窮が続かれている方につきましては、給付金を一定期間支給しまして、その間に求職をしていただいた上で。","id":"exchange-027"},{"speaker":"あくつ副委員長","kind":"質問","question":"趣旨は分かりましたが、最後のところは、副業等について努力をされているという何らかの証明ができれば、この求職活動等要件に当たるということでよろしいですか。","respondent":"櫻木生活福祉課長","answer":"要件としましては、求職活動を通じて収入を増やす努力をしていただくということになっておりますので、こちらに書かれているような求人等の応募等もやっていただくということにはなっております。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/831364?Template=document&Id=3642#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":24713,"voices":114}},{"id":"r04-20221031-8","meetingId":"r04-cm10","date":"2022年10月31日","dateIso":"2022-10-31","committee":"建設委員会","time":"午前１０時００分～午後 ０時４０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件抜き出しています。","topics":[{"id":"topic-01","title":"令和４年陳情第５３号 小山三丁目第一、第二地区再開発に関連する陳情","agenda":"令和４年陳情第５３号 小山三丁目第一、第二地区再開発に関連する陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"地権者の方が、いろいろ話を聞いても答えてもらえないということで、そういった説明会、会議ですか。それと、参加組合員との契約の方法が違法というところも言われておりますけれども、この競争入札で本来やるべきだということで書かれておりますが、それが随意契約のうちの１つですか。この準備組合、決算報告がどうなっているかということも言われておりますので、そこの現状を伺いたいと思います。","respondent":"多並都市開発課長","answer":"法人というのは法律の規定に従って設立されるものであり、ここの準備組合につきましては、法律の規定によらない設立された団体ということで、先ほどご説明させていただいたとおりです。そういうことなので、登記等は必要ないというところになります。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"運営費のところの事業協力者と連携してやっているというところは、具体的にはどういったところになっているのか。入札契約のところでは、プロポーザルでやられているというご答弁だったと思うのですが、この陳情者の方はそうではないということだと思うのですが、そこのところをもう少し詳しく伺えればというふうに思います。その辺の話がよく分からなかったので、もう一度伺いたい。","respondent":"多並都市開発課長","answer":"事業協力者です。もう一度ご説明いたしますと、事業協力者と事業の推進に必要な金額を、準備組合が協定を結んでいます。その必要な金額を、総会の承認を経て、予算の範囲内で資金の立替えを行っているとそういう事業の仕組みで進んでいる運営方式です。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"暮らしが大きく変わっていくことになりますので、そうした権限を用いうる、その前段階の団体、そこに進めていく団体ということですから、やはりそこはしっかり住民の皆さんにも説明などを行って運営していくということが必要だというふうに思いますので、この準備組合をある程度チェックする仕組みというのが必要なのではないかというふうに思うのですけれども。","respondent":"多並都市開発課長","answer":"来年度の組合設立の事業の認可の予定ということですけれども、今のところ来年度と聞いておりますが、これにつきましては、詳細は今後協議もしくはお話を頂きながら、詳細を聞いていくことになるかと思います。","id":"exchange-003"},{"speaker":"のだて委員","kind":"確認","question":"準備組合のところでは、総会に参加して区が確認しているということですけれども、準備組合の中身は確認できるというふうに思うのですが、参加をされていない方の意見というのはどう反映されていくのか。あるいは賛成しているのか反対しているのかというところを確認していくというところは、この総会では具体的にやられないと思うのです。","respondent":"多並都市開発課長","answer":"そこまでのお話合いにつきましては、皆さんが自由に検討していただくところでもありますので、ここについては区がどれぐらいの割合であるかというのは、逐次確認するわけではなくて、ただ一般的には、総会等で報告されることがありますので。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、一般地権者が債務を負う可能性があるのかどうかというところも改めて伺いたいというふうに思います。それと、本組合については登記はされないということで、東京都が認可をするということになると思うのですけれども、そこの仕組みというのですか。登記をしなくてもいい理由を伺いたいと思います。","respondent":"多並都市開発課長","answer":"ただし、それに代わる、一般的にその資格証明と言われているようなものですけれども、それにつきましては、この法律の中で都知事が交付できることになっていまして、それが陳情にもありました、東京都のほうが説明した内容と合致するところです。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"本組合のところは、１個の組合しか存在し得ないから登記しなくていいということなのですかね。そこをもう少し詳しくご説明があれば伺いたいというふうに思います。それはもちろん財政面でもそうですし、精神的な負担にもなるというふうに思いますけれども、そういった方への支援というのは、どういったことをされているのか伺いたいというふうに思います。","respondent":"多並都市開発課長","answer":"もう１個の、要するに今住まわれている方が、再開発によって転出される、もしくは残りたいという方についてのご不安というお話かと思いますけれども、これにつきましてはまさに今事業計画を立てている中で、皆さんでお話し合いしていただいていますが、また。","id":"exchange-006"},{"speaker":"のだて委員","kind":"意見","question":"地権者の方にいろいろ支援ありますよということでしたけれども、これは前から言っております、自由に転出するか、高層マンションに残るかというのを選択できると言いますが、今のまま住み続けるという選択ができないということで、それを望んでいる方も多くいらっしゃいますので、そうしたことを無理やり進めるのはやめるべきだというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"芹澤委員","kind":"意見","question":"本日結論を出す、不採択でお願いいたします。毎回お話はしていますが、この再開発はあくまでも品川区が事業主体ではありませんので、地域の動向を見守っていただく、サポートする立場だと考えています。特に今回超法規的なというようなお話が何度か出ておりますが、今、理事者からのご説明の中で、特段法律的な瑕疵はないというようなお話もありましたので、今回は不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"こんの委員","kind":"質問","question":"今陳情については、本日結論を出すということでお願いしたいと思います。先ほどの質疑をお聞きしまして、そもそもこちらは任意団体であると。法的の登記は必要ない団体であるということも分かりました。この中で正確性に欠けるというようなところも見受けられたかなといったところで、今陳情については、不採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。いろいろ本組合、準備組合についても説明をしてほしいということで求めているものでありますので、ぜひ説明をしていただきたいと思いますし、本筋としては、住民を追い出し暮らしを壊す再開発は中止にしてほしいということですので、賛同いたしますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"松永委員","kind":"質問","question":"本日結論を出すということにいたします。そして、不採択といたします。先ほどもご説明があったように、地権者である住民に対してしっかりと保障されるということをお聞きし、そして法的には民意ということでありましたので、この件に関しては、不採択といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"の(2)羽田空港の機能強化","agenda":"の(2)羽田空港の機能強化","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"陳情者の方が、自らこの場で委員の皆さんに訴えたいということですので、これは質疑の前にぜひ聞いていただきたい。そうした意見も、陳述も踏まえて、質疑をすることができると思いますので、前にやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回のこの請願は、下校時の安全を求める会、また、品川の空を守る会の方から、１１０名の署名とともに提出されています。請願者の方に連絡をして、お話を伺いました。約２か月にわたり、町会長を回って、過半数を超える１０１名の方が署名をしてくれたそうです。そうした請願が今回出されましたけれども、区としてはどのように考えているのか、受け止めているのか、伺います。","respondent":"鈴木都市計画課長","answer":"これまで直近で言いますと１０月２５日時点、運用開始からこれまでに５３１件の声を頂いているです。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問・要望","question":"国に届けるということですけれども、それは当然届けていただきたいと思うのですが、国に届けるということは、区としてもこれに賛同しているということなのか、そこを伺いたいと思います。それをしっかり区としても、議会としても受け止めるべきだというふうに思うのですが、いかがでしょう。","respondent":"鈴木都市計画課長","answer":"今、それと、固定化回避に向けた取組みを進めていただいておりますが、こうした取組みの早期実施に向けて、今後も国に求めてまいりたいです。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"態度表明はされないということですが、これは区内全域にわたっての署名だと思いますので、それは重く受け止めていただきたいというふうに思います。こうした中で、海上ルートでも増便を行っていくことが可能だと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"先ほどの請願の中にもある、これはイコール海上ルートに戻して増便につながるかというのを国土交通省の職員が答えているかというところも確認したのですが、そうした回答をした事実はないということを聞いて確認しています。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"飛行機の運航間隔が短くなったというところで、増減にはつながらないというお話でしたけれども、滑走路に常に１機しかいられないということですかね。実際に頂いた資料の中で、この１分半を切ったりする着陸間隔のものもあるわけですよね。そういった中でこれがコンスタントになっていけば、しっかり増便できると思うのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"これは当初から、計画上そういう状態は飛行機の大きさですとか、あるいは、その日の天候ですとか、当然パイロットが違えばというところも含めて、そういう状態が発生するということは聞いておりますし、事実といいますか、「羽田空港のこれから」の資料の中には。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問","question":"もともとそういった計画だということですが、この新ルートが運用されたときから間隔を短くできるということになっておりますから、そういったことを含めてやっているのだというふうに思いますけれども、そうした中で今回縮めることができるようになったわけですから、この滑走路に１機しかいられないというのは安全上重要なことだというふうに私も思いますけれども、日本の運用ではその滑走路に着陸する前と。","respondent":"鈴木都市計画課長","answer":"繰り返しの答弁をすることになりますが、基本的に滑走路上の使用については、着陸および離陸を含めて、常に１機の状態というところで、着陸した航空機が横の誘導路に侵入して、滑走路上からなくなるまで、次の航空機は進入できないと。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問","question":"それで、既にこの運用を開始して２年以上がたっているわけですけれども、国によって固定化回避検討会というのが設置されました。Ｃ滑走路から都心を通って侵入してくる。そこの認識を伺いたいのと、今示されている２方式、これがどういった場合に運用されるのか。そして、この現在のルートというのは２方式が実施されれば運用されなくなるのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"委員からも先ほどご質問の中でご紹介いただきましたが、現在の滑走路の運用を前提としつつという、これは第１回目の検討会の前提条件の中でも、資料の中でも明確に述べておりますので、まさに委員がご紹介いただいた前提で取組みが進められているわけですが、区としますと。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"この２方式がどういう場合に運用されるのかということもお聞きしたので、それとあと、この２方式が実施されたら現在のルートは運用されなくなるのかということもお聞きしたので、ご答弁いただきたいと思います。それと、今のルートが固定化されないように求めてきたということですが、実際に今の検討が進んだら固定化すると私は思うのですが、いかがでしょう。","respondent":"鈴木都市計画課長","answer":"この飛行方式の検討が進んで、今現在運用されている羽田新ルートの運用とどういう変化といいますか、関わりといいますか、そうしたことが生まれてくるというのは、まだ具体的に１回目から５回目までの検討会の中では示されておりませんので、今後検討が進んでいく中で。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問","question":"今検討中なので答えられないということですが、この間の検討で示されてきたのは、１つは天候がありますよね。この２方式を実施する上で、１つは目視による着陸ですから、天候がよくて澄みとおった空気でなければできないということになります。","respondent":"鈴木都市計画課長","answer":"国のほうには具体的な取組内容を一刻も早く示していただきたいというところは、再三再四要望していますが、現在、安全評価等の検証・取組みを進めているというところで、具体的な内容はまだ定まっていないです。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"その時点でもはや固定化が始まっていると私は思いますので、直ちにこの運用停止を求めることが必要だというふうに思います。区は、この騒音あるいは落下物、その被害をなくすべきだというふうに考えているのか、伺いたいと思います。今回示されたエルデンは基準値内だというお話ですけれども、この基準値内ということで、問題ないと考えているのか、併せて伺います。","respondent":"鈴木都市計画課長","answer":"そうした中で、この羽田新飛行ルートというのは、国の責任において国策として進められているというところでございまして、そうした従前になかった航空機が飛ぶことによって起こる変化、あるいは区民への不安、そうしたものを解消していただくために。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"その中で月単位のエルデンの公表もぜひしていただきたいと思いますが、そこのところを１点伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"併せて、日々の航空機音については、新飛行ルート運用開始以降これまで継続して１機ごとの航空機騒音、航空機の音というのを公表していますので、区としてはこの年間エルデンとともに、継続し、区民の方に公表してまいりたいです。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"それは実際の影響を見る上で、いろいろな情報を出していくというのが重要だというふうに思いますので、これは要望しておきたいというふうに思います。様々なこうした被害がある中で、今回請願も出され、そして運用停止もできるというところで、それにも関わらずこの新ルートが運用されているということですから、この請願にあるとおり、この意見書を提出していくべきだと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"松永委員","kind":"質問","question":"私からは、先ほどのだて委員からありましたが、改めてですけれども、この後方乱気流管制方式が、２０２０年１１月５日に規定が改正されたとあります。この請願に「ほか１１０名」と書かれておりますが、その中で、町会自治会長が１０１名と伺っております。そこで、住民投票も含め、区民に意見を問う必要があると考えておりますが、区の見解をお伺いいたします。","respondent":"鈴木都市計画課長","answer":"この後方乱気流の運用によって、海上ルートに戻した場合に増便が可能かどうかというご質問ですが、これも先ほどご答弁させていただいた内容の繰り返しになりますが、上空での飛行機の間隔よりも、羽田の増便については、滑走路での占有時間といいますか、滑走路上では。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問","question":"この空港の占有時間というのが、滑走路に１機しかいられないというのが、今の議論の中でキーポイントになっていると思うのですが、空港の占有時間というのは１機当たり何分になるのか伺います。","respondent":"鈴木都市計画課長","answer":"今のような形で今回国のほうに確認をしておりませんが、基本的に先ほどからご答弁申し上げているように、滑走路については、着陸、あるいは離陸を含めて、必ず１機しかその滑走路上は存在できないですので、航空機の大きさですとか。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"分かりました。ではその前に。もし、継続審査をお考えの委員がいるとするならば、継続にすべきではないということを言っておきたいと思います。なので、ここでぜひ態度、結論を出していただきたいというふうに思うのですけれども、少なくとも４月までには第４回定例会、第１回定例会とあるわけですので、その中で結論を示すべきだというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、請願者の方の声を直接聞くということが重要だと、議会としても、特に町会長１０１名に署名していただいたということもありますので、直接声を聞くということが重要だと思いますので、意見陳述、ぜひやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"芹澤委員","kind":"質問・要望","question":"羽田新ルートに関しては、我々自民党も含めて、固定化の回避を強く要望してきたところで、そこで今、固定化回避検討会が行われていると思います。一方、落下物等に関しては、あってはならない事態だと思っていますので、これは国に引き続き厳格な体制を取っていただいて、その情報提供というのは、国民区民に、品川区に下ろしていただけるようにこちらも要望していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"こんの委員","kind":"確認","question":"１つには、今の質疑のやり取りから、事実に対しての認識が異なっている箇所が数か所確認されたと思います。２つ目にはこれまで町会長をはじめ区民の皆様からの不安払拭のために、区議会全会一致で決議した意見書は重く受け止めております。この行方を議会としてもきちんと注視していく必要があると考えることから、本請願については、継続とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"のだて委員","kind":"意見","question":"結論を出すということで、採択を主張します。様々質疑をさせていただいた中で、海上ルートでも実施可能だと私は思います。そうした中で、住民への被害は、騒音、落下物などが行われている。こうしたものを直ちに停止するということで、区議会としても意見書を提出すべきだというふうに思いますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"松永委員","kind":"意見","question":"先ほどの質疑の中でもありましたが、騒音や落下物の危険性がある羽田新ルートに関しましては、私は、事故や事件が起こる前にもう飛ばさないということをお伝えして、この請願については採択という態度を示します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"横山委員","kind":"質問・要望","question":"私は継続でお願いいたします。事実と異なる部分があることを確認いたしました。２点、コミュケーションに関してアップデートする必要性を、区から国と関連部署、近隣区市に伝えていただきますよう要望いたします。１点目は区民の方々に対して、国からよりきめ細やかで丁寧な伝わる説明と、伝わっているかどうかを確認し合ってほしいということを強く要望いたします。」とあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"}]},{"id":"topic-03","title":"品川区まちづくりマスタープラン改定に向けた検討状況","agenda":"品川区まちづくりマスタープラン改定に向けた検討状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回第５回目の改定委員会が行われて、５章６章も冊子となって出てきたというところで、今回の改定で、主に５章６章、前回と変わったところを伺いたいというふうに思います。それと、オープンハウス型説明会が行われて、来場者の方が合計で３５９名。意見がいろいろ３つの方法を合わせると約１３０から４０件あったというところで、意見を幾つか、どういった意見があったのかご紹介いただければと思います。","respondent":"鈴木都市計画課長","answer":"中身の記載を充実といいますか、具体的な内容を書いて今回お示ししているですので、大きな変更点は５章６章に関してはございません。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回のまちづくりマスタープランの改定に当たって、前回も言ったところではありますけれども、補助２９号線とか、補助２８号線、放射２号線の特定整備路線を延焼遮断として位置づけているということですとか、あと再開発についても、先ほどのご説明の中でもありました武蔵小山ですとか、大井町、広町のところなど様々進めていくということで、今回北品川のところも駅前の広場を進めていくということですが。","respondent":"鈴木都市計画課長","answer":"初めのご質問ですが、現行計画から今改定ということで、今後１０年間の計画ということで今検討を進めているわけですけれども、まちづくりを進めていくに当たっては、再開発だけでない様々な手法でまちづくりを進めていくというところ。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"地域特性によって、いろいろなまちづくりの手法があるというお話でした。それと、都市計画道路の整備率のところでは、２０３２年、１０年後、７８％ということですから、これが目標値ということですので、特定整備路線は完成しないのだろうなと私は思います。そうした中で、住民を追い出して生活を壊していくという、こうした事業はやめるべきだということを求めたいと思いますけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"当然これ以外にも事業決定されていない、あるいは優先整備路線に入ってきていない道路等もありますので、そうした道路はまだ入っていない形でのパーセンテージというところで、ご照会の中で優先整備路線の整備がもうなかなかできないというお話も頂きましたが。","id":"exchange-035"},{"speaker":"横山委員","kind":"質問・要望","question":"こちらのオープンハウス型のスクエア荏原、数が少ないのはどうしたのだろうというふうに思っていたのですけれども、先ほどご説明を頂きまして、天候不良ということで理解いたしました。こちらですけれども、何ページのどの部分に、この改訂素案に含まれる内容ということで書いてあるのでしょうか。各地域の中学生向けの説明というところは、反映されているという理解でよろしいでしょうか。","respondent":"鈴木都市計画課長","answer":"オープンハウス型説明会の件で幾つかご質問いただきましたが、まず、この４会場での子ども等の方のご意見ですが、例えばしながわ区民公園のほうでは、生徒が、公園利用の目的で大勢の集団で通りかかったところにお声かけをして、実際お寄りいただいて。","id":"exchange-036"},{"speaker":"横山委員","kind":"質問・要望","question":"ほかの場所は１階のスペースが多いものですから、例えば４階ではなくて１階のスペースであったり、または駅にもう少し近い場所で検討していただくとかということを、また次の何かの段階では検討していただきたいなというふうに思っておりましたので、こちらは要望でお伝えをします。子ども・若者の意見ということで、実際にご意見があったのは１件であったというお話でした。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"こんの委員","kind":"質問","question":"第６章のところを伺いたいと思います。そして、これ以前の１０年前と比べてのことが示されているのですが、その前です。いわゆる平成１３年。最初の平成１３年に策定された、今回に至るまでの、いわゆる達成率というのでしょうか。どれぐらいこの目標に対して、プランに対して、どれぐらい全体的に実効性が伴ってきたのか、その辺を伺いたいというふうに思います。","respondent":"鈴木都市計画課長","answer":"特に、直近の現行計画、さらに今の改定計画の中では、さらに地域資源、水辺ですとか、緑ですとか、そうした地域資源を活用した取組みというのは、今しっかり打ち出しを検討しているようなところです。","id":"exchange-038"},{"speaker":"こんの委員","kind":"質問・要望","question":"例えば「歩きやすいまちづくり」というぼやっとした、今プランですからそういう表現ですけれども、それがどういったところできちんと区民の方の生活環境を向上させていくかというところというのは、非常に見えにくいというか、分かりにくい部分もあったりするので、いわゆるそういう細かい点についても、ぜひ実効性を伴う１０年間にしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"芹澤委員","kind":"質問・要望","question":"何点かお伺いしますが、オープンハウス型説明会の資料の２ページですか。品川区の都市景観分野のところ、品川の個性を残し、歩いて楽しいまちにしてほしいと。２点伺いますが、まず、個性というのを今区としてはどこと捉えていらっしゃるのか。ハード面なのかソフト面なのか。","respondent":"鈴木都市計画課長","answer":"資料２ページの都市景観分野のところですが、景観分野で品川の個性を残しというところ、ハード面、ソフト面いろいろあろうかと思うのですが、区としての今の受け止めとしては、例えば旧東海道、これは非常に昔の町並み、景観的にしっかり残しながら、この地域資源を活用しながら。","id":"exchange-040"},{"speaker":"松永委員","kind":"質問","question":"私からは１点だけですが、第４章の４－１７の可動式ホーム柵についてですけれども、地元駅であります立会川駅では人身事故が立て続けに起こっておりました。今現在、分かる範囲でいいのですが、そうしたホーム柵の計画等というのはあるのでしょうか。未導入駅については、どのように進められていくのか、お知らせいただければと思います。","respondent":"鈴木都市計画課長","answer":"立体化を進めていく北品川駅、そこについてはその中で整備が進んでいくものというふうな理解です。今ご質問頂いた立会川駅については、京浜急行電鉄の計画上にはまだ載ってきていないです。それから２点目のご質問が。","id":"exchange-041"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひともこうした要望というかご意見もあるので、ぜひ、そうした様々な課題に取り組んでいただいて、この可動式ホーム柵はいろいろ種類があると思うのですよね。そうしたところも含めて、しっかりと進めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"西村副委員長","kind":"質問","question":"１点だけ最後にすみません、お伺いをさせてください。２－８のところで、人口の推移について、これまでとこれからについて少し伺えたらと思います。この中で、人口世代間のバランスが、１０年前と比較して品川区はどうなっているのかなということと、今後どのようになっていくと予想しておられるのか、伺えればと思います。","respondent":"鈴木都市計画課長","answer":"具体的に今手持ちに子育て世帯の状況、特に子育て世代という形でのデータ取りはしていないのですが、年代別の人口の増加傾向というのは細かいものがなくて申し訳ないですが、トレンドとしては少子高齢化が今後も進んでいくというような認識です。","id":"exchange-043"},{"speaker":"西村副委員長","kind":"質問","question":"先日過疎認定を受けた町長のお話を伺いまして、改めて品川区を外側からも見てみたいなと思ってお伺いをさせていただきました。何となく肌感覚ですと、子育て世帯が増えているような気もするのですけれど、具体的にまた改めて伺えればと思いますので、品川区ならではの世代間のバランスに合わせた積極的な取組みをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/979224?Template=document&Id=4362#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":43095,"voices":138}}]);
